INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20399576700', 'Filtro Ar Cabine Kia Cerato 2009 a 2013 - 1353561 - AKX1984', 'Filtro Ar Cabine Kia Cerato 2009 a 2013 1353561 AKX1984 (Sedan) - 1.6 16V Gasolina - Automático / Mecânico - (Sem carvão) Os filtros do ar para cabine são produzidos com fibras carregadas eletrostaticamente. Este filtros possuem camadas protegidas de um lado por um pré-filtro para reter partículas maiores. Do lado oposto possui uma camada de proteção a danos ao filtro.A função do meio filtrante é remover a maior quantidade possível de contaminantes do sistema do ar, oferecendo o mínimo de restrição ao fluxo de ar.', 20.16, 20.16, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/br-11134201-820me-mr0fer7rvevbff', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F20399576700', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22198159834', 'Barra de Proteína Caramel Protein 45g Display C/12 Un - Nutrata', 'O Combo Perfeito: Chocolate + Amendoim + Caramelo + Whey Protein Nutrata Caramel é uma barra de proteína com recheio macio de caramelo, amendoim crocante e uma incrível cobertura de chocolate. Deliciosa e muito mais nutritiva do que um chocolate comum, é perfeita para o dia a dia. Experimente nossas duas diferentes versões DESCUBRA O SABOR IRRESISTÍVEL DO CHOCOLATE PROTEICO COM AMENDOIM DA NUTRATA! 10 g de proteínas; Deliciosa cobertura de chocolate; Recheio de caramelo macio e amendoim crocante; Blend de proteínas de alto valor biológico; Com whey protein; 50% menos carboidratos que um chocolate comum; 78% menos açúcar que um chocolate comum; 0 gordura trans; Sem adoçantes artificiais. QUANDO CONSUMIR A NUTRATA CARAMEL? Antes do treino; Para saciar a fome entre as refeições; Para aumentar a energia quando bater o cansaço; Como uma sobremesa. Nutreline Distribuidora', 109.9, 74.9, NULL, 'Food & Beverages > Breakfast Cereals & Spread > Breakfast Bar', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m533ml8dyzps95', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F965164614%2F22198159834', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19399601463', 'Calça Legging Infantil Moletom Stretch Flanelado Malwee Kids', 'Calça legging infantil confeccionada em moletom stretch flanelado. Modelagem com caimento ajustado e modelado no corpo, seu comprimento vai até o pé. Modelo possui cintura média e cós aplicado com elástico embutido. Os básicos da Malwee Kids são essenciais para acompanhar o crescimento das crianças, são peças versáteis e duráveis além de terem a melhor qualidade do mercado brasileiro. O moletom flanelado tem o diferencial de ter a felpa internamente e também conta com a fibra de elastano, garantindo maior conforto e liberdade de movimentos. Um item prático e perfeito para os momentos de lazer da sua pequena. Combine com blusa básica Malwee Kids e tênis esportivo! Modelagem: Legging Cós: Aplicado com elástico embutido', 39.9, 35.91, NULL, 'Baby & Kids Fashion > Girl Clothes > Bottoms', 'https://cf.shopee.com.br/file/sg-11134201-7rbkq-m62z8xdp9pzyd7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1264817414%2F19399601463', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58255161119', 'Lampada Leds Farol Alto Baixo Milha E Aux Cross Fox + Brinde', 'Descrição KIT COMPLETO DE LAMPADAS SUPER LED VW CROSS FOX 2003 A 2009 FAROL ALTO BAIXO E AUXILIAR E MILHA + BRINDE ATENÇÃO ANTES DA COMPRA ( ESTE KIT SERVE SOMENTE PARA CROSS FOX COM FAROL FOCO DUPLO ) SEM NECESSIDADE DE CORTAR FIOS , CHICOTE VEM PRONTO PARA SE CONECTAR AO SISTEMA ORIGINAL DO VEICULO Este kit super LED emite luz branca azulada na tonalidade de 6000K com 2200LM, causando o mesmo efeito do xenon, mas não são proibidas. Além do destaque no visual do carro, essa luz ilumina bem a via, permitindo que o motorista tenha ótima visibilidade. Encaixe H7 H1 H3 H3 6000K (Kelvins) Extremamente Branca Base de Lâmpada em Alumínio Não Precisa de Reator ou Cooler para Funcionamento Eficiência de 2800 Lumens ( CADA LAMPADA ) TOTAL DE 5600 LUMENS O KIT Vida Útil de: 50000 – 100000 Horas Consumo: 40W Proporciona Melhora na Visualização de Placas e Sinalizações Economiza a Bateria Voltagem: 12V e 24V Voltagem Compatível com Carros e Caminhões Conteúdo da Embalagem: 2 Super LED Headlight H7 FAROL BAIXO 2 Super LED Headlight H1 FAROL ALTO 2 Super LED Headlight H3 FAROL AUXILIAR 2 Super LED Headlight H3 FAROL DE MILHA 1 PAR DE LAMPADAS DE LED PARA LUZ DE POSIÇÃO. 8 Chicotes APLICAÇÃO: CROSS FOX 2003 A 2009 Importante: Garantia de 6 MESES Valor do Kit. Perguntas e respostas Qual informação você precisa?', 225.93, 225.93, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Lighting', 'https://cf.shopee.com.br/file/sg-11134201-825zw-mkmy6k2bz8che4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1310462644%2F58255161119', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58207907912', 'Chinelo Oakley Crowd Masculino Adulto', 'Chinelo Oakley Crowd – Conforto bruto, estilo discreto e aquela pegada resistente que só a Oakley entrega. Esse modelo chega com um visual clean em tom neutro, perfeito pra quem quer algo estiloso sem chamar atenção demais. As tiras largas em material emborrachado garantem firmeza no pé, enquanto o solado texturizado dá tração até no piso molhado. A palmilha anatômica é macia, tem apoio na medida certa e ainda vem com o clássico logo da Oakley marcado. É aquele chinelo pra usar o dia inteiro sem reclamar: Leve, resistente e confortável. Vai da praia ao rolê com a mesma vibe relaxada — e sem perder o charme. Destaques: Palmilha anatômica super confortável Tiras emborrachadas com detalhamento em alto-relevo Solado com boa aderência Design minimalista com logo Oakley Leve, resistente e pronto pra rotina', 174.99, 139.99, NULL, 'Men Shoes > Sandals & Flip Flops > Flip Flops', 'https://cf.shopee.com.br/file/br-11134207-820mb-mpts4vnk6ozmbf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1490043415%2F58207907912', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23836496506', 'Sabonete Espuma Refil Pitanga 800ml Exaccta Plus Trilha', 'Sabonete Espuma Refil Pitanga 800ml Exaccta Plus Trilha Possui ativos emolientes com ação protetora, hidratante e calmante. Indicado para ser usado em indústrias, restaurantes, escritórios, clínicas, academias, rodoviárias, salões, colégios, clubes, shoppings e demais estabelecimentos públicos. Produto biodegradável promovendo a limpeza da pele, devolvendo-lhe a umidade e oleosidade natural. Sendo também um excelente produto para uso contínuo. Possui o Sistema de Refil Eco Fácil, facilitando o modo de uso e o descarte, além de proteger o sistema da ventosa contra contaminações. É só retirar e usar. Utilização: Saboneteiras com sistema para refil Eco Fácil de 800 ml com válvula fixa na saboneteira, linha Exaccta Plus ou linha Elisa. Saboneteiras com Válvula Compatíveis: Cód. de Fábrica: 107533 - EL-SABFE2 - Saboneteira Espuma com Válvula Branca e Preta Elisa Cód. de Fábrica: 107540 - EL-SABVG14 - Dispenser Saboneteira Espuma com Válvula Branca e Preta Elisa Cód. de Fábrica: 107541 - EL-SABEBP - Saboneteira Espuma com Válvula Branca e Preta Elisa Cód. de Fábrica: 105774 - ELP-22SABFE - Saboneteira Espuma com Válvula Branco Cristal Elisa Plus Cód. de Fábrica: 105775 - ELP-23SABVG - Saboneteira Espuma com Válvula Grande Branco Cristal Elisa Plus Cor: Vermelho Fragrância: Pitanga Embalagem: 01 Refil com 800ml', 17.95, 17.95, NULL, 'Beauty > Bath & Body Care > Body Wash & Soap', 'https://cf.shopee.com.br/file/sg-11134201-824ih-mfmtpjnbqk96da', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F946161700%2F23836496506', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58204365555', 'Roda Livre Camaleão Cassete Catraca GTS 12V 11x50 K7 Bicicleta MTB', 'Seja Bem-Vindo(a) ao nosso canal de vendas de Peças de Bicicletas. Dê um upgrade no seu MTB ou XC com o Cassete GTS de 12 velocidades! Com ampla relação de 11x50 dentes, ele proporciona máxima potência e versatilidade para encarar qualquer terreno, desde subidas desafiadoras até descidas radicais. Feito com materiais de alta qualidade, combina durabilidade e leveza para um desempenho superior. Compatível com freehub padrão Shimano, sua instalação é prática e rápida. BENEFÍCIOS: > Trocas precisas e suaves – Maior controle e desempenho em qualquer trilha. > Leve e resistente – Aço e alumínio garantem durabilidade sem comprometer a leveza. > Fácil instalação – Compatível com freehub Shimano, simplifica a substituição. ️ Marca: GTS Características: > Modelo: Cassete 12V 11x50T > Cor: camaleão. > Material: Aço e Alumínio > Escalonamento: 11-13-15-17-19-21-24-28-32-36-42-50 > Peso aproximado: 780g ℹ IMPORTANTE: Compra Segura Com Garantia Shopee. Somos Vendedor Indicado Pela Shopee. Enviamos sua compra rápido.', 189.91, 189.91, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Cycling', 'https://cf.shopee.com.br/file/sg-11134201-8260u-mk3wvsx4b282f4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F333705502%2F58204365555', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22697123572', 'Parafusadeira De Impacto 2 Baterias 18v Dtd152 Makita Bivolt', 'DISTRIBUÍDO POR C-JAÚ FERRAMENTAS CARACTERÍSTICAS Resistente à água e poeira com a tecnologia XPT. Velocidade variável. Rotação reversível. Freio instantâneo. Iluminação de trabalho. ESPECIFICAÇÕES Rotações por minuto: 0 - 2.900 Impactos por minuto: 0 - 3.500 Parafuso Máquina: M4 - M8 Parafuso Padrão: M5 - M16 Parafuso de alta tensão: M5 - M12 Torque: 165N.m Encaixe: Sextavado 1/4" Dimensões(C x L x A): 137 x 79 x 220mm Peso: 1.2kg Acompanha: 2 Baterias 18v 3Ah 1 Carregador DC18RC Bivolt', 1914.0, 1820.0, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lnn8l2jsf9an89', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F380456261%2F22697123572', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18897517309', 'Lixadeira Esmerilhadeira Bateria 4ah Sbg700 Stanley Sem carregador', 'DISTRIBUÍDO POR C-JAÚ FERRAMENTAS NÃO ACOMPANHA CARREGADOR Lixadeira Esmerilhadeira 5" A Bateria 20v 4ah SBG700 Stanley S/ Carvão (Brushless) Sem Carregador Novo sistema v20, ferramentas sem fio, potentes bateria intercambiável. As novas baterias de 20v podem ser usadas com todas as novas ferramentas do sistema v20. Combine-os para obter a potência necessária para seus projetos. Esmerilhadeira angular sem fio 4.1/2 polegadas (115mm) e 5 polegadas (125mm), brushless, sistema 20v com bateria de íon de lítio. As novas baterias v20 íon de lítio oferecem todo o desempenho que você precisa para um longo dia de trabalho e muito mais, porque você precisa contar com o bom funcionamento da sua ferramentas. Tecnologia aprimorada, maior vida útil da bateria, mínimo descarregamento automático e sem efeito memória. Brushless: a linha v20 inclui ferramentas com motores sem escovas de carvão (brushless) que utiliza um dispositivo eletrônico que altera continuamente a fase elétrica para manter o motor funcionando em vez de escovas de carvão. O sistema brushless dá às ferramentas vantagens significativas em relação aos modelos com escova de carvão. Mais potência os motores sem escova não perdem energia por atrito ou calor, fornecendo mais potência para aplicações exigentes. Maior duração o controlador eletrônico, em vez de escovas de carvão, consome menos energia da bateria, permitindo que a ferramenta funcione por mais tempo em comparação a um modelo com escova de carvão. Motor compacto as ferramentas sem escova de carvão são mais compactas devido ao design menor do motor, tornando-as mais leves e fáceis de usar em aplicações de difícil acesso. Com o novo sistema v20 faça sua melhor obra. 2 anos de garantia. Recursos e Benefícios BRUSHLESS MOTOR SEM ESCOVA Perfeito tempo de uso e alta e ciência. Reduz os custos de manutenção DESIGN ERGONÔMICO E LEVE Para maior conforto BATERIA 20VÍON DE LÍTIO BLOQUEIO DO EIXO Para facilidade de troca do disco INTERRUPTOR COM TRAVA DE SEGURANÇA Evita inicialização não intencional. Aumentando a segurança do usuário GUARDA DE PROTEÇÃO SEM CHAVE Ajuste rápido da guarda de acordo com a aplicação de corte ou desbaste EMPUNHADURA LATERAL DE 3 POSIÇÕES (COM PORTA CHAVE) Posicione de acordo com a aplicação, aumentando o conforto e a segurança do usuário PARADA RÁPIDA DO DISCOO interruptor se desliga em 3 seg para maior segurança do usuário ESPECIFICAÇÕES SBG700 Velocidade sem carga 0 - 8.000 RPM Tamanho do disco 4.1/2 polegadas (115mm) e 5 polegadas (125mm) Vibração 4,5m/s2 Indicador de carga Sim (bateria) Interruptor com gatilho Tipo alavanca Peso 1,85 Kg INCLUI (1) ESMERILHADEIRA ANGULAR 4.1/2 polegadas (115mm) E 5 polegadas (125mm) BRUSHLESS 20V (SBG700) (1) BATERIA DE LITIO 20 VOLTS 4.0 AH SB204 STANLEY', 1332.0, 1191.0, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lnwwjx2xjx618c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F380456261%2F18897517309', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23698019217', 'Kit Bico Injetor VOYAGE 2009/2017 - 36930 - 1229', 'Kit Bico Injetor VOYAGE 2009/2017 1.0 - (Multi Point - (4 Pares O''rings) (Ø Interno - 13,80mm) (Ø Secção - 2,62mm) (Ø Interno - 7,52mm) (Ø Secção - 3,53mm) Tem a finalidade de evitar entupimento do bico injetor devido às impurezas e contaminações do combustível. Outra função é vedar a entrada falsa de ar no coletor de admissão evitando vazamentos. Ao fazer a limpeza do bico injetor, devemos trocar o(s) filtro(s) e os anéis, pois eles retêm as impurezas que diminuem o volume de combustível injetado provocando assim, algumas irregularidades como perda de potência, dificuldade na partida e funcionamento irregular do motor.', 29.43, 29.43, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Electrical System', 'https://cf.shopee.com.br/file/sg-11134201-7reo5-m2f73i5ob06bbd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23698019217', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23499195678', 'Kit Salon Line SOS Hidratação Turbinado Shampoo + Condicionador + Máscara', 'Kit Salon Line SOS Hidratação Turbinado Shampoo 1L + Condicionador 1L + Máscara 1kg Kit completo Salon Line S.O.S Hidratação Turbinado para nutrição e reparação profunda. Fórmula com óleo de rícino, manteiga de karité e azeite de oliva que devolve força, maciez e brilho aos fios danificados desde a primeira aplicação. Ideal para tratamento intensivo em casa com máscara concentrada de 1kg para resultado profissional. Tratamento intensivo com óleo de rícino, manteiga de karité e azeite de oliva para fios mais fortes e brilhantes. Máscara concentrada 1kg para hidratação profunda e resultado profissional em poucos minutos. Modo de uso Aplique o shampoo nos cabelos úmidos, massageie e enxágue. Use o condicionador para desembaraçar. Retire o excesso de água e aplique a máscara do comprimento às pontas por 3 minutos. Enxágue abundantemente. 1- Lavar: Aplique o shampoo no couro cabeludo e fios úmidos, massageie suavemente e enxágue. 2- Condicionar: Distribua o condicionador do comprimento às pontas, deixe agir rapidamente e enxágue para desembaraçar. 3- Hidratar: Retire o excesso de água e aplique a máscara concentrada do comprimento às pontas, deixe por 3 minutos. 4- Enxaguar: Enxágue abundantemente até remover todo o produto e finalize conforme desejar. Características e benefícios Combinação poderosa para tratar fios danificados: Limpeza suave do shampoo, condicionamento desembaraçante e máscara concentrada para hidratação intensa. Ingredientes nutritivos restauram a fibra capilar, aumentam resistência, devolvem brilho e promovem maciez duradoura, com fórmula sem parabenos. 1- Nutrição Intensa: Óleo de rícino penetra na fibra capilar, fortalecendo e recuperando a resistência dos fios danificados. 2- Hidratação Profunda: Máscara concentrada 1kg proporciona reposição de água e lipídios, deixando os fios macios e com brilho prolongado. 3- Fórmula Suave: Sem parabenos e com ativos nutritivos que cuidam do couro cabeludo e dos fios sem agredir. 4- Embalagem Prática: Frascos com tampas flip-top e pote da máscara que facilitam a aplicação e conservação do produto. Especificações Técnicas - Marca: Salon Line - Indicação: Cabelos danificados - Shampoo: 1L - Condicionador: 1L - Máscara: 1kg - Ativos: Óleo de rícino, Manteiga de karité, Azeite de oliva - Sem parabenos - Volumes generosos: Shampoo 1L, condicionador 1L e máscara 1kg para tratamento completo em casa. Sobre a marca Salon Line Salon Line é referência nacional em cuidados capilares, oferecendo fórmulas eficazes e soluções para diversas necessidades com foco em saúde e resultado visível. - Qualidade de Processos: Produção com padrões rigorosos de qualidade e controle para garantir performance, segurança e consistência em cada fórmula. - Produtos Eficazes: Fórmulas desenvolvidas com ativos selecionados que entregam resultados visíveis e cuidados específicos para cada tipo de cabelo. - Compromisso Sustentável: Adoção de práticas sustentáveis e iniciativas para reduzir o impacto ambiental, alinhadas à responsabilidade social.', 111.98, 111.98, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-822zq-mhwc2fvjozd1c4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1587699638%2F23499195678', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '53863279000', 'Mini Rodo Esfregão Absorvente Portátil Limpeza Multifuncional Mop de Mesa Limpeza Esponja Duhome', '🧼 Mini Rodo Mop Mágico com Esponja PVA Multiuso Deixe a limpeza mais rápida e prática com o Mini Rodo Mop Mágico! Sua esponja de PVA de alta absorção remove água, poeira e sujeiras com facilidade, sem riscar as superfícies. Compacto e leve, é ideal para limpar vidros, espelhos, pias, bancadas, azulejos, box de banheiro e muito mais. ✨ Benefícios ✔ Alta absorção de água ✔ Limpeza rápida e eficiente ✔ Remove água e sujeira sem deixar marcas ✔ Compacto, leve e fácil de guardar ✔ Fácil de lavar e reutilizar ✔ Ideal para uso doméstico 📦 Especificações Material: Plástico + Esponja PVA Tipo: Mini Rodo Mop de Limpeza Cor: Enviada conforme disponibilidade em estoque Uso: Vidros, espelhos, pias, bancadas, azulejos, box, janelas e outras superfícies lisas 📌 Conteúdo da Embalagem 1 Mini Rodo Mop Mágico com Esponja PVA TAMANHO - 15X13X3CM Praticidade e eficiência para manter sua casa sempre limpa!', 39.9, 22.9, NULL, 'Home & Living > Home Care Supplies > Mops', 'https://cf.shopee.com.br/file/br-11134207-820m9-mq6k6v3ar6kj66', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436723291%2F53863279000', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58052698928', 'Tempero Olivier', 'Tempero Olivier Mistura aromática e equilibrada de ervas e especiarias, ideal para realçar o sabor de carnes, legumes, molhos e diversos pratos. Prático e versátil, traz um toque especial e sofisticado às suas receitas. Ingredientes: Cebola, salsa desidratada, alho desidratado, cenoura, açafrão,manjerona lemon pepper, caldo de galinha e óleo de soja. ALÉRGICOS: PODE CONTER TRAÇOS DE GLÚTEN, LEITE, SOJA, AMENDOIM E CACAU POR CONTAMINAÇÃO CRUZADA. INFORMAÇÕES ADICIONAIS - PODE HAVER VARIAÇÃO DE COR DEPENDENDO DO LOTE. - EMBALAGEM MERAMENTE ILUSTRATIVA.', 31.56, 31.56, NULL, 'Food & Beverages > Cooking Essentials > Seasonings & Condiments', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mhxmsi7jpxc2c0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F657120589%2F58052698928', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23198243850', 'MOLAS DA SAPATA COURIER 1.4 1997 1998 1999 2000 2001 - 94897 - 325', 'MOLAS DA SAPATA COURIER 1.4 1997 1998 1999 2000 2001 CECCARELLI 325 - COURIER 97/13 1.3/1.4/1.6 - (2 RODAS - TRASEIRA) (SISTEMA VARGA)Função: É responsável pelo retorno das sapatas após a frenagem. Aplicação: Normalmente nas rodas traseiras. Mas pode ser aplicado nas rodas dianteiras em modelos com freio a tambor dianteiro. Funcionamento: Trabalha exercendo força contrária ao cilindro de roda. Também é responsável pela fixação e alinhamento das sapatas no espelho. Características: Molas fabricadas em aço com alto teor de carbono (SAE 1070)', 38.34, 38.34, NULL, 'Automobiles > Automobile Spare Parts > Brake System', 'https://cf.shopee.com.br/file/sg-11134201-7rd3q-m6u57gvsw0152c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23198243850', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22898228014', 'Válvula Termostática PALIO 1.6 16V COM AR 1996/2005 - 71866 - 336788', 'Válvula Termostática PALIO 1.6 16V COM AR 1996/2005 1.6 16v - Com Ar - 1 Furo - Kit - Flange + Válvula Termostática - 88º / VALCLEI 336788 A válvula termostática é uma peça importantíssima do sistema de arrefecimento dos carros. Ela controla a temperatura do motor. Quando o motor está frio, ela fica fechada, fazendo com que o líquido de arrefecimento (água e aditivo) volte para o bloco do motor. A partir de uma determinada temperatura, cerca de 90 graus, ela se abre, permitindo a passagem do líquido para o radiador para que ele seja refrigerado e volte para o bloco. A manutenção preventiva a cada 30 mil km ou menos.', 388.21, 388.21, NULL, 'Automobiles > Automobile Spare Parts > Radiators, Engine Cooling & Climate Control', 'https://cf.shopee.com.br/file/sg-11134201-7rbn2-lmt49zkwlyita9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22898228014', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20598920774', 'Kit 2 Suporte Banheiro Porta Shampoo e Saboneteira Preto', 'Kit 2 Suporte Banheiro Porta Shampoo e Saboneteira Preto – Sem Furo Transforme seu banheiro em um ambiente moderno, organizado e sofisticado com o Kit 2 Suportes Porta Shampoo e Saboneteira Preto. Ideal para quem busca praticidade sem abrir mão do design, ele dispensa furos e ferramentas, preservando suas paredes e garantindo uma instalação rápida e segura. ⭐ Destaques do Produto 🚿 Instalação sem furo – não danifica a parede 🛠️ Fixação simples e prática – basta aplicar pressão 🖤 Design moderno e elegante – valoriza qualquer banheiro 💧 Fundo vazado – facilita a drenagem da água e evita acúmulo de sujeira 🛡️ Material resistente à umidade – não enferruja e não descasca 🌱 Metal de alta qualidade – durável, atóxico e sem odor 🧱 Material e Acabamento • Estrutura em metal de alta qualidade • Pintura resistente à umidade, ideal para áreas molhadas • Acabamento preto moderno e sofisticado 🧴 Ideal para Organizar ✔ Shampoo ✔ Condicionador ✔ Sabonete líquido ✔ Cremes e itens de higiene Perfeito para banheiros, lavabos e até cozinhas, trazendo mais praticidade ao dia a dia. 📦 Conteúdo da Embalagem ✔ 2 Suportes Porta Shampoo / Saboneteira Preto', 135.83, 135.83, NULL, 'Home & Living > Furniture > Shelves & Racks', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mk2gle85kjcyd6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F408653169%2F20598920774', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23993887709', 'Frigideira Antiaderente para Ovo Oliveira Grafite 12cm', 'Desperte o Chef que Há em Você com a Frigideira Antiaderente para Ovo Oliveira Grafite 12cm!Na busca pela culinária perfeita, cada utensílio na cozinha desempenha um papel crucial. A Frigideira Antiaderente para Ovo Oliveira Grafite 12cm é a escolha ideal para quem busca praticidade e resultados excepcionais ao preparar seus pratos favoritos. Com uma camada especial que cobre seu material, essa frigideira eleva a experiência culinária a um novo patamar, garantindo que os alimentos não grudem e preservando o sabor original. Graças à sua camada antiaderente de alta qualidade, é possível cozinhar sem a necessidade de usar óleos ou gorduras excessivas. Esse benefício não apenas contribui para refeições mais leves e equilibradas, mas também facilita a manutenção de uma dieta saudável e nutritiva para você e sua família. Seu cabo é super resistente, proporcionando segurança e conforto durante o manuseio. Esqueça as preocupações com queimaduras ou desconforto ao cozinhar por longos períodos. Este utensílio foi projetado para atender às demandas dos chefs caseiros mais exigentes, proporcionando uma experiência gastronômica agradável e sem contratempos.A versatilidade desta frigideira não se limita apenas à preparação de ovos. Ela se adapta a diversas receitas e técnicas culinárias. Prepare desde omeletes perfeitamente dourados até panquecas macias, garantindo resultados consistentes e deliciosos a cada uso. Além de sua funcionalidade inigualável, a Frigideira Oliveira Grafite também é um item elegante na cozinha. Seu design moderno e sofisticado adiciona um toque de estilo ao seu espaço culinário, tornando-a uma peça indispensável para os amantes da boa comida que também apreciam um ambiente bem decorado.Invista na excelência da Frigideira Antiaderente para Ovo Oliveira Grafite 12cm e descubra como cada detalhe faz a diferença na sua jornada culinária. Prepare-se para experimentar a facilidade, segurança e sabor que esta frigideira proporciona. Torne-se o mestre da sua cozinha com um utensílio que está à altura das suas aspirações gastronômicas.O segredo de um ovo frito irresistível com a Frigideira Antiaderente OliveiraDesvendar o segredo de um ovo frito cremoso é transformar um simples ingrediente em uma delícia irresistível. Comece escolhendo uma frigideira antiaderente de qualidade, como a Frigideira Antiaderente para Ovo Oliveira Grafite 12cm, para garantir que o ovo deslize suavemente durante o cozimento. Pré-aqueça a frigideira em fogo médio e, se desejar, adicione uma pequena quantidade de manteiga, azeite de oliva ou óleo de coco. Quebre o ovo cuidadosamente, assegurando-se de manter a gema íntegra. Cozinhe em fogo baixo para garantir uma textura cremosa, cobrindo a frigideira para concentrar o calor. Adicione uma pitada de sal e pimenta a gosto.Para potencializar o sabor, experimente adicionar ervas frescas ou queijo durante o cozimento. Sirva o ovo frito cremoso sobre uma fatia de pão ou ao lado de vegetais salteados. Com essas dicas simples, você conquistará uma explosão de cremosidade em cada mordida, transformando seu ovo frito em uma experiência gastronômica inesquecível.', 24.99, 22.99, NULL, 'Home & Living > Kitchenware > Pans', 'https://cf.shopee.com.br/file/sg-11134201-8258m-mqyt1tmdq9kx50', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1050213612%2F23993887709', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21097415151', 'Shampoo Deta Gold Ceramidas 2L', 'A Linha Detagold evita o ressecamento, hidratando os cabelos proporcionando maior resistência à fibra capilar, deixando-os sedosos e saudáveis. Modo de uso: Aplicar nos cabelos molhados. Massagear suavemente. Enxaguar. Repetir a operação se necessário. #html-body [data-pb-style="646BA6473BC0D"]{justify-content: Flex-start; display: Flex; flex-direction: Column; background-position: Left top; background-size: Cover; background-repeat: No-repeat; background-attachment: Scroll; border-style: None; border-width: 1px; border-radius: 0px; margin: 0px 0px 10px; padding: 10px;}#html-body [data-pb-style="646BA6473BC21"]{border-style: None; border-width: 1px; border-radius: 0px; margin: 0px; padding: 0px;}', 28.31, 28.31, NULL, 'Beauty > Hair Care > Shampoo', 'https://cf.shopee.com.br/file/sg-11134201-7rbn9-lmf3l54l7yvt22', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F21097415151', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19699245256', 'Cílios 3D Esfumado Incrível Ricca Vol.03 Médio', '#html-body [data-pb-style=ERWNXVQ]{justify-content:Flex-start;display:Flex;flex-direction:Column;background-position:Left top;background-size:Cover;background-repeat:No-repeat;background-attachment:Scroll}Transforme seu olhar com os Cílios 3D Esfumado Incrível Ricca, a escolha perfeita para quem busca volume e harmonia. Estes cílios postiços 3D de fio sintético tem tamanho médio e cor preto, além de oferecer um resultado incrível, realçando sua beleza natural com elegância e sofisticação. Características incríveis do Cílios 3D Esfumado Incrível Ricca: Os Cílios 3D Esfumado Incrível Ricca apresentam um volume médio com fios intercalados em diferentes tamanhos, proporcionando um resultado harmonioso para o olhar. Feitos com a inovadora fibra PBT, garantem leveza, flexibilidade e pontas afiladas para um acabamento impecável. A estrutura desses cílios em camadas oferece um efeito natural e esfumado, misturando-se perfeitamente aos seus cílios naturais. Experimente a beleza da harmonia com os cílios médios 3D Ricca. Como colar os seus cílios postiços: Retire os cílios do estojo delicadamente com uma pinça. Ajuste o tamanho, se necessário; Aplique a cola para cílios postiços Ricca (vendida separadamente) na tira dos cílios e aguarde 30 a 60 segundos até que fique transparente e consistente; Posicione os cílios postiços rente à raiz dos seus cílios naturais. Segure por alguns segundos até que a cola seque. Como remover os seus cílios postiços: Aplique demaquilante bifásico em uma haste flexível com ponta de algodão e passe suavemente na linha dos cílios; Comece a descolar os cílios pelo canto externo.', 21.52, 21.52, NULL, 'Beauty > Beauty Tools > Makeup Accessories', 'https://cf.shopee.com.br/file/sg-11134201-7rd6z-lu87j3s38s7j31', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F19699245256', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22694032250', 'Bomba Direção Hidraulica Voyage Saveiro Cross Fox Gol G5 G6 2003 2010 2011 A 2017 Original Indisa', 'BOMBA DE DIREÇÃO HIDRÁULICA ORIGINAL INDISA (DH454111) - PREÇO REFERENTE A 01 PEÇA APLICAÇÕES: FOX 1.0, 1.6. 2003 2004 2005 2006 2007 2008 2009 2010 2011 2012 2013 2014 2015 2016 2017 CROSS FOX 1.0 1.6 2003 2004 2005 2006 2007 2008 2009 2010 2011 2012 2013 2014 2015 2016 2017 NOVO POLO 2006 2007 2008 2009 2010 2011 2012 2013 2014 2015 2016 2017 VOYAGE 2006 2007 2008 2009 2010 2011 2012 2013 2014 2015 2016 2017 GOL G5 E G6 1.0,1.6 2009 2010 2011 2012 2013 2014 2015 2016 2017 Saveiro G5 E G6 1.0, 1.6 2009 2010 2011 2012 2013 2014 2015 2016 2017 SPACE FOX 1.0 2003 2004 2005 2006 2007 2008 2009 2010 2011 2012 2013 2014 2015 2016 2017 Polia com triangulo sextavado. PRESSÃO: 95Bar. VAZÃO: 6L por minuto. FUROS DE FIXAÇÃO: 3 ROTAÇÃO: Horária (Direita). GARANTIA DE 6 MESES DO FABRICANTE ***RECOMENDAMOS QUE A INSTALAÇÃO SEJA REALIZADA POR PROFISSIONAIS ESPECIALIZADOS!*** NÓS DA EQUIPE GOLDSPEED, AGUARDAMOS SUA COMPRA! Invista na Bomba Direção Hidráulica Indisa e experimente a diferença que um produto de qualidade pode fazer na sua condução. Aumente a eficiência do seu sistema de direção e aproveite cada viagem com mais segurança e conforto.', 459.9, 425.62, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Others', 'https://cf.shopee.com.br/file/sg-11134201-7ravh-ma2u8n3kjssx4c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F972424499%2F22694032250', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20116494218', 'Sensor Abs Traseiro Gol / Voyage / Fox / Golf - Wht003862', 'SENSOR ABS APLICACAO: - AUDI A1 1.4 16V TFSI 2011 > 2018 A1 1.8 16V TFSI 2016 > 2018 - VOLKSWAGEN CROSSFOX 1.6 8V 2005 > 2014 CROSSFOX 1.6 16V 2015 > 2018 FOX 1.0 12V 2014 > 2019 FOX 1.0 8V 2004 > 2015 FOX 1.6 16V 2015 > 2018 FOX 1.6 8V 2004 > NIVUS 1.0 12V TSI 2021 > POLO 1.0 12V TSI 2018 > POLO 1.4 16V TSI 2020 > POLO 1.6 16V 2018 > POLO 1.6 8V 2003 > 2014 | SERIE 9N 9N3 POLO 2.0 8V 2003 > 2014 | SERIE 9N 9N3 SPACECROSS 1.6 8V 2012 > 2014 SPACECROSS 1.6 16V 2015 > 2017 SPACEFOX 1.6 8V 2006 > 2019 SPACEFOX 1.6 16V 2015 > 2017 T-CROSS 1.0 12V TSI 2020 > T-CROSS 1.4 16V TSI 2020 > UP 1.0 12V 2014 > UP 1.0 12V TSI 2016 > VIRTUS 1.0 12V TSI 2018 > VIRTUS 1.4 16V TSI 2020 > VIRTUS 1.6 16V 2019 > - POSICAO: LADO DIREITO TRASEIRO *** COMPATIVEL COM WHT003862B - MARCA: VOLKSWAGEN - CODIGO: WHT003862 / 6Q0927808B / EI 03862 / 0986594503 / 6Q0927808A / 120006 / SS20211 / ABSMM20TD / 73335 / GS2862 - PECA NOVA! * FOTOS REAIS DO PRODUTO. * 3 MESES DE GARANTIA. * CONFIRME A NUMERACAO DA SUA PECA ANTES DE REALIZAR A COMPRA. ENTRE EM CONTATO CONOSCO E TIRE TODAS AS SUAS DUVIDAS.', 39.9, 39.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Others', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m2jniqy2yx52f4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F241226352%2F20116494218', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23798365990', 'Kit 4 Aditivo Radiador Paraflu Orgânico Rosa Long Life Pronto Uso 103004', 'Conteúdo da embalagem 5l Aditivo para Radiador Paraflu Ecoflu Rosa 1 Litro – Pronto para Uso Descrição do produto O Aditivo para Radiador Paraflu Ecoflu Rosa é uma solução arrefecedora desenvolvida para auxiliar na proteção e no bom funcionamento do sistema de arrefecimento do veículo. Sua fórmula Long Life e pronta para uso proporciona mais praticidade na aplicação, pois não necessita de diluição. O produto ajuda a proteger os componentes do sistema contra ferrugem, corrosão, formação de espuma e incrustações, contribuindo para o controle adequado da temperatura e para a conservação do motor. Principais benefícios Produto pronto para uso Não necessita diluição Embalagem de 1 litro Coloração rosa Tecnologia Long Life Auxilia na proteção contra ferrugem e corrosão Ajuda a evitar espuma e incrustações Possui ação anticongelante e antifervura Contribui para a conservação do sistema de arrefecimento Produto original Paraflu Especificações Marca: Paraflu Linha: Ecoflu Cor: Rosa Conteúdo: 1 litro Tipo: Solução para sistema de arrefecimento Tecnologia: Long Life Aplicação: Pronto para uso Norma indicada na embalagem: ABNT NBR 14261 – Tipo C Modo de uso Antes da aplicação, verifique a especificação recomendada no manual do veículo e as orientações do fabricante. Não misture produtos de cores, tecnologias ou composições diferentes. Caso seja necessário trocar o tipo de fluido, recomenda-se realizar a limpeza completa do sistema de arrefecimento antes da aplicação. Atenção A cor do fluido, isoladamente, não determina sua compatibilidade com o veículo. Confira sempre a tecnologia e a especificação recomendadas pela montadora antes da compra e da aplicação. Sobre a Paraflu Há mais de 50 anos no mercado, a Paraflu é especialista no desenvolvimento de soluções para sistemas de arrefecimento. Seus produtos unem tecnologia, inovação e qualidade para proporcionar proteção e segurança aos componentes do motor. AutoStileMotors Produto à pronta entrega, cuidadosamente embalado e enviado com segurança pela AutoStileMotors – Peças e Lubrificantes Automotivos.', 140.6, 99.98, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Additive and Lubricant', 'https://cf.shopee.com.br/file/br-11134207-820l4-mr09bpx6rsp037', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F954990910%2F23798365990', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23298946198', 'Desodorante Aerosol Bozzano Anti Dry 200ml', '#html-body [data-pb-style=HOWS1FS]{justify-content:Flex-start;display:Flex;flex-direction:Column;background-position:Left top;background-size:Cover;background-repeat:No-repeat;background-attachment:Scroll}O Desodorante Aerosol Bozzano Anti Dry 200ml foi desenvolvido para oferecer proteção duradoura contra o suor e o mau odor, com sensação de toque seco imediato. Sua fórmula de alta performance garante até 48 horas de proteção, ideal para homens que buscam frescor e segurança ao longo do dia. Com tecnologia que minimiza resíduos brancos e manchas nas roupas, o Bozzano Anti Dry também conta com fragrância masculina leve e refrescante, ideal para todos os momentos do dia — do trabalho à academia. É fácil de aplicar, seca rapidamente e não agride a pele. Modo de Uso: Agite bem antes de usar. Aplique nas axilas limpas e secas, mantendo uma distância de 15 cm da pele. Espere secar completamente antes de se vestir.', 19.37, 19.37, NULL, 'Beauty > Bath & Body Care > Body Deodorants', 'https://cf.shopee.com.br/file/sg-11134201-824hs-mfa7w8bh6qdnd5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F23298946198', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23294919262', 'Colete Blusa Feminina Tricot Regata Botões Dourados Elegante Ajustado 3RD SD1901', 'Uma peça moderna, confortável e super versátil — perfeita tanto para o dia a dia quanto para ocasiões especiais. Com caimento impecável e tecido de alta qualidade, ela garante estilo, praticidade e muito bem-estar em qualquer momento. Nada melhor do que investir em looks que elevam sua autoestima e destacam seu estilo todos os dias. Garanta já o seu! 📌 Tecido Modal ✔ Toque suave ✔ Confortável ✔ Estica bem 👗 Modelo veste P/M Altura: 【1,60m】 — Peso: 【60kg】 📏Medidas P/M(36-38) • Busto:72cm • Comprimento:52cm G/GG(40-42) • Busto:76cm • Comprimento:54cm OBSERVAÇÕES 1) Recomendamos pedir sua numeração habitual. A modelagem é padrão — não veste menor nem maior. 2) Em caso de dúvidas, sugestões ou qualquer problema, nos chame no chat da loja! Atendemos também pedidos no atacado. 3) Trabalhamos somente com produtos importados e de ótima qualidade. Como não há reposição imediata, nossos estoques são limitados — aproveite enquanto temos! ♥️ Siga a 3RD Fashion e conheça todas as novidades que preparamos com muito carinho para você! ⭐ Muito obrigado pelo seu bom gosto! Esperamos oferecer a melhor experiência de compra possível.', 55.0, 55.0, NULL, 'Women Clothes > Jackets, Coats & Vests > Vests', 'https://cf.shopee.com.br/file/br-11134207-820m7-mm0pmdqbzapz52', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F393568956%2F23294919262', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
