INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23192498332', 'Esmalte Colorama Cremoso 5 Avenida', 'O Esmalte Colorama possui uma ótima textura, alta durabilidade, proporciona brilho intenso e acabamento uniforme. Possibilita infinitas formas para criar e ousar com seus efeitos e tecnologias diferenciadas. Moderna, ousada, fashion e feminina a Colorama disponibiliza várias cores e tendências para todos os gostos e looks. Modo de usar: Com as unhas limpas, aplique uma ou duas camadas do esmalte, de acordo com a intensidade desejada. #html-body [data-pb-style="646BA647A19EC"]{justify-content: Flex-start; display: Flex; flex-direction: Column; background-position: Left top; background-size: Cover; background-repeat: No-repeat; background-attachment: Scroll; border-style: None; border-width: 1px; border-radius: 0px; margin: 0px 0px 10px; padding: 10px;}#html-body [data-pb-style="646BA647A1A01"]{border-style: None; border-width: 1px; border-radius: 0px; margin: 0px; padding: 0px;}', 21.45, 21.45, NULL, 'Beauty > Hand, Foot & Nail Care > Nail Care', 'https://cf.shopee.com.br/file/sg-11134201-7rbkp-lmg33jel6vft18', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F23192498332', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22392495530', 'Balsamo Pós Barba Bozzano Hidrat 100ml', 'O Bálsamo Pós Barba Bozzano Pele Sensível proporciona um cuidado adequado com a pele dos homens, suaviza e hidrata instantaneamente.Possui uma fórmula que previne e reduz os efeitos da irritação, provocados pela lâmina, diminuindo a vermelhidão e sensação de ardência, proporciona secagem rápida, frescor e alívio.DescriçãoHidrata por 24 horas.O Bálsamo Pós Barba Bozzano Pele Sensível foi desenvolvido exclusivamente para suavizar e hidratar a pele dos homens apó o barbear.Agora com exclusiva tecnologia B-Effect System, que auxilia a proteger a pele contra os efeitos agressivos do barbear, promovendo hidratação e renovação celular, preparando a pele para o próximo barbear. Modo de uso: Após o barbear, seque o rosto e aplique o bálsamoem sua pele, espalhando-o suavemente. Previne e reduz os efeitos da irritação, provocados pela lâmina, diminuindo a vermelhidão e sensação de ardência, proporciona secagem rápida, frescor e alívio. #html-body [data-pb-style="646BA657AEBF5"]{justify-content: Flex-start; display: Flex; flex-direction: Column; background-position: Left top; background-size: Cover; background-repeat: No-repeat; background-attachment: Scroll; border-style: None; border-width: 1px; border-radius: 0px; margin: 0px 0px 10px; padding: 10px;}#html-body [data-pb-style="646BA657AEC09"]{border-style: None; border-width: 1px; border-radius: 0px; margin: 0px; padding: 0px;}', 41.47, 41.47, NULL, 'Beauty > Men''s Care > Shaving & Grooming', 'https://cf.shopee.com.br/file/sg-11134201-7rbm1-lmho2tg8g19621', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F22392495530', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
