INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19049690864', 'Kit Pastilhas de Freio P/ Dafra Nhx 190 2025 / Nh 190 2025 / Nh 300 Abs 2025 / Next 250 Diafrag', 'Jogo de Pastilhas de Freio Dianteira + Traseira - Diafrag Pastilha da melhor qualidade para frenagem da sua moto, testado e aprovado por laboratórios de qualidade! Não vai te deixar sem freio! Compatível com: DAFRA NEXT 250 ROADWIN 250﻿ NH 190 2025 NHX 190 2025 NH 300 ABS Conteúdo da Embalagem: 01 Par de Pastilhas de Freio Traseira Diafrag Urban Tech (orgânica) 01 Par de Pastilhas de Freio Dianteira Diafrag Dura tech (semimetálica) Especificações Técnicas: - Ótima performance em condições secas ou molhadas - Bom poder de frenagem - Baixa dureza do material de atrito - Rápido assentamento inicial da superfície da pastilha à do disco de freio - Dissipação de calor moderada - Performance superior - Pastilha de alta duração - Maior segurança ao motociclista - Possui medidas originais - Tendência a redução de ruídos - Boa durabilidade Importante: Recomendamos que a instalação seja feita por profissional especializado e não nos responsabilizamos pelo mau uso do produto.', 124.9, 74.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Chassis', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mhuis4l1c7416e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316500472%2F19049690864', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
