INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19097748906', 'Troca de Óleo P/ Harley Davidson V-Road / Night Road Motul 7100 20w50 + FIltro Hiflo', 'ACONSELHAMOS VERIFICAR A RECOMENDAÇÃO DO FABRICANTE NO MANUAL DA MOTOCICLETA. Kit Troca de Óleo Aumente a vida útil de sua moto. Praticando uma manutenção rigorosa do sistema de lubrificação, trocando o óleo e o filtro de óleo regularmente você estará estendendo a vida do motor, evitando desgaste excessivo das partes móveis, aumentando o desempenho e reduzindo o consumo de combustível. Conteúdo da Embalagem: 05 Frascos de 1 Litro de Óleo Motul Sintético 7100 20w50 01 Filtro de Óleo Hiflo Algumas Aplicações: HARLEY DAVIDSON V-ROD 1250 MUSCLE VRSCF V-ROD 1250 VRSCAW V-ROD VRSCDX 10th ANNIVERSARY EDITION Especificações Óleo Motul: Aplicação: Lubrificantes para Motor Qualidade: Sintético Tipo de motor: 4 Tempos Viscosidade: 20W50 Padrão API: API SN / SM / SL / SJ / SH/ SG Padrão JASO: JASO MA2 com nro de certificado M033MOT120 Número de Registro ANP: 12.731 Especificações Técnicas Filtro Hiflo: - Fabricado em Metal e Borracha Resistente - Número da Peça: HF145 - Possui Válvula Anti-Dreno, Desvio e Alívio PSI - Para Uso de Óleo Mineral, Sintético e Semi-sintético - Projetado Para Suportar Pressões Internas Elevadas - Garante Melhor Circulação do Óleo e Proteção ao Motor - Maior Resistência a Pedras e Detritos que Podem Atingir a Moto - Borracha de Vedação Pré-Lubrificada - Substitui o Filtro de Óleo Original - Fácil Instalação - Qualidade Reconhecida HIFLO FILTRO * Atenção * Usar porca apenas para a retirada do filtro. O filtro de óleo proporciona os seguintes benefícios ao seu motor: - Protege o motor; - Prolonga sua vida útil; - Proporciona segurança; - Permite uma lubrificação mais eficaz; - Proporciona melhor rendimento do motor e precisão de funcionamento; - Contribui na economia de combustível; - Contribui para a redução de emissão de poluentes na atmosfera. Importante: Recomendamos que a instalação seja feita por profissional especializado e não nos responsabilizamos pelo mau uso do produto.', 870.9, 870.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Additive and Lubricant', 'https://cf.shopee.com.br/file/sg-11134201-7rd6z-lwr57x8veunt89', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316500472%2F19097748906', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21038997510', 'Filtro de Combustivel Xre 300 / Cb 250f Twister / Cb 300f Twister / Cb 300R Metal Leve', 'Essa peça serve para filtrar o combustível que passa pelo motor, evitando que impurezas danifiquem sua estrutura. O filtro impede que partículas que estejam no tanque como ferrugem, pó, água ou sujeira, cheguem à bomba de combustível e ao bico injetor, preservando a sua vida útil. Compatível com: Aplicação Flex: CB 300F TWISTER 2023 A 2024 CB 300R EDIÇÃO LIMITADA 2016 A 2022 CB 300R 2013 A 2022 CB 300R ABS 2013 A 2022 CB 250F TWISTER 2015 A 2022 CB 250F TWISTER ABS 2015 A 2020 XRE 300 ABS 2013 A 2022 XRE 300 2013 A 2016 Especificações Técnicas: - Diâmetro Externo (d): 87 - Diâmetro Interno (d1): 49 - Diâmetro Interno (d2): 6,3 - Diâmetro Interno (d3): 16,3 - Altura (h1): 105 - OEM: 16910-KVK-B21 / 16940-KVK-B22 / 16910-KCW-B1 Principais sinais que necessitam a troca: - Dificuldade para arranque - Perda de eficiência no consumo de combustível - Aparente falta de combustível - Motor engasgando ao acelerar - Aparecimento de ferrugem no filtro Como saber se devo trocar o Filtro de Combustível? Geralmente, falta de potência, dificuldade em altas velocidades ou uma partida mais lenta são sinais que é preciso trocar filtro de combustível o mais rápido possível. Instabilidade no desempenho do motor, com aumento do consumo de combustível, presença de ferrugem ou resíduos no tanque e dificuldade para dar partida no carro também são alguns sinais a serem observados e que podem indicar que está na hora de fazer a troca do filtro. A finalidade do filtro de combustível é eliminar impurezas no combustível para que ele chegue ao cilindro de combustão o mais puro possível. A peça age retirando impurezas muitas vezes invisíveis a olho nu, como poeira, ferrugem, água, ferro, partículas orgânicas (muito presentes no álcool), entre outras, jogando o líquido puro direto no motor. Quando o veículo apresenta algum problema, nada pior do que descobrir que tudo poderia ter sido evitado se alguma peça tivesse sido trocada com antecedência. Entre os equipamentos simples que podem causar grandes aborrecimentos no futuro está o filtro de combustível, que merece atenção especial. Como a peça previne a entrada de impurezas no motor, ela é de vital importância para o bom funcionamento do automóvel. Sendo assim, conhecer os sintomas do filtro de combustível sujo pode facilitar bastante a sua vida, evitando que as falhas se tornem uma verdadeira bola de neve. Importante: Recomendamos que a instalação seja feita por profissional especializado e não nos responsabilizamos pelo mau uso do produto.', 34.9, 29.67, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Filters', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m5oiml7mi3zme2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316500472%2F21038997510', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
