INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23593083662', 'Guarda Roupa Modulado Closet Industrial 2 Portas 6 Gavetas Off White Olivar Móveis', 'Descrição: Este é o Conjunto de Closet Ind. Olivar-Módulos 05,03 e 02, produto que mostra uma diversidade de materiais, com metal nas laterais, MDF e MDP de 15 mm. Ele possui prateleiras para acomodar objetos ou roupas, 1 cabideiro de metal e 1 cabideiro de alumínio, gavetas e portas com corrediças e dobradiças metálicas, tudo com design de uma pegada industrial para quem gosta do estilo mais urbano e contemporâneo onde você personaliza seu ambiente deixando-o exclusivo. Características: - Quantidade de Portas: 2 - Tipo de Closet: Modulado - Material: MDF e MDP - Acompanha Porta?: Sim - Garantia: 3 Meses - Volumes: 8 - Recomendações de manutenção: Pano úmido. Não aplicar lustra móveis. - Tipo de Prateleira: Fixa - Quantidade de Prateleiras: 8 - Tipo de Porta: Porta Rotativa - Quantidade de Portas: 2 - Tipo de Pés: Fixo - Quantidade de Pés: 12 - Tipo de Gaveta: Com corrediça telescópica - Quantidade de Gaveta: 6 - Produto Necessita de Montagem?: Sim - Peso do Produto Montado: 130,30Kg - Material da Estrutura: Mdp e Mdf - Escala de Brilho: Acetinado - Acabamento: Pintura UV - Peso Máximo Suportado: 90Kg - Medida do Produto Montado (LXCXA): 46,8cmX232,20cmX200cm', 4399.99, 3049.99, NULL, 'Home & Living > Furniture > Wardrobes', 'https://cf.shopee.com.br/file/sg-11134201-7rd59-lv9ifhvfdwls42', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F408578430%2F23593083662', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22497983273', 'Kit 3 Refil Filtro Purificador Electrolux PE11 PE12 PE15 Compatível', 'O Refil Filtro Purificador Electrolux Compatível Oxygen é indicado para quem busca uma reposição prática, econômica e eficiente para purificadores Electrolux. Este refil é compatível com os modelos PE11, PE12, PE15, PC41B, PC41X, PH41B, PH41X, PA21G, PA26G e PA31G. Antes da compra, verifique o modelo do seu purificador para garantir a compatibilidade correta. O refil Oxygen OxElux é similar ao refil original Electrolux Acqua Pure para os modelos compatíveis informados neste anúncio. O produto auxilia na redução do cloro livre, melhora o sabor e o odor da água e retém partículas como areia, barro, ferrugem e sedimentos. Produto compatível Oxygen. Benefícios Compatível com purificadores Electrolux PE11, PE12 e PE15. Também compatível com PC41B, PC41X, PH41B, PH41X, PA21G, PA26G e PA31G. Similar ao refil original Electrolux Acqua Pure. Reduz no mínimo 75% do cloro livre. Ajuda a reduzir odores e sabores indesejáveis. Filtragem Classe C. Carvão ativado com íons de prata. Controle microbiológico. Instalação simples. Vida útil de até 4.000 litros ou até 6 meses. Garantia de 90 dias contra defeitos de fabricação. Especificações técnicas Marca: Oxygen Modelo interno: OxElux Tipo de produto: refil filtro compatível Aplicação: purificador de água Electrolux Vida útil: até 4.000 litros ou até 6 meses Redução de cloro livre: mínimo de 75% Classificação de filtragem: Classe C Norma informada: ABNT NBR 16098:2012 Elemento filtrante: carvão ativado com íons de prata e polipropileno meltblown Retenção de partículas: 5 a 15 µm Controle microbiológico: sim Garantia: 90 dias contra defeitos de fabricação Compatibilidade Compatível com: PE11 | PE12 | PE15 | PC41B | PC41X | PH41B | PH41X | PA21G | PA26G | PA31G FAQ 1. Esse refil é compatível com quais purificadores Electrolux? É compatível com PE11, PE12, PE15, PC41B, PC41X, PH41B, PH41X, PA21G, PA26G e PA31G. 2. Esse refil é original Electrolux? Não. É um refil compatível da marca Oxygen. 3. Ele é similar a qual refil original Electrolux? É similar ao refil original Electrolux Acqua Pure. 4. O refil reduz cloro? Sim. Reduz no mínimo 75% do cloro livre. 5. Qual é a vida útil do refil? Até 4.000 litros ou até 6 meses, podendo variar conforme a qualidade da água e o consumo. 6. A instalação é fácil? Sim. A instalação é simples e não exige técnico.', 194.46, 138.9, NULL, 'Home Appliances > Kitchen Appliances > Water Filters, Coolers & Dispensers', 'https://cf.shopee.com.br/file/br-11134207-7r98o-ma4gvtcegt1jc5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F987512869%2F22497983273', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
