INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '15904167052', 'Viseira para Corrida HUPI Dryfit Run Preto Com Ajuste', 'A viseira HUPI vem ao mercado para que você possa esfriar a cabeça e preocupar-se com nada além de correr. Isto porque é um item tão leve e confortável que você nem vai sentir na cabeça! Qualidade profissional A fabricação é realizada 100% em poliéster, que auxilia na transpiração, evitando a retenção de suor refletindo na qualidade da sua corrida. A aba curva protege os olhos e a pele da região facial dos raios ultravioletas que podem causar danos permanentes à sua saúde. A faixa de sustentação da viseira é ajustável e veste muito bem, sem qualquer peça de plástico ou metal que possa causar desconforto. Fabricada em poliéster também é projetada para não reter suor, mas promover sustentação sem incômodo. A parte interna da faixa, na região da aba possui um tecido aveludado, evitando que o suor escorra em direção aos olhos. Use a viseira para praticar atividades ao ar livre, importante se proteger do sol. Não esqueça da viseira mesmo em dias nublados, afinal proteção nunca é demais. Modelo de viseira para corrida Dryfit é unissex, pode ser usado como veseira feminina ou masculino! Clique Aqui e conheça todos os modelos de Viseiras para Corrida da HUPI! Ficha técnica * Composição: 100% poliéster; * Peso: 50 gramas; * Aba curva; * Tecido aveludado na parte interna frontal; * Faixa de sustentação moldável; * Tamanho único.', 130.08, 109.9, NULL, 'Sports & Outdoors > Sports & Outdoor Accessories > Sports & Outdoor Hats', 'https://cf.shopee.com.br/file/br-11134207-820l7-mmkmxw828yro6e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F524728336%2F15904167052', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
