INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '29571331446', 'Arroz Parboilizado', 'O arroz parboilizado é um tipo de arroz que passa por um processo único de parboilização, no qual os grãos são embebidos, aquecidos e secos antes da remoção da casca. Este produto é composto por grãos selecionados, que mantêm uma textura firme e um cozimento sempre uniforme, garantindo que o arroz fique soltinho e com ótima apresentação. O arroz parboilizado é versátil e pode ser utilizado em diversas receitas, desde pratos simples do dia a dia até preparações mais elaboradas, como risotos, paellas e acompanhamentos de carnes, aves e vegetais. Ingredientes: Arroz parbolizado ALÉRGICOS: PODE CONTER TRAÇOS DE GLÚTEN, LEITE, SOJA, AMENDOIM E CACAU POR CONTAMINAÇÃO CRUZADA. INFORMAÇÕES ADICIONAIS - PODE HAVER VARIAÇÃO DE COR DEPENDENDO DO LOTE. - EMBALAGEM MERAMENTE ILUSTRATIVA.', 12.89, 12.89, NULL, 'Food & Beverages > Food Staples > Rice', 'https://cf.shopee.com.br/file/br-11134207-820lt-mqj8x0ix7p4ydc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F657120589%2F29571331446', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
