INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '46201015276', 'Camiseta Lupo Basic Feminina - Branco', 'Camiseta básica com modelagem reta, manga curta e gola redonda. Possui transfer refletivo na frente e proteção contra os raios solares UV +50. Produzida especialmente com fio de poliamida biodegradável que reduz o tempo de biodegradação da peça para menos de três anos quando descartada em aterrossanitários. Aposte na marca que visa qualidade e autenticidade nas suas combinações, vai de Lupo!', 129.9, 119.9, NULL, 'Women Clothes > Tops > T-shirts', 'https://cf.shopee.com.br/file/br-11134207-81zuc-mkjuanjlf11e59', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1178125772%2F46201015276', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
