INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58200422743', '4K CCD Câmera Digital Zoom 16X CCD, Retro Viagem Selfie De 50MP HD De 2,4 Polegadas Tela De Campus Cam+32GB', '✨✨Destaques do Produto: Vídeo Full HD + Imagem 50MP: Capture momentos com qualidade surpreendente! Imagens nítidas com resolução de 44MP e vídeos em 1080P. Com zoom digital de 16x, aproxime ou afaste a cena facilmente. A luz de preenchimento embutida permite fotos claras mesmo no escuro. ✅Modo Multifuncional: Inclui luz de preenchimento , estabilização anti-vibração , disparo contínuo , detecção facial , captura de sorriso , selfie , microfone e alto-falante embutidos . Registre cada momento com diversão! ✅Vídeos Estáveis + Webcam: Grave vídeos mais suaves e use como webcam para chamadas de vídeo ou transmissões ao vivo . A porta USB Tipo-C facilita a transferência de fotos e vídeos para o computador. ✅Compacta e Portátil: Menor que um celular! Super leve, fácil de levar para qualquer lugar . Ideal para crianças e adolescentes entre 4 a 15 anos, feita com material ecológico, seguro e durável . ️ ✅Especificações Técnicas: ️ Resolução de Vídeo: 1080P Full HD ️ Resolução de Imagem: 50MP Zoom Digital: 16x Formatos Suportados: JPG / AVI Abertura: F/3.2 Distância Focal: f = 7,36mm Conexão: Tipo-C USB Tela: 2,4 polegadas Bateria: Íons de lítio recarregável (inclusa) Desligamento Automático: Sim ✅Idiomas: Vários idiomas suportados Funções Extras: Captura de sorriso, selfie, anti-tremor, etc. 📦Conteúdo da Embalagem: 1x Câmera Digital 1x Cabo Tipo-C 1x Cordinha de segurança 1x Manual do Usuário 1XSaco de acolhimento 1XCartão de memória-32G✨ 1X Leitor de cartão✨', 300.0, 300.0, NULL, 'Cameras & Drones > Cameras > Point & Shoot', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mgroq123oa2oa3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fp