INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '9930774944', 'Comentário Bíblico - Warren Wiersbe - 2 Volumes', 'Livro Comentário bíblico, Warren W. Wiersbe Volume 1 (Antigo Testamento) e Volume 2 (Novo Testamento). O livro comentário bíblico Warren W. Wiersbe, um dos melhores e mais importantes mestres do ensino bíblico do mundo, analisa a emocionante, profunda, verdadeira e eficaz Palavra de Deus, enfatizando sua aplicação pessoal e contribuindo para que o leitor cresça intelectual e espiritualmente. De Gênesis ao Apocalipse, Dr. Wiersbe explica, com linguagem fácil, direta e concisa, o significado de cada mensagem comunicada pelos escritores bíblicos, sempre tendo em mente uma aplicação prática. O autor analisa a história, a cultura, os povos e os lugares bíblicos, contextualizando os ensinamentos para nossos dias e enriquecendo-os com vários exemplos e ilustrações. O comentário Wiersbe será muito útil ao leitor no seu estudo particular, na pregação e no ensino da Palavra de Deus.', 166.41, 166.41, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/br-11134207-7qukw-liu8olyxlain5d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F380531074%2F9930774944', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
