INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259455151', 'Cream Cheese Tradicional Danubio', 'O Cream Cheese Tradicional Danubio é cremoso, equilibrado e com o verdadeiro sabor do cream cheese, ideal para receitas doces e salgadas. Elaborado com leite pasteurizado, passa por processo de ultrafiltração, resultando em um produto leve e saudável. Perfeito para preparar tortas, cheesecakes, recheios e molhos. Experimente também com torradas e canapés. * Não contém glúten * Contém leite e derivados * Sem aromatizantes artificiais * Manter refrigerado entre 1°C e 10°C', 14.79, 13.3, NULL, 'Food & Beverages > Dairy & Eggs > Others', 'https://cf.shopee.com.br/file/sg-11134201-825b5-mqnelgl3ka9uea', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1660302938%2F58259455151', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
