INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23294277722', 'Minimanual de História - Enem, vestibulares e concursos', 'CONHEÇA O PRODUTO Autores: Flávia Maíra de Araújo Gonçalves, Robson Belchior Oliveira Chaves e Silvia Helena de Araújo Bueno Coordenação: Bruno Galelli Chieregatti e João de Sá Brasil Lima Destaques: Abordagem teórica com linguagem simples para auxiliar os estudos de quem não quer perder tempo; Conteúdo didático dividido por assuntos, de acordo com os editais do Enem, vestibulares e concursos públicos; Questões comentadas das provas dos últimos concursos e principais vestibulares; A Coleção Minimanuais - ENEM, Vestibulares e Concursos constitui um instrumento valioso para estudo, pesquisa e consulta das mais variadas áreas do conhecimento humano. Com linguagem acessível, este livro da coleção contempla teoria simplificada e questões resolvidas. A teoria está de acordo com o conteúdo programático exigido em editais do Enem, vestibulares e concursos públicos. A apresentação da resolução da questão visa à sistematização didática dos conhecimentos adquiridos. Nela, o alunado acompanhará as etapas de resolução como se estivesse assistindo a uma aula. Neste livro você verá com que frequência os tópicos da disciplina foram abordados pelas principais bancas organizadoras nos últimos exames. Tomaram-se por base as questões presentes neste livro. É, portanto, uma ferramenta importante para que o aluno conheça o perfil da banca para a qual prestará o seu próximo exame. Os coordenadores', 39.9, 39.9, NULL, 'Books & Magazines > Books > Politics, Law & Social Sciences', 'https://cf.shopee.com.br/file/br-11134207-820m8-mpconb0yfq4lec', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F626529639%2F23294277722', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58201898933', 'Mala Infantil Carrinho Viagem 2 em 1 Rosa Importway Pode Sentar e Ser Puxada Ideal Para Viagens Mais Divertidas', 'Mala Infantil Carrinho Viagem 2 Em 1 Rosa Importway A Mala Infantil 2 em 1 Importway é perfeita para acompanhar os pequenos em viagens com mais praticidade e diversão. Com design moderno e resistente, ela pode ser usada como mala tradicional ou como carrinho para a criança sentar e ser puxada, garantindo conforto e tornando o trajeto muito mais agradável. Especificações: • Marca: Importway • Modelo: BW360RS • Maleta plástica resistente com design em formato de motocicleta • Pode ser usada como brinquedo de passeio ou bagagem infantil • Possui rodinhas funcionais e alça de transporte ajustável • Possui amplo espaço interno para guardar brinquedos ou roupas • Acompanha adesivos para personalizar a maleta • Ideal para viagens ou momentos de diversão Conteúdo da Embalagem: - 01 Mala Infantil Carrinho Viagem 2 Em 1 Rosa Importway "Compra Garantida" - Ao Comprar conosco a sua compra é 100% garantida, o seu dinheiro está seguro até a entrega. *Garantia 90 dias. *Imagens meramente ilustrativas Importway Importando Soluções com Qualidade, Inovação e Responsabilidade desde 2007.', 275.26, 245.16, NULL, 'Travel & Luggage > Travel Bags > Others', 'https://cf.shopee.com.br/file/sg-11134201-822wn-mi7cozret4w067', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1229255557%2F58201898933', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22998726324', 'Espumante Salton Evidence 750ml', 'Tipo de vinho: Espumante Tipo de uva: 70% Chardonnay e 30% Pinot Noir Região de Origem: Serra Gaúcha Aroma: Pão torrado, delicadas fragrâncias de fermentos, frutas cítricas, maçãs, flores do campo e baunilha Paladar: Sabor elegante, harmônico, cremoso, de bom corpo, aveludado com notas de mel de acácia e feno maduro Graduação Alcóolica: 12%', 188.64, 188.64, NULL, 'Food & Beverages > Alcoholic Beverages > Wine & Champagne', 'https://cf.shopee.com.br/file/sg-11134201-7rdxp-mcb25szx40i9bd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1308521377%2F22998726324', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22698209611', 'KIT MOTUL VALVE & INJECTOR CLEAN 300ML 3 UNIDADES', 'Loja Ofical MOTUL A Motul é uma empresa francesa com mais de 165 anos de experiência na produção e distribuição de lubrificantes e fluidos de qualidade para motores. Ela é pioneira em inovação, tendo desenvolvido o primeiro lubrificante automotivo 100% sintético do mundo. Presente em mais de 160 países, a Motul chegou ao Brasil em 1992 e é conhecida por sua participação em competições automobilísticas de renome mundial. As pistas de corrida são o laboratório principal da empresa, onde seus produtos são testados em condições extremas antes de serem lançados no mercado. Representante oficial MOTUL BROOKLIN RACE uma das principais lojas de vendas de Lubrificantes, Pneus e acessórios para o segmento em São Paulo, com forte presença no . Nosso compromisso é proporcionar uma experiência de compra excepcional, oferecendo produtos de alta qualidade a preços competitivos. Valorizamos o suporte ao cliente, estando disponíveis para auxiliar tanto na pré-venda quanto no pós-venda, garantindo que todas as dúvidas sejam esclarecidas e quaisquer problemas sejam prontamente resolvidos. Estamos empenhados em superar suas expectativas e tornar sua jornada conosco memorável. COMPRANDO ATÉ ÀS 16:00+ DESPACHAMOS NO MESMO DIA. Limpeza De Valvulas Bicos Motul Valve E Injector Clean 300ml Características: Código: 108123 Código universal de produto: 3374650276083 Condição do item: Novo Marca: Motul Modelo: Aditivo limpeza gasolina MOTUL VALVE & INJECTOR CLEAN 300 ML MPN: 108123 Tipo de veículo: Carro/Caminhonete Volume da unidade: 300 ml "Aditivo de combustível para limpeza, dedicado a válvulas de admissão e bicos injetores especialmente desenvolvido para eliminar depósitos e vernizes nesses sistemas. Elimina contaminações em todo o sistema de injeção de gasolina causadas pelas condições de funcionamento e assegura uma limpeza eficaz das válvulas, dos bicos injetores e do coletor de admissão sem desmontagem."', 205.73, 185.16, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Additive and Lubricant', 'https://cf.shopee.com.br/file/sg-11134201-7rcf0-m66wid2g7k7r85', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1068060049%2F22698209611', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20398019597', 'Carabina de Pressão New Jade Oxidada 4.5mm - CBC + Capa', 'Carabina de Pressão CBC New Jade Oxidada 4.5 mm A New Jade 4.5 mm é uma carabina ideal para quem busca iniciação no tiro esportivo com um conjunto moderno, resistente e fácil de manusear. Sua coronha em polímero oferece ótima durabilidade no uso diário, com grip antiderrapante que melhora a pegada e aumenta o controle, trazendo mais confiança para quem está começando e também para quem quer um equipamento prático para treinos recreativos. Por ser no calibre 4.5mm, ela entrega maior velocidade e precisão, sendo uma excelente escolha para quem busca tiros mais rápidos e agrupamentos mais consistentes, especialmente em alvos e prática esportiva. O sistema de funcionamento é por basculamento do cano com alavanca acionada no engatilhamento, trabalhando com tiro individual de chumbinhos. Na pontaria, a New Jade entrega uma solução completa: alça de mira com regulagem horizontal e vertical e massa de mira fixa protegida por túnel, facilitando ajustes e oferecendo melhor proteção no transporte. Além disso, conta com trilho Picatinny, permitindo a instalação de acessórios compatíveis conforme a preferência do atirador. A segurança é um ponto forte, com trava ambidestra automática no gatilho e sistema que impede o disparo com o cano aberto, aumentando a proteção durante o uso. O gatilho convencional ajustável ajuda a refinar a experiência, enquanto o acabamento em aço com sobreinjeção de polímero reforça a robustez e o visual moderno. No desempenho, alcança 183 m/s (600 fps) com energia de 8 J, com alcance máximo indicado de 203m. Em relação a documentos, carabinas de pressão exigem apenas maioridade. Recomendamos verificar a legislação vigente da sua região. Trabalhamos apenas com produtos 100% originais, enviados com nota fiscal e garantia do fabricante de 1 ano. Especificações: Marca: CBC Modelo: New Jade Oxidada Calibre: 4.5 mm (maior velocidade e precisão) Sistema de funcionamento: Basculamento do cano (alavanca acionada no engatilhamento) Capacidade: Tiro individual (chumbinhos) Mola: Convencional em aço Velocidade na boca: 183 m/s (600 fps) Energia de Joules: 8 Distância máxima do tiro: 203 m Pontaria: Alça regulável (horizontal e vertical) + massa fixa com túnel Segurança: Trava ambidestra automática no gatilho + bloqueio com cano aberto Gatilho: Convencional ajustável Trilho: Picatinny Acabamento: Aço com sobreinjeção de polímero Coronha: Polímero Comprimento do cano: 44 cm Comprimento total: 103 cm Força para engatilhar: 8 kg Peso: 2,1 kg Itens inclusos: 1 Carabina de Pressão New Jade Oxidada 4.5mm 1 Porta Carabina Produtos enviados de imediato com despacho em até 24 horas úteis após a confirmação do pagamento.', 770.9, 539.9, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Shooting & Survival Games', 'https://cf.shopee.com.br/file/sg-11134201-7ra3f-m54hpxiuzkke2b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F335160199%2F20398019597', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22894948025', 'Sorveteira Expressa EOS ESO02S 220V', '🍨 Sorveteira Expressa EOS ESO02S 1L ❄️ Prepare sorvetes caseiros deliciosos com muito mais praticidade usando a Sorveteira Expressa EOS ESO02S. Compacta, eficiente e fácil de usar, ela é perfeita para criar sobremesas geladas para toda a família no conforto da sua casa. ✨ Destaques do Produto: ✅ Capacidade de 1 litro ✅ Refrigeração por compressor ✅ Display digital LCD intuitivo ✅ Seletor de funções prático ✅ Sistema Easy Clean com peças removíveis ✅ Baixo consumo de energia ✅ Ideal para sorvetes, gelatos e sobremesas caseiras ✅ Design compacto e moderno 📏 Medidas (LxAxP/cm): 35,5 x 22,7 x 26 cm 🏡 Perfeita para quem ama sobremesas geladas e deseja praticidade, rapidez e receitas incríveis no dia a dia.', 1197.9, 1197.9, NULL, 'Home Appliances > Kitchen Appliances > Specialty Cookware', 'https://cf.shopee.com.br/file/sg-11134201-820ok-mnagyerffawzd5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1527564302%2F22894948025', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58254918584', 'Regata Básica Masculina Verão Rota do Mar 100% Algodão Confortável Macia Promoção', 'Se você procura uma regata masculina básica, confortável e fácil de usar no dia a dia, essa peça da Rota do Mar é uma excelente escolha. Produzida em 100% algodão, ela oferece toque macio, caimento agradável e praticidade para diferentes momentos. É aquela regata versátil que combina com bermuda, short ou calça jeans, sendo ideal para quem quer conforto, estilo e um bom custo-benefício em uma peça só. ✅ Benefícios do produto ✔️ Tecido 100% algodão com toque macio e confortável ✔️ Modelagem básica que facilita o uso no dia a dia ✔️ Estampa moderna que valoriza o visual ✔️ Leve e confortável para usar por mais tempo ✔️ Fácil de combinar com diferentes peças do guarda-roupa ✔️ Ideal para lazer, passeios e rotina ✔️ Ótima opção para quem busca praticidade e conforto 📋 Especificações do Produto 🔹 Marca: RoTa do Mar 🔹 Modelo: Regata básica masculina estampada 🔹 Material: 100% algodão 🔹 Manga: Curta 🔹 Gola: Redonda 🔹 Estilo: Casual 🔹 Indicação: Uso diário, lazer e passeios 🔹 Toque do tecido: Macio e confortável 📏 Como escolher o tamanho correto 📌 Recomendamos escolher seu tamanho habitual. 📌 Se preferir a camiseta com caimento mais solto, escolha um número maior. 📐 Tabela de Medidas Tamanho P • Busto: 44-46 cm • Altura: 70 cm Tamanho M • Busto: 48-50 cm • Altura: 73 cm Tamanho G • Busto: 53-55 cm • Altura: 75 cm Tamanho GG • Busto: 56-58 cm • Altura: 78 cm ⚠️ Medidas aproximadas, podendo variar levemente. ❓ Perguntas Frequentes 🔸 A camiseta é 100% algodão? Sim, o tecido é 100% algodão. 🔸 O tecido é confortável? Sim, é uma peça com toque macio e agradável para o uso diário. 🔸 A modelagem é básica? Sim, é uma camiseta básica masculina, prática e versátil. 🔸 Pode usar no dia a dia? Sim, ela foi feita justamente para rotina, lazer e passeios. 🔸 Combina com quais peças? Combina facilmente com bermudas, shorts e calças jeans. 🔥 Garanta a sua antes que acabe Essa é a regata ideal para quem busca conforto, praticidade e um visual fácil de combinar no dia a dia. Uma peça básica, versátil e confortável, perfeita para ter no guarda-roupa e usar em várias ocasiões. 🛒 Aproveite agora e garanta a sua enquanto ainda há disponibilidade no seu tamanho.', 99.9, 49.99, NULL, 'Men Clothes > Tops > Tanks', 'https://cf.shopee.com.br/file/br-11134207-81zti-mkjmsbpxj1mr0d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F867315228%2F58254918584', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259825296', 'Conjunto de Panelas 5 Peças Tramontina Solar em Aço Inox com Fundo Triplo e Tampas com Saída de Vapor', 'O Conjunto de Panelas 5 Peças Tramontina Solar é a escolha ideal para quem busca eficiência, durabilidade e sofisticação na cozinha. Produzidas em aço inox, não liberam resíduos nos alimentos, garantindo preparos mais saudáveis. Com fundo triplo que distribui o calor de forma uniforme, proporcionam um cozimento mais rápido e econômico. Versáteis, podem ser utilizadas em diferentes tipos de fogão, incluindo indução, além de irem ao forno, tornando o preparo das suas receitas ainda mais prático e funcional, sem abrir mão de um design moderno com acabamento em alto brilho. Características: Material: Aço Inox Acabamento externo: Alto brilho Acabamento interno: Não possui Compatível com fogão por indução: Sim Fundo: Triplo (aço inox + alumínio + aço inox) Temperatura máxima no forno: 260°C Lavável em lava-louças: Sim Garantia: 03 Meses contra defeitos de fabricação. Conteúdo da embalagem: 01 panela 16 cm 1,4 L 01 caçarola rasa 20 cm 2,9 L 01 caçarola funda 20 cm 3,60 L 01 frigideira sem tampa 20 cm 2,20 L 01 cozi-vapore 20 cm 2,20 L', 790.8, 790.8, NULL, 'Home & Living > Kitchenware > Pots', 'https://cf.shopee.com.br/file/sg-11134201-820lk-mnmxc514ddz692', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1083800536%2F58259825296', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '45653139986', 'Chuteira Umbro Futsal Attak III Preto - Masculino', 'Mais controle, tração e velocidade dentro das quadras! Chuteira Umbro Futsal Attak III Preto – Masculino Ficha Técnica: Marca: Umbro Cor: Preto com detalhes em grafite no solado Gênero: Masculino Indicado: Futsal (uso indoor) Cabedal: 100% sintético com acabamento frequenciado que proporciona leveza, resistência e ajuste anatômico Palmilha: X-Comfort em EVA para maior amortecimento Sola: 100% borracha ID Vortex com máxima tração Fechamento: Cadarço Amortecimento: Médio Estabilidade: Alta Tecnologias: Cabedal leve e flexível, palmilha X-Comfort e solado ID Vortex Detalhes: Forro 100% poliéster para maior respirabilidade e conforto A Umbro Attak III é ideal para jogadores que não abrem mão de precisão e estabilidade nas quadras. Porque investir: Seu solado ID Vortex garante tração em todas as direções, enquanto o cabedal leve oferece flexibilidade sem perder a resistência. A palmilha X-Comfort proporciona amortecimento extra para que você jogue com confiança e intensidade. Conteúdo da embalagem: 1 par de Chuteira Umbro Futsal Attak III Preto – Masculino', 249.99, 249.99, NULL, 'Sports & Outdoors > Sports Footwear > Futsal Shoes', 'https://cf.shopee.com.br/file/sg-11134201-822yu-mia8i9yyysqq6c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1175741090%2F45653139986', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43131000752', 'Mocassim Anacapri Bold Pala Removível Marrom - Feminino', 'Um mocassim, dois estilos! Mocassim Anacapri Bold Pala Removível Marrom - Feminino Ficha Técnica: Marca: Anacapri Gênero: Feminino Cor: Marrom com detalhes em dourado Indicado: Dia a dia, trabalho e ocasiões casuais Cabedal: Material sintético com acabamento liso Palmilha: Macia e confortável Sola: Borracha marrom com construção bold levemente elevada Fechamento: Slip on Amortecimento: Confortável Estabilidade: Alta Entressola: Borracha Tecnologias: Estrutura leve com conforto prolongado Detalhes: Pala removível estilo tassel, com aplicação de metais laterais, costura pesponto e acompanha pala extra para personalização do estilo. Se você busca praticidade sem abrir mão do estilo, esse modelo é a escolha certa. Com design moderno e detalhe removível, ele se adapta facilmente ao seu look. Porque investir: Versátil, confortável e atual, é perfeito para quem quer um calçado que acompanha diferentes momentos com elegância. Um verdadeiro curinga no guarda-roupa. Conteúdo da embalagem: 1 par de Mocassim Anacapri Bold Pala Removível Marrom - Feminino', 289.99, 233.99, NULL, 'Women Shoes > Flats > Loafers & Boat Shoes', 'https://cf.shopee.com.br/file/sg-11134201-822z4-moe4rxuriadle6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1175741090%2F43131000752', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259235302', 'Panela Eltrica de Presso Mondial PE-47 Pratic Cook 3L - Inox', 'Praticidade e rapidez na cozinha agora virou realidade com a incrvel Panela de Presso Eltrica Mondial PE-47 Pratic Cook, que te auxilia a preparar as melhores receitas com facilidade e rapidez no preparo graas as suas 10 funes, sendo uma delas, a de manter a sua comida quentinha por mais tempo. Possui uma vlvula de segurana que mantm a presso interna da panela totalmente equilibrada, alm de uma capacidade de 3L que permite voc cozinhar vrias opes e com um volume maior se necessrio. Quer praticidade na hora de lavar a loua? Sua cuba interna removvel e antiaderente, que proporciona uma lavagem fcil e prtica. Falando mais ainda em praticidade, a Panela de Presso Eltrica Mondial PE-47 Pratic Cook possui tampa com ala ergonmica, trmica e com trava, garantia de segurana na hora de preparar suas receitas. Viu s quantos benefcios com a Panela de Presso Eltrica Mondial PE-47 Pratic Cook? No perca mais tempo e garanta j a sua! Caractersticas: Antiaquecimento externo: No Lmpada piloto: Sim Porta-fio: No Desligamento automtico: sim Consumo de energia (kW/h): 0,7kw/h Temperatura mxima (C): No aplicvel Capacidade (litros): 3L Potncia (W): 700W Capacidade de alimentos (g): No aplicvel Tenso/Voltagem: 110V|220V Tipo de Tomada: 10A (4mm) Tipo de Plugue: 3 Pinos Contedo da Embalagem: 1 Panela de Presso Eltrica 1 Colher 1 Copo Medidor 1 Livro de Receitas 1 Manual de Instrues Garantia do fornecedor: 12 meses Ateno: Verificar voltagem do produto. Fotos meramente ilustrativas. Demais produtos que no fazem parte do contedo da embalagem, so ilustrativos e no so vendidos com o produto. No nos responsabilizamos pela instalao ou montagem; tambm no nos responsabilizamos pelo transporte por escadas ou elevadores. Todas as instrues, manuais e peas necessrias para a montagem so fornecidas junto com o produto.', 408.4, 408.4, NULL, 'Home Appliances > Kitchen Appliances > Pressure Cookers', 'https://cf.shopee.com.br/file/sg-11134201-820me-mnacvddtb210a1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1083800536%2F58259235302', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58204149169', 'Kit 2x Luteína e Zeaxantina Vision Guard com Vit A 60 Caps Nutrilibrium', 'LUTEÍNA E ZEAXANTINA- VISION GUARD INGREDIENTES: Luteína (Luteína da flor de Tagetes erecta), Licopeno (Licopeno de tomate), Zeaxantina (Zeaxantina), Vitamina C (Ácido ascórbico), Vitamina E (Acetato de D-alfa-tocoferol), Vitamina B6 (Cloridrato de piridoxina), Zinco (Óxido de Zinco), Vitamina A (Betacaroteno e Acetato de Retinol), Selênio (Selenito de Sódio) e Antiumectante Dióxido de Silício. INGREDIENTES DA CÁPSULA: Gelatina, Água Potável Filtrada e Corante Dióxido de Titânio. NÃO CONTÉM GLÚTEN. SUGESTÃO DE USO: Consumir 1 (uma) cápsulas 1 (uma) vez ao dia. PRODUTO INDICADO PARA MAIORES DE 19 ANOS. ADVERTÊNCIAS: “ESTE PRODUTO NÃO É UM MEDICAMENTO”. “NÃO EXCEDER A RECOMENDAÇÃO DIÁRIA DE CONSUMO INDICADA NA EMBALAGEM”. “MANTENHA FORA DO ALCANCE DE CRIANÇAS”. “ESTE PRODUTO NÃO DEVE SER CONSUMIDO POR GESTANTES, LACTANTES E CRIANÇAS”. CONSERVAÇÃO: Manter em lugar fresco, não úmido e ao abrigo de luz. Não consumir o produto se o lacre de proteção estiver violado. Após aberto, consumir preferencialmente em 80 dias.', 119.87, 95.9, NULL, 'Health > Food Supplement > Well Being', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mjzuna10pa837a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F443076516%2F58204149169', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '52005364424', 'Conjunto Infantil Masculino Capivara Tenista', 'Descrição: Conjunto Infantil Masculino Capivara Tenista Conjunto masculino em meia malha na parte superior e moletinho na parte inferior (100% algodão). Camiseta azul marinho com estampa frontal e bermuda vermelha com cadarço decorativo fofo! Tudo pensado e produzido com muito amor e carinho. Selecionamos os melhores materiais para crianças que desejam ser destaque por onde passam! Guia de Tamanhos Como medir a criança? Utilizando uma fita métrica, envolva as regiões a serem medidas. Busto: Enrole a fita métrica em torno do corpo, na linha do peito. Comprimento: Comece pelo topo do ombro e meça até chegar no comprimento desejado. Quando for calça, short ou saia, comece medindo na linha da cintura. Cintura: Enrole a fita métrica em torno da cintura, sem apertar. As medidas da tabela abaixo são referentes á parte frontal da peça, então busto e cintura você deve multiplicar por 2. A tabela pode sofrer alterações de 1 á 2 cm para mais ou menos, leve isso em conta na hora de selecionar o tamanho adequado. Características: - Estação: Verão - Gênero: Masculino - Composição: 100% Algodão - Tecido Parte Superior: Meia Malha - Tecido Parte Inferior: Moletinho - Faixa Etária: 1 à 12 anos - Garantia: 1 Mês - Tipo de Roupa: Conjunto - Tabela de Medidas: Tabela de Medidas Camiseta: Tamanho | Busto | Comprimento 1 | 25CM | 31CM 2 | 27CM | 33CM 3 | 29CM | 35CM 4 | 31CM | 40CM 6 | 35CM | 43CM 8 | 36CM | 44CM 10 | 37CM | 47CM 12 | 40CM | 51CM Tabela de Medidas Bermuda: Tamanho | Cintura | Comprimento 1 | 19CM | 20CM 2 | 19CM | 22CM 3 | 20CM | 25CM 4 | 21CM | 29CM 6 | 25CM | 31CM 8 | 25CM | 33CM 10 | 26CM | 34CM 12 | 28CM | 36CM', 34.9, 24.9, NULL, 'Baby & Kids Fashion > Boy Clothes > Suits & Sets', 'https://cf.shopee.com.br/file/sg-11134201-8261n-mjyhxs6vufba6e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F717393801%2F52005364424', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20998861654', 'Kit Home Care Trivitt Itallian Color Hidratação Fluido Repar', 'O Combo Profissional Trivitt com 05 Produtos da Itallian Color é a solução completa para quem busca cuidados capilares intensivos e profissionais em casa. Este kit é ideal para todos os tipos de cabelo, especialmente aqueles que passaram por processos químicos e necessitam de hidratação, proteção e reparação. O Fluído para Escova Trivitt 300ml é o aliado perfeito para quem utiliza secador. Ele facilita a escovação, oferece proteção térmica e evita pontas duplas. Sua fórmula avançada acelera a secagem dos fios e forma um filme protetor que proporciona brilho intenso e maciez. Com ativos como filtro solar, queratina vegetal e óleo de camelina dourada, ele restaura e conserva a hidratação dos cabelos, deixando-os sedosos e protegidos contra danos solares. O Reparador de Pontas Trivitt 30ml é essencial para manter as pontas dos cabelos saudáveis e brilhantes. Com um blend de silicones, ele forma uma película protetora que repara pontas duplas e condiciona os fios sem deixá-los pesados ou oleosos. O produto também oferece proteção contra os raios UV-B, garantindo que os cabelos fiquem protegidos e com um brilho tridimensional. O Kit Home Care Hidratação da Itallian Trivitt é composto por um Shampoo Pós-Química, um Condicionador Trivitt e uma Hidratação Intensiva. Este conjunto é ideal para cabelos quimicamente tratados, oferecendo hidratação profunda, maciez e resistência. O shampoo limpa suavemente, preparando os fios para o condicionador, que garante um condicionamento profundo. A Hidratação Intensiva restaura o brilho e a vitalidade dos cabelos, protegendo-os contra frizz e ressecamento. Para usar o combo, inicie com o Shampoo do Kit Home Care, seguido do Condicionador ou da Hidratação Intensiva para um tratamento mais profundo. Aplique o Fluído para Escova antes de usar o secador para proteger e facilitar a escovação. Finalize com o Reparador de Pontas para selar e proteger as pontas dos cabelos. Os benefícios deste combo incluem cabelos mais resistentes à quebra, com brilho e maciez intensos, além de proteção contra o frizz e ressecamento. A combinação dos produtos proporciona um cuidado completo, reequilibrando a hidratação e protegendo os fios de agentes externos, garantindo um resultado profissional no conforto da sua casa. Cuidados: Todos os produtos são de uso externo e devem ser mantidos fora do alcance de crianças. O Reparador de Pontas tem validade de 36 meses, garantindo longa duração na sua rotina de cuidados.', 289.46, 251.84, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/br-11134207-7r98p-ll9lyxv9nrr0a6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F969993035%2F20998861654', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42651864299', 'Máquina De Solda Inversora 170a Portátil Mma Tig Bivolt Start Com Acessórios Fusion Arc 170', 'MÁQUINA DE SOLDA INVERSORA 170A PORTATIL ELETRODO 3.5MM MMA TIG BIVOLT 110V/220V COM ACESSORIOS FUSION ARC 170 Start A Máquina de Solda Inversora Start Fusion Arc 170 é uma ferramenta portátil de alta tecnologia, ideal para serralheiros e usuários que precisam realizar trabalhos dentro e fora da oficina. Equipamento seguro, robusto e confiável, acompanha o soldador em diferentes locais de trabalho. CARACTERÍSTICAS: - Alto Desempenho - Proporciona Excelente Soldabilidade e Fácil Abertura de Arco Com Eletrodos E6013, Sendo Perfeita para Eletrodos de Até 3,5mm. - Bivolt - Possui Tensão de Alimentação Automática de 127v e 220v. - Praticidade - Com Alça de Ombro para Transporte, é Compacta e Pode Ser Guardada Em Armário de Ferramentas, Mochila ou Baú de Moto. - Painel Fácil - Permite Ajuste dos Parâmetros de Acordo Com a Bitola do Eletrodo, Facilitando a Regulagem. - Economia - Alta Eficiência Energética, Garantindo Menor Consumo de Energia. VANTAGENS: - Por ser um equipamento leve e pequeno facilita muito o trabalhos em locais de difícil acesso ou em altura elevada; - Possui visor digital para melhor visualiação do trabalho exigido; - Solda aço, aço carbono, entre outros metais ferrosos. FICHA TÉCNICA: Fator de Trabalho: 80% - 170A 220V / 80% - 120A 127V Eletrodo: 1,6 a 3,5mm 220V / 1,6 a 2,5 127V Conectores: Engate Padrão: 9mm Corrente de Saída Máxima: 170A Grau de Proteção: IP21S Voltagem: 110/220V Funções: MMA / TIG ITENS INCLUSOS: - 01 Manual de Instruções: - 01 Garra de Aterramento; - 01 Porta Eletrodo 200A; - 01 Cabo de Alimentação; - 01 Inversora. Marca: Start Modelo: Fusion Arc 170', 630.0, 299.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-825aq-mq3sivv33yf608', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F360012700%2F42651864299', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22593216542', 'Chumbinho Technogun Sonic Gold 5.5mm - 250un', 'O Chumbinho Technogun Sonic Gold 5.5mm é a escolha ideal para atiradores que buscam máxima penetração, precisão e estabilidade em tiros de longa distância. Com um design aerodinâmico pontiagudo e um revestimento exclusivo de latão, reduz o atrito dentro do cano da arma, resultando em disparos mais potentes e eficientes. Por que escolher o Sonic Gold 5,5mm? Revestimento em latão: Proporciona menor atrito e mais potência nos disparos. Alta precisão e impacto: Balanceamento centrífugo uniforme para tiros mais estáveis e consistentes. Indicado para média e alta pressão: Ideal para tiro esportivo e prática de precisão. Perfuração eficiente: Design aerodinâmico otimizado para máxima penetração, garantindo alto desempenho em alvos como papel, papelão, latas e garrafas PET cheias. Tecnologia nacional: Produzido no Brasil pela Pesca Brasil, utilizando um sistema de injeção em alta pressão patenteado. Características Marca: Technogun Modelo: Sonic Gold Penetração Calibre: 5.5mm (.22) Peso: 1,05g (16,13 grains) Quantidade: 250 unidades Material: Liga de chumbo com banho de latão Finalidade: Tiro a longa distância e alta penetração Cor: Dourado Atenção Nunca atire em superfícies duras (pedras, paredes de alvenaria ou chapas de aço), pois há risco de ricochete. Utilize sempre em um ambiente seguro e com óculos de proteção. Posicione os alvos com um fundo seguro, como barrancos de terra ou chapas de EVA, para evitar transfixação. Mantenha fora do alcance de crianças e animais e utilize com responsabilidade. Garantia 3 meses contra defeitos de fabricação. Itens Inclusos 1x Lata de Chumbinho Technogun Sonic Gold 5.5mm (250 unidades) 1x Nota fiscal Imagens meramente ilustrativas. As cores e detalhes podem variar conforme sua tela e o produto final.', 67.8, 67.8, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Shooting & Survival Games', 'https://cf.shopee.com.br/file/sg-11134201-822yu-mi4vywo7vymb94', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F654132276%2F22593216542', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18798102978', 'Tenis Botinha Infantil Meninos Casual Cano Alto Confortavel + Oculos', 'Dê um toque de estilo e conforto para os pequenos com o Tênis Botinha Casual Infantil! Com um design moderno e sofisticado, esse modelo de cano alto é perfeito para diversas ocasiões, desde passeios até momentos especiais. Estilo e Versatilidade – Combina com diferentes looks, ideal para o dia a dia. Material Resistente – Produzido em couro sintético de alta qualidade. Ajuste Confortável – Fechamento em cadarço para um encaixe firme e seguro. Forro Interno Macio – Maior conforto para os pés durante o uso. Sola Antiderrapante – Proporciona mais estabilidade e segurança ao caminhar. Garanta já esse tênis botinha incrível e ofereça estilo e conforto para seu filho! Conteúdo do anúncio: 1 Par de tênis infantil Light 1 Óculos infantil Não lavar em máquina de lavar roupas. Usar apenas pano úmido. Secar na sombra para manter a qualidade e durabilidade do calçado. Garantia e Medidas: Nossos produtos possuem garantia contra defeitos de fabricação. Para garantir o tamanho ideal, meça o pé da criança e escolha a numeração com 0,5 cm de folga. Isso evita problemas com trocas por tamanho. Tabela de Medidas: 20 - 13,5 cm 21 - 14,0 cm 22 - 14,5 cm 23 - 15,5 cm 24 - 16,0 cm 25 - 16,5 cm 26 - 17,5 cm 27 - 18,0 cm 28 - 19,0 cm 29 - 19,5 cm 30 - 20,0 cm 31 - 21,0 cm 32 - 21,5 cm 33 - 22,0 cm 34 - 23,0 cm 35 - 24,0 cm 36 - 24,5 cm Evite problemas com trocas por tamanho decidindo com atenção a numeração desejada, seguindo a tabela acima! Garantia do Vendedor: 7 dias.', 78.99, 51.99, NULL, 'Baby & Kids Fashion > Boy Shoes > Sneakers', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m7dj6lpek7d8f3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F908041635%2F18798102978', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58201106571', 'Mixer Pratic Mondial M15B Preto', 'O Mixer Turbo Preto Inox M-16-BI - Mondial é o aliado perfeito para deixar sua rotina na cozinha mais prática e eficiente. Com 500W de potência e função turbo, ele tritura e mistura alimentos com rapidez, garantindo receitas cremosas, homogêneas e com a textura ideal. Equipado com lâminas em aço inox de múltipla função, realiza cortes simultâneos na vertical e horizontal, proporcionando resultados consistentes em sopas, cremes, sucos, vitaminas, molhos e até papinhas. Sua haste em aço inox super-resistente suporta altas temperaturas, ideal para preparos quentes, além de não absorver odores nem manchar. Feito pela fabricante Mondial, o mixer é confeccionado com materiais de alta qualidade, com design com design moderno e ergonômico, é fácil de manusear e garante praticidade no dia a dia, transformando o preparo dos alimentos em uma experiência rápida e eficiente. O mixer acompanha uma jarra de 800ml com tampa e graduação lateral, prática para armazenar e medir receitas. Seu corpo desmontável facilita a limpeza e permite guardar o aparelho até em espaços menores.', 275.9, 195.89, NULL, 'Home Appliances > Kitchen Appliances > Mixers', 'https://cf.shopee.com.br/file/sg-11134201-823qb-mos9zjpa2gwbc1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1081505086%2F58201106571', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21098198783', 'Jogo Serviço Americano Color Suplat Avulso Terracota 44cm', 'Delicadeza e romantismo à mesa em cores modernas e atuais, você encontrará nos jogos americanos Color Copa&Cia. Com detalhes delicados, com diversas cores para compor diferentes momentos à mesa, são peças atemporais e muito versáteis nas composições de mesa posta. São uma excelente opção para suas combinações de decor na mesa posta.Porque usar Jogos Americanos em Sua Mesa posta:Uma das vantagens em usar os Jogos Americanos na mesa posta é a facilidade em fazer e desfazer o decor da mesa. Basta dispor os jogos americanos conforme a disposição dos lugares e apoiar pratos, talheres, copos e outros itens sobre ele.Ajudam a manter a mesa limpa, pois evitam que respingos e sujeiras caiam sobre a mesa, demarcam os lugares, organizando a disposição dos itens sobre a mesa e das pessoas à mesa.No fim da refeição, basta passar um pano úmido para limpá-los e guardá-los. Simples, rápido e de fácil manutenção. Feitos com materiais resistentes os Jogos Americanos da Linha Color, podem durar por muito tempo e não precisam de lavagem imediata após o uso. Portanto, são perfeitos para o uso diário.Os jogos Americanos sem dúvida valorizam o design da mesa, das louças e os complementos da mesa posta, dão aquele toque visual a refeição que será servida, pois também despertam o sentido visual.Detalhes:Composto por 100% Policloreto de VinilaPossui toque macioPeça Prática destinada ao uso diário FlexívelCor/Estampa: TerracotaDimensões: 44cm de comprimento e 28,5 de larguraCuidados Recomendados:Não Torcer, Amassar, Dobrar ou Molhar Totalmente o Produto;Não Utilizar Solventes ou Abrasivos;Evitar contato com objetos cortantes ou superaquecidos;Limpar manualmente com pano úmido e detergente neutro.O que acompanha?1 peça de Jogo Americano', 31.9, 22.65, NULL, 'Home & Living > Dinnerware > Placemats & Coasters', 'https://cf.shopee.com.br/file/sg-11134201-7ravn-ma2sdll8e1012b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1081505086%2F21098198783', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22098196327', 'SHAMPOO ELSEVE SUPER ALINHADOR LISO DOS SONHOS LORÉAL 200ML (LANÇAMENTO 2025 )', 'SHAMPOO ELSEVE LISO DOS SONHOS SUPER ALINHADOR 200ML O Shampoo Super Alinhador limpa e fortalece a fibra preparando os fios para um liso de longa duração e com frizz controlado. Enriquecido com AHA + QUERATINA VEGETAL, Elseve Liso dos sonhos é o nosso 1ª tratamento em casa que transforma os fios para 1 semana de cabelos lisos e à prova de umidade. Resultados que resistem ate 5 lavagens. - 2X mais liso, 2x menos frizz - 15X mais sedoso - 3X mais fácil de desembaraçar Modo de Uso Aplique nos cabelos molhados, massageie e enxágue. Repita se necessário.', 23.99, 23.99, NULL, 'Beauty > Hair Care > Shampoo', 'https://cf.shopee.com.br/file/sg-11134201-7rbn9-m5pvqnyf89p3a3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F290598330%2F22098196327', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '2956143679', 'Kit Pesca De Praia Vara 3,60 Molinete Caixa e Acessórios', 'Kit de Pesca especialmente elaborado para você amigo pescador que vai desfrutar de uma diversão na Praia ou Em Rios e Lagos . Com ele poderá fisgar diversos tipos de peixe como : Perna de Moça , Baiacu , Tainhas , Lambaris, Tilapias, Pacus, Tambacus , Tambaquis, Piaus , dourados , Pintados, Surubuins , Cacharas, Carpas , Matrinxãs ,Bagres , Traíras , Curvinas , Tucunarés e outros 1 Vara Para Molinete Telescopica 3,60m Araxa Xingu ESPECIFICAÇÕES: Marca: Xingu Modelo: Araxá Tamanho aberto: 3,60m Tamanho fechado: 67cm Peso: 220g Resistencia: 2-4kg Ação: Média Material: Fibra de vidro Passadores: 4+1 ponteira 1 Molinete 3 Rolamento Araguaia 2000 ou Deyu 2000 Modelo: Araguaia, ou Deyu Rolamentos: 3 Recolhimento: 5.5:1 Capacidade de Linha: 0,18mm-245m / 0,25mm-125m Peso: 390g 1 Caixa/Maleta Para Pesca 1 Bandeja Articulada Preta 1 linha monofilamento 0,25 com 100 metros (em alguns modelos de molinete a linha já vai enrolada) Anzol 4330 Super Strong Marine Sports Niquelado Nickel,facilita fixar a isca e também ao fisgar do peixe a ser pescado, pois possui farpas muito eficiente que facilitam a pesca 10 Anzol 4330 Nº1 (3,1 cm) 10 Anzol 4330 Nº6 (2,0 cm) 10 Anzol 4330 Nº8 (1,8cm) 10 Anzol 4330 Nº10 (1,5 cm) 2 Giradores simples em aço carbono nº7, super resistente. Utilizado para evitar torção da linha. 3 Lider Aço Encastoador Nº 6 2 Jig 3/0 10gr para camarão 2 Camarão de 8cm cor conforme disponibilidade em estoque 2 Chumbada Piramide 1 - 28,35gr 2 Chumbada Piramide 1.1/2 - 42,52gr 1 Chumbada Gota 20gr 1 Chumbada Gota 40gr 1 Sinete/Alarme de Espera utilizado em vara', 219.89, 197.91, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Fishing', 'https://cf.shopee.com.br/file/sg-11134201-7rbn7-lp5lc