INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23798839304', 'Película para iPhone 17 Pro Max - Dual Glass Preta - Gshield', 'Proteja a seu dispositivo com a melhor película para iPhone 17 Pro Max A Película Dual Glass para iPhone 17 Pro Max, da GShield, foi desenvolvida para proteger o seu smartphone dos impactos do dia a dia. Fabricada com a mais moderna tecnologia anti-impacto, o acessório garante a segurança do aparelho sem alterar o design e o toque. Não espere o celular ser danificado para tomar uma providência. Invista na película Coverage e previna-se das dores de cabeça.', 142.97, 142.97, NULL, 'Mobile & Gadgets > Accessories > Screen Protectors', 'https://cf.shopee.com.br/file/sg-11134201-7rdvj-mdsip4ttowh6ab', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F339198085%2F23798839304', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22498316561', 'Capa Capinha Apple Watch - Preta / Transparente Proteção Militar - Gshield', 'A Case Armor para Apple Watch, da Gshield, foi projetada para dar proteção a tela de seu Apple Watch, reduzindo as chances de danos por impacto e arranhões. Além de proteger a tela do seu Apple Watch, ela também protege suas laterais mantendo-o sempre novo. Atenção: Não acompanha o relógio e pulseira , as imagens são só ilustrativas para mostrar o produto instalado. ESPECIFICAÇÕES Material: Plastico TPU Marca: Gshield Dimensões: Dimensões exatas do aparelho Proteção: Contra impactos e riscos à tela e laterais Certificações: Us Military Cor: Preta e Transparente COMPATIBILIDADE Apple Watch ITENS INCLUSOS 1x Case protetora', 49.0, 49.0, NULL, 'Mobile & Gadgets > Accessories > Wearable Accessories', 'https://cf.shopee.com.br/file/sg-11134201-7rd75-m79wmtjohgxd8f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F339198085%2F22498316561', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
