INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12220409452', 'Película Nano Traseira para Xiaomi Redmi Note 9 Pro - Gshield', 'DESCRIÇÃO Proteja a traseira do seu smartphone com a película Nano Traseira da Gshield! A Película Nano Traseira, protege seu aparelho contra riscos e arranhões na parte de trás. Ideal para os adeptos ao uso do aparelho sem uso de capa, mas para uma maior proteção, as películas traseiras também podem ser usadas em conjunto com as capas da Gshield, evitando o acúmulo de detritos no interior do acessório e eventuais arranhões no celular. ESPECIFICAÇÕES Material: Hidro nano pet Marca: Gshield - ( Gorila Shield ) Espessura: 0,10mm Proteção: Contra pequenos impactos e riscos à traseira Grau de transparência: 98% High Definition Certificações: US Military Dimensões: Cobre as dimensões da traseira do aparelho, podendo haver pequenos recuos para melhor aderência', 21.97, 21.97, NULL, 'Mobile & Gadgets > Accessories > Screen Protectors', 'https://cf.shopee.com.br/file/97cea76f0427a3a1f9ac8ba1b49f5667', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F339198085%2F12220409452', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '54606497082', 'Caminhão de Reciclagem do Rocky com Boneco - Patrulha Canina', 'O caminhão de reciclagem do Rocky da Patrulha Canina transforma cada missão em uma aventura sustentável! Com design autêntico, rodas que giram, garfo móvel e escotilha funcional, o veículo reproduz o visual da série e estimula o jogo imaginativo. Rocky veste seu uniforme de reciclagem e está pronto para ensinar o valor do cuidado com o planeta. Feito com pelo menos 80% de plástico reciclado pré-consumo, o brinquedo combina diversão e consciência ambiental. Ideal para crianças que adoram explorar, criar histórias e fazer parte do universo heroico da Patrulha Canina.REGISTRO INMETRO 004740/2020', 129.99, 122.19, NULL, 'Hobbies & Collections > Collectible Items > Action Figurines', 'https://cf.shopee.com.br/file/sg-11134201-8262o-ml6j12ttcdfx09', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F341622697%2F54606497082', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '10454930732', 'Película Traseira de Fibra de Carbono Transparente para Motorola Moto Z2 Force - Gorila Shield', 'A Película Traseira de Fibra de Carbono, da Gorila Shield, protege seu aparelho contra riscos e arranhões na parte de trás do aparelho. Para uma maior proteção, as películas traseiras podem ser usadas em conjunto com as capas da Gorila Shield, evitando o acúmulo de detritos no interior da capa e eventuais arranhões.', 9.99, 9.99, NULL, 'Mobile & Gadgets > Accessories > Screen Protectors', 'https://cf.shopee.com.br/file/49296c43b452463d0d888f23210b5851', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F339198085%2F10454930732', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '13920388455', 'Película para Lente de Câmera para Xiaomi Mi 9T - Gorila Shield', 'A Película para Lente da Câmera , da Gorila Shield, é projetada para garantir uma proteção extra para a câmera do seu smartphone. Fabricada em vidro temperado ionizado e 0,27mm de espessura, a película da Gorila Shield garante segurança em curtos impactos e riscos do cotidiano.', 5.47, 5.47, NULL, 'Mobile & Gadgets > Accessories > Screen Protectors', 'https://cf.shopee.com.br/file/d86621dc558c7a1f73f3db830044f3da', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F339198085%2F13920388455', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22393569626', 'Mesa De Jantar Redonda Charles Eames Eiffel 70cm Branco', 'Bem Vindo a Cadeiras Inc Mesa De Jantar Cozinha Redonda Eiffel Para 4 Lugares 70cm Que tal uma mesa de jantar estilosa com espaço para aproveitar aquelas refeições especiais, seja no café da manhã, almoço ou jantar, reunir a família é sempre uma delícia, né? E de quebra sua sala de jantar ganha uma aliada para o visual. O tampo amplo, é ideal para você dispor todos os pratos, copos e aquelas receitas especiais que todo mundo ama ou até para deixar aquele vaso com flores quando o móvel não estiver em uso. O modelo também possui um design que vai deixar o ambiente digno de capa de revista: junta pés palito, cores sóbrias e tampo redondo, tudo para dar um toque sofisticado à decoração e te ajudar a construir o lar-style dos sonhos. Para completar, a estrutura te permite posicionar até 4 cadeiras que devem ser adquiridas à parte, sua única tarefa vai ser encontrar os complementos perfeitos, deixando o cantinho gourmet da sua casa pronto para qualquer ocasião. Descrições Técnicas da Mesa Charles Eames Eiffel: Altura Total: 72cm Diâmetro: 70cm Garantia: 3 meses contra defeito de fabricação', 359.9, 335.9, NULL, 'Home & Living > Furniture > Desks & Tables', 'https://cf.shopee.com.br/file/sg-11134201-7rfhk-m3dpdcyxiysdfc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F687950391%2F22393569626', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19248625295', 'Meia Esportiva Corrida Ciclismo Mtb Speed Masculina Ride Pith', 'Desempenho, conforto e proteção para os seus pés durante as atividades físicas! A Meia de Compressão Pith é ideal para quem pratica esportes como corrida, ciclismo, MTB, crossfit, cross training, atletismo e outras modalidades. Benefícios: ✅ Melhora a circulação sanguínea e o aporte de oxigênio nos músculos ✅ Reduz a fadiga e o risco de lesões ✅ Ajuda na recuperação muscular pós-treino ✅ Alta ventilação e controle térmico ✅ Conforto e ajuste ideal ao pé Características Técnicas: • Composição: 86% Poliamida, 8% Poliéster, 3% Elastano, 3% Outras Fibras • Tamanho: Veste do 34 ao 39 • Marca: PITH • Indicações: Ciclismo, MTB, CrossFit, Corrida, Atletismo e outros esportes de alta performance • Design com zonas de ventilação estratégica para respiração da pele • Produto leve, elástico e com ótimo ajuste anatômico Garantia de Qualidade: • Produto original PITH • Nota fiscal e garantia de fábrica Informações Importantes: ✓ Produto novo, com nota fiscal e envio imediato! ✓ Envio para todo Brasil com segurança! ✓ Envio no mesmo dia para pedidos aprovados até as 11h (segunda a sexta)', 28.9, 19.84, NULL, 'Men Clothes > Socks', 'https://cf.shopee.com.br/file/sg-11134201-22090-b3bardw3kshv97', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F801784100%2F19248625295', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
