INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '17761113768', 'Ração Premier Raças Específicas Maltês Cães Adultos Peru e Arroz 7,5kg', 'A Ração Premier Maltês Adultos Peru e Arroz contém ingredientes nobres como peru, salmão, arroz e aveia que proporcionam uma digestão fácil e rica em nutrientes, apresenta ingredientes que auxiliam na prevenção da formação da placa bacteriana e do tártaro. Indicado para cães adultos da raça Maltês, a partir de 1 ano de idade. Sua combinação de ingredientes de altíssima qualidade e de fácil digestão são facilmente aproveitáveis, favorecendo e redução do odor e volume das fezes. Ingredientes Farinha de vísceras de frango, farinha de carne e ossos de peru (10%), farinha de torresmo, glúten de milho (não transgênico), glúten de trigo, ovo em pó, grão de sorgo, quirera de arroz (35%), aveia (2,5%), polpa desidratada de beterraba, banha refinada, gordura de frango, óleo refinado de peixe, cloreto de potássio, cloreto de sódio, antioxidante natural (concentrado de tocoferóis, extrato de alecrim, extrato de chá verde, extrato de menta, hortelã – mín. 0,05%), bentonita, extrato de yucca (0,06%), hexametafosfato de sódio (0,10%), hidrolisado de fígado de aves e suíno, parede celular de levedura, vitamina A, vitamina B1, vitamina B2, vitamina B3, vitamina B5, vitamina B6, vitamina B7, vitamina B9, vitamina B12, vitamina C, cloreto de colina, vitamina D3, vitamina E, vitamina K3, ferro aminoácido quelato, iodato de cálcio, manganês aminoácido quelato, óxido de magnésio, selenometionina hidroxi análoga, sulfato de cobre pentahidratado, sulfato de ferro, sulfato de manganês, sulfato de zinco monohidratado, zinco aminoácido quelato.', 219.9, 202.31, NULL, 'Pets > Pet Food > Dog Food', 'https://cf.shopee.com.br/file/br-11134207-81z1k-merid1ryb9q865', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fs