INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18397419520', 'Aparelho De Barbear Bic Comfort 2 Twin Pele Normal C/2Un', 'O Aparelho BIC Comfort 2 Pele Sensível proporciona um barbear com máxima lubrificação, pois sua fita lubrificante com Aloe Vera e Vitamina E auxiliam na retirada de pelos sem agredir a pele. Possui duas lâminas revestidas de Teflon® proporcionando um barbear rente e confortável. Seu cabo antideslizante ajuda no maior controle no barbear. Modo de uso: Lave o rosto para remover a oleosidade, sujeira e pele morta, preparando sua pele para um deslizar confortavel. Aplique creme, gel ou espuma para ajudar a hidratar os pelos, melhorar o deslizamento da lâmina e ajudar a proteger contra irritação. #html-body [data-pb-style="646BA651979BD"]{justify-content: Flex-start; display: Flex; flex-direction: Column; background-position: Left top; background-size: Cover; background-repeat: No-repeat; background-attachment: Scroll; border-style: None; border-width: 1px; border-radius: 0px; margin: 0px 0px 10px; padding: 10px;}#html-body [data-pb-style="646BA651979D1"]{border-style: None; border-width: 1px; border-radius: 0px; margin: 0px; padding: 0px;}', 22.23, 22.23, NULL, 'Beauty > Men''s Care > Shaving & Grooming', 'https://cf.shopee.com.br/file/sg-11134201-7rblo-lmhfa6lna4udc1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F18397419520', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
