INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19299494797', 'Base Box Baú Solteiro 88x188x34 cm Linho Bege', 'O Baú Solteiro Cama InHouse conta com pistões a gás, melhor marca do mercado, para um fácil manuseio sem esforço, conta com espaço interno para guardar seus objetos deixando assim o quarto com melhor usufruto do espaço. O Baú Solteiro Cama InHouse conta com Madeira em eucalipto de reflorestamento tratada; Revestimento em Tecido Linho Bege Tampa quatro centímetros mais cumprida, evitando necessidade de puxadores; Tampa revestida com espuma na borda frontal; Tratamento antialérgico e antiácaro; Gel Sílica para prevenir concentração de umidade e mofo; Pistões a Gás; Contém jogo de pés; Contém alça de apoio para o colchão. Profundidade interna do Baú: 25 cm Medida sem os pés: 88 cm x 1,88 m x 34 cm Medida com os pés: 88 cm x 1,88 m x 42 cm &nbsp; INFORMAÇÕES IMPORTANTES: Confira as dimensões do produto e certifique-se de que estão adequadas aos elevadores, portas e corredores do local da entrega, pois não fazemos a montagem e desmontagem do produto e/ou portas e janelas, nem içamento pelo lado de fora do prédio ou da residência. A transportadora não realiza a montagem do produto, não sobe escadas, apenas elevadores, caso não suba por elevador, a responsabilidade de subir o produto é do cliente. Foto meramente ilustrativa.', 799.0, 649.0, NULL, 'Home & Living > Furniture > Bed Frames & Headboards', 'https://cf.shopee.com.br/file/sg-11134201-7rdxj-m12x6l1cwb4138', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F785818771%2F19299494797', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
