INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209674684', 'Refil Condicionador Suave Natura Mamãe e Bebê 200ML', 'Refil Condicionador Mamãe e Bebê Natura Mamãe e Bebê Refil Condicionador Suave é a escolha perfeita para cuidar dos cabelos delicados do seu bebê com todo o carinho e cuidado que ele merece. formulado com ingredientes suaves e naturais, ele limpa e hidrata os cabelos do bebê, deixando-os macios, brilhantes e fáceis de pentear. todos os produtos para o bebê são hipoalergênicos. estes produtos foram formulados de maneira a minimizar possível surgimento de alergia. CARACTERISTICAS: feito com com 97% de ingredientes naturais e biodegradáveis. fórmula 100% segura, testada e criada para cuidar da pele sensível dos bebês. proporciona cabelos macios e cheirosos, de fácil enxágue, com fragrância suave. BENEFÍCIOS: testado dermatologicamente idade sugerida: 0 a 3 anos tipo de cabelo: todos os tipos de cabelos hipoalergênico cruelty free vegano DICAS DE USO: Ao abrir o refil, despeje o conteúdo na embalagem regular do produto ou em um recipiente vazio e limpo. logo após lavar os cabelos com o Shampoo Mamãe e Bebê, coloque uma pequena quantidade do condicionador nas mãos e massageie delicadamente o cabelo úmido e lavado do bebê. por fim, enxágue até ser completamente removido.', 38.9, 38.9, NULL, 'Beauty > Hair Care > Shampoo', 'https://cf.shopee.com.br/file/sg-11134201-820oe-mnk67myt5gjm60', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1785523344%2F58209674684', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
