INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22898377740', 'Kit 3 Descarbonizante Car 80 Spray 300ml - Econômico Limpeza TBI Motor Manutenção', 'Descarbonizante Spray Car 80 – Limpeza Interna e Mais Performance Recupere o desempenho do seu motor com uma solução profissional. O Descarbonizante Car 80 remove o acúmulo de carbono, melhora a queima de combustível e ajuda a restaurar a potência do veículo, garantindo funcionamento mais eficiente e econômico. APLICAÇÃO / COMPATIBILIDADE Indicado para: - Corpo de borboleta (TBI) - Carburadores - Bicos injetores - Coletores de admissão - Válvulas de admissão e escapamento - Veículos leves e pesados: carros, motos e caminhões Recomendado para manutenção periódica do sistema (ex: a cada 10.000 km, conforme uso). DADOS TÉCNICOS Tipo: Descarbonizante em spray Conteúdo: 1 unidade Marca: Car 80 Ação: remoção de resíduos de carbono Aplicação: limpeza interna de componentes do sistema de admissão Uso: automotivo leve e pesado QUALIDADE E CERTIFICAÇÕES A Car 80 é referência nacional no segmento automotivo, com mais de 40 anos de mercado. Seus produtos são amplamente utilizados por profissionais da reparação, oferecendo eficiência comprovada, segurança e alto desempenho em manutenção automotiva. RECOMENDAÇÕES IMPORTANTES Restaura desempenho: melhora a resposta do motor e a eficiência da combustão Limpeza eficaz: remove carbonização sem necessidade de desmontagem completa Ação rápida: resultados perceptíveis após a aplicação Produto original: 100% novo e com garantia Uso profissional recomendado: aplicação por mecânico qualificado garante melhor resultado Envio rápido: despacho em até 24h úteis após confirmação Garantia: 90 dias contra defeitos de fabricação', 127.8, 127.8, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Additive and Lubricant', 'https://cf.shopee.com.br/file/sg-11134201-7rfhv-m9zxerlgfxi1b0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1424408486%2F22898377740', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
