INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23693058548', 'Kit 2 Esmalte Risqué Rosas Cremoso Léo Mandou Flores 8ml', 'ESMALTE RISQUÉ COR LÉO MANDOU FLORES A moda não é apenas o que você usa, é também o que você sente. Por isso os esmaltes Risqué tem diversas opções de cores, sempre com novas coleções, uma para cada sensação, para cada momento. Além disso, os esmaltes Risqué possuem três benefícios em um só produto. Sua formulação, aprovada por consumidoras e manicures de todo o Brasil, garante longa duração, secagem rápida e ultra brilho.', 14.72, 14.72, NULL, 'Beauty > Hand, Foot & Nail Care > Nail Care', 'https://cf.shopee.com.br/file/sg-11134201-8259h-mqmc3kjpbfgg9f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F23693058548', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58208494010', 'Firmador Pró Colágeno Sallve Aquagel 30g', 'Firmador Pró-Colégeno Sallve Aquagel 30g O que é e para que serve o SALLVE FIRMADOR PRÓ-COLÁGENO 30G? O Firmador Pró-Colágeno Sallve é um tratamento facial de alta performance desenvolvido para preser', 109.89, 109.89, NULL, 'Beauty > Skincare > Others', 'https://cf.shopee.com.br/file/sg-11134201-823rr-moixsmd062vhb9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F58208494010', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19999870296', 'Kit 2 Tinta de Cabelo Koleston Castanho Dourado Acobreado 54', 'TINTURA CREME KOLESTON WELLA CASTANHO DOURADO ACOBREADO 54 Cor intensa e duradoura. Perfeita cobertura dos cabelos brancos. Koleston tem um reativador de cor! Reative a sua cor entre as colorações, depositando mais pigmentos de cor nos cabelos. No dia da coloração: aplique a coloração normalmente. Os pigmentos penetrarão profundamente, dando aos cabelos uma cor intensa. Este kit contém: 1 Bisnaga Wella koleston tintura creme 55g 1 Frasco aplicador Wella koleston emulsão reveladora / água oxigenada 20vol 55ml 1 Tubo Wella koleston tratamento gloss intenso que contém 4 aplicações 40ml 1 Sachê Wella koleston reativador da cor tratamento com pigmentos 22ml 2 Pares de luvas. 1 Folheto explicativo.', 48.38, 48.38, NULL, 'Beauty > Hair Care > Hair Colour', 'https://cf.shopee.com.br/file/sg-11134201-823r8-mok9wdt7h6vj1e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F19999870296', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18497120955', 'Kit 3 Sabonete Líquido Dove Baby Hidratação Glicerinada da Cabeça aos Pés 200ml', 'Sabonete Líquido de Glicerina Baby Dove Hidratação Glicerinada • Hipoalergênico • pH neutro para a pele do recém-nascido • Sem lágrimas, corantes artificiais, parabenos, ftalatos, sulfatos • Sabonete Líquido com glicerina • Com nutrientes naturalmente encontrados na pele do bebê • Sabonete líquido da cabeça aos pés Nosso Sabonete Líquido da Cabeça aos Pés de Glicerina Baby Dove é hipoalergênico e ajuda a manter a pele saudável desde o primeiro banho do recém-nascido. Comprovadamente minimiza os riscos de alergia com um perfume desenvolvido para a delicada pele do bebê. A hora do banho com seu bebê é especial e, por isso, sabemos que você quer o melhor sabonete líquido para esse momento. Como a pele do bebê é mais fina do que a de um adulto, ela precisa de um cuidado mais delicado. Com glicerina e nutrientes naturalmente encontrados na pele do bebê, ele vai além da limpeza suave, esse produto ajuda a repor os nutrientes essenciais e a hidratação que a pele pode perder durante o banho. Antes de dar o banho no seu bebê que tal limpar primeiro as Toalhas Umedecidas Baby Dove? Elas ajudam a remover as impurezas com suavidade, deixando a pele do bebê ainda mais saudável. Experimente também hidratar o corpo do seu pequeno pelo menos duas vezes ao dia com uma fórmula suave e hipoalergênica como a das loções Baby Dove. Testado por oftalmologista, dermatologista e pediatra. Modo de uso: Aplique uma pequena quantidade nas mãos, ensabe delicadamente a pele e o cabelo do seu bebê. Enxágue em seguida.', 62.67, 62.67, NULL, 'Mom & Baby > Bath & Body Care > Hair Care & Body Wash', 'https://cf.shopee.com.br/file/br-11134201-820lk-mqxep5r7yqyt1e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F18497120955', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23498891114', 'Kit 2 Sabonete Líquido Phebo Amazonian Refil 320ml', 'SABONETE LÍQUIDO PHEBO AMAZONIAN Novo frasco com molde exclusivo. Glicerina vegetal. Fragrâncias únicas e marcantes. Deixa a pele macia e perfumada. Fórmula biodegradável. Livre de parabenos e ingredientes de origem animal. Conteúdo 320ml Modo de usar: Aplique o produto sobre a pele molhada, friccionando suavemente para obter espuma. Em seguida, enxágue.', 56.58, 56.58, NULL, 'Beauty > Bath & Body Care > Body Wash & Soap', 'https://cf.shopee.com.br/file/sg-11134201-823qx-molshaf4ba4h0c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F23498891114', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23794389545', 'Kit 4 Fralda Huggies Pants Roupinha Proteção Acolchoada Tamanho XXG 58 Unidades Descartáveis', 'Fralda Huggies Proteção Acolchoada Pants Tamanho XXG A Fralda Huggies Proteção Acolchoada Pants Tamanho XXG, com 58 unidades, é ideal para bebês em fase ativa que precisam de proteção e conforto. Supreme Care Roupinha agora é Proteção Acolchoada: com o mesmo cuidado e proteção de sempre. Abraço confortável para barriguinha e perninhas. Previne marquinhas e oferece até 12 horas de proteção contra vazamentos*. Seu formato tipo roupinha é fácil de vestir e acompanha cada movimento do bebê. Com cintura super macia e melhor proteção de Huggies* é escolha ideal para quem busca conforto, praticidade e segurança em todos os momentos do dia. *Desempenho pode variar conforme hábitos, alimentação e características do bebê. **vs Huggies Rápida Absorção', 583.96, 583.96, NULL, 'Mom & Baby > Diapering & Potty > Disposable Diapers', 'https://cf.shopee.com.br/file/sg-11134201-8260l-mj78rx7r10jk5d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F23794389545', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
