INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58204168070', 'Bola Adidas Campo Copa 2026 Trionda Club Rosa', 'Bola costurada à máquina para diversão com futebol recreativo. Prepare-se para mostrar seus movimentos no campo de futebol com a Bola Copa do Mundo da FIFA 26™ Trionda Club. Não importa se você está jogando uma partida casual ou aprimorando suas habilidades, esta bola foi feita para resistir aos rigores do jogo. Projetada para quem ama o futebol, sua estrutura costurada à máquina proporciona um toque macio e durabilidade. Com uma câmara de butil, a bola oferece retenção de ar confiável, mantendo-a pronta para a ação sempre que você estiver. Adequada para jogos recreativos, ela oferece uma boa relação custo-benefício sem comprometer a qualidade. adidas traz para você uma bola que incorpora o espírito do futebol, incentivando-o a jogar com paixão e entusiasmo.', 279.9, 251.91, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Soccer, Futsal & Sepak Takraw', 'https://cf.shopee.com.br/file/sg-11134201-8262d-mk00hpf7tqtc63', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1332710855%2F58204168070', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
