INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20698266578', 'Jogo 12 potes de vidro 250ml com tampa de bambu herméticos para tempero - Oikos', '"Conheça o Kit de 12 potes de vidro com tampa de bambu herméticos para mantimentos de 250ml da Oikos! Prático, multiuso e moderno, é o kit de potes com tampa ideal para armazenar e conservar temperos e alimentos. Além disso, os potes podem ser empilháveis e utilizados para guardar diversos itens, como: fios, acessórios, moedas, algodão e o que precisar! Possuem design moderno, com tampa de bambu natural que harmoniza com diversos estilos de decoração e cai bem em diferentes ambientes. As tampas vêm com banho de verniz natural de coco para proteger da umidade! São potes de vidro borossilicato e tampa de bambu. Para limpar a parte de vidro, basta lavar em água corrente com sabão neutro. Para a parte de bambu, é só passar um pano úmido e deixar secar em local arejado. Não deixe a tampa de bambu imersa na água. Leve modernidade e qualidade para sua casa! O kit contém: 12 potes de vidro herméticos empilháveis com tampa de bambu 250ml Medidas individuais: Altura: 10 cm Diâmetro: 6,5 cm Espessura do vidro dos potes: Aproximadamente 2,5 mm."', 341.9, 145.9, NULL, 'Home & Living > Kitchenware > Food Storage', 'https://cf.shopee.com.br/file/sg-11134201-8261f-mlgo5vweygw855', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F752849300%2F20698266578', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
