INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22693551206', 'Tamanco Campesí de Salto Bloco CP571', 'Produto marca Campesí. Descubra o conforto que seus pés merecem com o Tamanco Campesí de Salto Bloco da coleção Primavera/Verão 2024! Perfeito para mulheres que buscam um calçado elegante e prático, este tamanco combina estilo e conforto e está disponível na cor . Seu design moderno e detalhes sofisticados, como a tira trançada e a peça sobre o pé, trazem um toque artesanal e sofisticado para seus looks. Conforto e bem-estar para seus pés estão garantidos, graças ao forro com tecnologia Aloe Vera, que proporciona uma sensação de frescor e hidratação, cuidando da saúde dos seus pés. Além disso, a palmilha macia garante o máximo conforto durante o dia todo. o salto bloco de 3,7 cm proporciona estabilidade e segurança ao caminhar, ideal para o dia a dia e para os momentos de lazer. Com design atemporal, este tamanco combina com diversas peças do seu guarda-roupa, desde jeans e camisetas até vestidos mais elaborados. Perfeito para usar no trabalho, em um passeio no parque ou em um happy hour com as amigas. Peso: 0,507 kg Altura da sola: 3,70 cm', 149.9, 139.9, NULL, 'Women Shoes > Flat Sandals & Flip Flops > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rff0-m310lvb1lblofc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1082095796%2F22693551206', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
