INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19020312753', 'Impermeabilizante Pisos Hidrofuga Super Pisoclean 1L', 'PSC HIDROFUGA SUPER 1L Proteção invisível contra umidade e manchamentos diversos Hidrofuga Super é um hidro/oleofugante base solvente indicado para a máxima proteção dos revestimentos mais porosos. Impede a infiltração de óleos e diversos outros tipos de líquidos. Também protege o revestimento contra a deterioração pela ação da umidade. Trata-se de um produto impregnante que não promove qualquer alteração estética (não promove brilho) e ainda permite a liberação da umidade contida dentro ou abaixo dos revestimentos. Ambientes: Áreas internas, áreas externas. Revestimentos: Todo e qualquer revestimento poroso. Resolve: Risco de manchamentos e eflorescências, umidade, Risco de infiltração, intempéries diversas. Benefícios: Sem alteração estética, Ação contra fungos e musgo. RENDIMENTO: 1L Até 30m²', 229.5, 160.65, NULL, 'Home & Living > Home Care Supplies > Cleaning Agents', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lwr32rvfvo2a3e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F800925303%2F19020312753', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
