INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23897468170', 'Reservatório Óleo Freio Gm Corsa 1994 a 2002 - 135250 - C0106', 'Reservatório Óleo Freio Gm Corsa 1994 a 2002 135250 C0106 COM TAMPA E AVISO DE NÍVEL (SISTEMA ATE) O reservatório de fluído de freio pode ser incorporado ao corpo, ou separado, feito em material plástico, translucido para observação do nível o de fluído do sistema. A tampa do reservatório possui um orifício que põe o fluído em contato com a pressão atmosférica, o que impede que se crie “vácuo” durante o funcionamento dos freios. Além disso, esta possui um interruptor elétrico que informa ao motorista, através de uma lâmpada piloto no painel, quando o nível de fluído de freio diminui.', 96.09, 96.09, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Additive and Lubricant', 'https://cf.shopee.com.br/file/sg-11134201-823r3-mojr9yas3pjib9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23897468170', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23993153091', 'Rennaiz Snacks 30 tabletes palatáveis ourofino P/Cães', '____________________________________________________________________________ A nossa loja está a mais de 10 anos no mercado, com produtos originais e com nota fiscal. ____________________________________________________________________________ Rennaiz Snacks Rennaiz Snacks é um suplemento alimentar em forma de tablete mastigável, desenvolvido para ser altamente palatável para animais. Formulado com Vitaminas do Complexo B, Ômega 3, Quitosana, Betacarotenos, Probióticos e Vitaminas C e E, este suplemento auxilia na melhoria nutricional e na qualidade de vida dos animais em todas as fases de vida, especialmente em situações que se beneficiam do aporte desses nutrientes. COMPOSIÇÃO BÁSICA DO PRODUTO VITAMINAS: - Vitamina C - Vitamina E - Betacaroteno - Vitamina B1 - Vitamina B2 - Vitamina B6 - Vitamina B9 - Vitamina B12 ÁCIDOS GRAXOS E OUTROS INGREDIENTES FUNCIONAIS: - Ômega 3 (Biomassa de Microalgas Schizochytrium sp. e Óleo de Peixe Refinado) - Quitosana PROBIÓTICOS: - Saccharomyces cerevisiae (CBS 493.94) - Enterococcus faecium (IMI 507120) - Lactobacillus acidophilus (IMI 506857) OUTROS INGREDIENTES: - Fressura de Suínos - Quirera de Arroz - Farelo de Trigo - Fosfato Bicálcico - Citrato de Potássio - Cloreto de Sódio - Propionato de Cálcio - DL-Alfa-Tocoferol - Glicerina - Ácido Cítrico - Tripolifosfato de Sódio - Sorbato de Potássio - Eritorbato de Sódio MODO DE USAR - DOSAGEM RECOMENDADA: Fornecer 1 tablete para cada 10 kg de peso corporal diretamente na boca do animal uma vez ao dia. - ADMINISTRAÇÃO: Pode ser oferecido diretamente como um petisco, garantindo que o animal consuma a dose completa. - CONSULTA VETERINÁRIA: Antes de iniciar o uso de Rennaiz Snacks, consulte um veterinário para garantir que o suplemento é adequado para o seu animal e para obter orientações específicas sobre a dosagem correta. ____________________________________________________________ ESPECIFICAÇÃO: Indicado para: Cães Idade indicada: Todas as idades Formato do suplemento: Comprimido palatável Tamanho da raça: Todas as raças Quantidade por frasco: 30 unidades _____________________________________________________________ Gostou? Não perca tempo, garanta já o seu!', 313.74, 145.9, NULL, 'Pets > Pet Healthcare > Vitamins & Supplements', 'https://cf.shopee.com.br/file/sg-11134201-7rdy3-lxwovo3onizt42', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F293152127%2F23993153091', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23493747020', 'Mangueira Do Respiro Anti Chama GOL PARATI Ap 1996/2009 - 95058 - 2137', 'Mangueira Do Respiro Anti Chama GOL PARATI Ap 1996/2009 Defletor Óleo 1.6/1.8/2.0 Bifurcada - (Ø:20mm 13/16 ")(Medida:9cmx18cm)Essa mangueira serve para aliviar a pressão de dentro do cárter pelo vazamento dos gases dos anéis. Isso é normal e chama-se ventilação positiva. Esse gás é reabsorvido junto com o vapor do óleo pelo motor para ser queimado dentro da camara de combustão, por isso ela fica ligada logo na entrada de ar do motor, ou seja, junto do filtro de ar. Isso foi desenvolvido para não poluir o ar com esses gases.', 37.42, 37.42, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rd70-m6u6nri3wiehdc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23493747020', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
