INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23294287384', 'Aerofólio Para Chevrolet Vectra 1998 1999 2000 2001 2002 2003 2004 2005 2006 2007 2008 2009 2010 A 2011 Black Piano', 'OBSERVAÇÃO: PARA MELHOR ADERÊNCIA A PEÇA DEVE SER APLICADA EM UMA SUPERFICÍE PLANA CARACTERÍSTICAS: • Ideal Para Superfície Plana • Produto Novo de Ótima Qualidade • Fabricado com Material Altamente Resistente • 100% em Acrílico • Cor Black Piano ESPECIFICAÇÕES TÉCNICAS: • Acabamento Perfeito, Com Design Esportivo • Pode ser Pintado na cor do Veículo • Fácil Instalação • Fixação Sem Furos (Fixado por meio de fita dupla face) • Dimensões: 127cm de Comprimento (Distância mais longa) X 8,8cm de Altura • Comprimento ajustável, adaptável para maioria dos carros • Borda de 135 graus pode reduzir a resistência do vento de forma mais eficaz COMPATÍVEL COM OS MODELOS: • Universal para Veículos Sedan com superfície plana de 118cm de comprimento (Faça medição antes da compra) IMPORTANTE: • Não nos responsabilizamos por instalação mal realizada; A instalação deve ser feita por um profissional especializado Atenção: As compras realizadas em nome de Pessoa Jurídica estão sujeitas à cobrança de ICMS, conforme Protocolo ICMS 41, de 4 de Abril de 2008. Caso você tenha dúvidas sobre o percentual a ser aplicado, consulte a Cláusula Segunda, §1° do referido Protocolo', 368.55, 313.27, NULL, 'Spare Parts and Accessories for Vehicles > External Accessories for Automobiles > Tuning', 'https://cf.shopee.com.br/file/br-11134207-7r98o-md0jem2ktwqpd9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F442439073%2F23294287384', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '46905429453', 'Pack 2Bonecos Surpresa Squish-a-Longs Case Laranja Brilhante', 'Descrição: "A nova linha de Squish A Long chegou, oferecendo uma experiência ainda mais fofa e diversificada para os fãs, com uma variedade incrível de produtos que garantem diversão sem fim! Prepare-se para uma surpresa adorável! A nova linha apresenta figuras exclusivas e únicas que aguardam para serem descobertas, proporcionando momentos emocionantes de expectativa e diversão. Basta abrir o pacote misterioso para revelar duas surpresas. Cada abertura é uma nova aventura, cheia de encanto e surpresas. Cada Squish A Long oferece uma diversão única e especial, garantindo que cada experiência seja única e emocionante. Abra e descubra o seu novo Squish A Long! Com uma variedade de personagens e emoções para explorar, a diversão está garantida em cada abertura." Características: Marca: Sunny Brinquedos Referência: 4290 Idade recomendada: A partir de 3 anos Pilhas Inclusas? Tipo de Pilha/Bateria Não necessita de pilhas Possui Luzes: Não Possui Sons: Não Dimensões aproximadas da embalagem: 8,1 x 6,3 x 3,8cm (A x L x C) Garantia: 3 meses a contar da emissão da Nota Fiscal Embalagem: Conteúdo da embalagem: 2 Bonecos Surpresa Certificado Inmetro: REGISTRO 004077/2021 Produtos de decoração não inclusos. Imagens meramente ilustrativas. As cores dos objetos podem sofrer alterações devido a luminosidade, configurações do monitor e até mesmo a percepção do usuário.', 59.99, 56.39, NULL, 'Hobbies & Collections > Collectible Items > Action Figurines', 'https://cf.shopee.com.br/file/sg-11134201-8261v-mjzzc1m510xxff', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F341622697%2F46905429453', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22394225453', 'Smart TV QLED 55 4K Toshiba Google TV 3HDMI 2USB Wi-Fi', 'Smart TV QLED 55 4K Toshiba Google TV 3HDMI 2USB Wi-Fi A tecnologia QLED e a resolução 4K proporcionam um brilho preciso e uniforme, cores vibrantes e detalhes nítidos que oferecem uma experiência visual de alta qualidade. Google TV Mais de 400.000 filmes e séries dos seus serviços de streaming favoritos. Crie um perfil para cada usuário na TV e mantenha as recomendações organizadas pelas preferências de cada um! Aproveite os serviços como Netflix, YouTube, Prime Vídeo e Disney+ pré-instalados. (assinaturas não incluídas) Uma combinação poderosa que proporciona um som envolvente, graças aos dois alto-falantes de 8W RMS (16W RMS no total). E a profundidade das cores exibe as imagens como realmente são. Controle parental Integração entre a TV e smartphone por meio do espelhamento de tela Controle remoto com comando de voz e botões de atalho Ela fica bem em qualquer lugar e oferece ótima visualização da tela de qualquer ângulo. Ficha Técnica Marca: Toshiba Modelo: Smart TV QLED 55 4K Toshiba Google TV 3 HDMI 2 USB Wi-Fi Cor: Preto Tamanho da Tela: 55 Polegadas Formato da Tela: 16:09 Resolução de Vídeo: 4K Tecnologia do Painel: QLED Velocidade do Painel: 60Hz Sistema Operacional: Google TV Wi-fi: Sim Smart: Sim Tensão: Bivolt Brilho: 350 cd/m² Ângulo de Visão: H: H:178° V:178° Tempo de Resposta do Painel: 8ms Contraste: 5000:1 Modo de Áudio: Dolby Áudio Aplicativos Compatíveis: Netflix, Youtube, Prime Vídeo, Disney+, Apple TV+, Loja de APP Comando de Voz: Sim Espelhamento de Tela: Sim Navegador: Sim Suporte VESA: 200 × 400 RGB/WRGB: RGB Consumo Médio: 130W Eficiência Energética: Procel Nível A Entradas: 3x HDMI 2.0; 2x USB 2.0; 1x AV; 1x entrada P2; 1x Óptica; 1x conversor digital; 1x Lan Ethernet. Dimensões com Base (LxAxC): 1233 × 757 × 273 mm Dimensões sem Base (LxAxC): 1233 × 718 × 80 mm Peso: 11 Kg Certificado Anatel: 02288-22-05520 Certificado Inmetro: 002256/2022 Garantia: 1 Ano *Imagens meramente Ilustrativas.', 3665.52, 3665.52, NULL, 'Home Appliances > TVs & Accessories > TVs', 'https://cf.shopee.com.br/file/sg-11134201-7rdvv-mc7xna7haiiff0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F898632247%2F22394225453', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23992583761', 'Flange Bomba Combustível Gm Zafira 2001 a 2004 - 516430 - T030023', 'Flange Bomba Combustível Gm Zafira 2001 a 2004 516430 T030023 Gasolina - (Bosch) Flange é um elemento de plástico ou de metal que fixa o Módulo de Combustível ao tanque de combustível do veículo. Além da fixação, a Flange faz ligação hidráulica e elétrica do interior do tanque para o exterior, permitindo o acesso ao Módulo de Combustível (composto por bomba de combustível, sensor de nível, pré-filtro, regulador de pressão, tubo corrugado e guarnição) sem operação destrutiva ou de descarte, proporcionando o reparo necessário dos componentes inclusive da própria Flange.', 53.01, 53.01, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rbmu-lnbrzzpmzf1m31', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23992583761', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20516828950', 'Papa Manchas Liquido 900ml - BELLINZONI', 'Papa Manchas Líquido Superfícies de Aplicação • Porcelanato • Mármore • Cerâmica • Granito • Pedras em Geral Finalidade Remove manchas de vinho, café, chocolate, refrigerantes, tintas para cabelos, sucos de frutas, vários tipos de corantes provenientes de tomate, mostarda, madeira entre outros. Instruções de Uso Papa Manchas Líquido pode ser usado puro* ou diluído em até 10 partes de água, dependendo da mancha a ser removida. Aplique o produto diretamente sobre a mancha e deixe agir por 30 minutos ( não ultrapasse este tempo ). Remova o produto com água limpa, enxaguando bem o material. Caso seja necessário, repita a operação. A total remoção da mancha depende da porosidade do material e do tempo em que a mesma está impregnada em sua superfície. • Atenção! Em mármores e limestone lustrados, e outros materiais com base calcária e com acabamento lustrado, não aplique o produto puro! Dilua o produto em no mínimo 5 partes de água, teste-o em uma pequena área do revestimento e verifique o resultado antes de aplicá-lo sobre a mancha. Caso seja necessário, aumente a diluição do produto para 10 partes de água. Rendimento; O rendimento do produto depende da intensidade e do tipo de manchas para limpar.', 115.88, 81.12, NULL, 'Home & Living > Home Care Supplies > Cleaning Agents', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mj44owjy92py9e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F800925303%2F20516828950', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23198845288', 'Cama Elástica Grande 2.20 Metros até 200KG Infantil Pula Pula Trampolim Azul - Castela', 'DESCRIÇÃO DO PRODUT0 Diversão garantida para a criançada! A cama elástica infantil Castela é perfeita para entreter as crianças com segurança e alegria. Ideal para quintais, áreas de lazer e festas, conta com estrutura reforçada e rede de proteção para garantir momentos de brincadeira com toda tranquilidade. - Rede de proteção alta e resistente, proporcionando máxima segurança para as crianças. - Suporte de até 200kg, permitindo que várias crianças brinquem juntas. - Capa protetora em PVC de alta qualidade, cobrindo molas e bordas para evitar acidentes. - Pés com base firme que garantem maior estabilidade durante o uso. CARACTERÍSTICAS TÉCNICAS: Conteúdo da Embalagem: 1 Cama Elástica Infantil Castela Dimensões Aproximadas do Produto: 2.2m x 1.83m (Altura x Largura) Dimensões Aproximadas da Embalagem: 24 cm x 46 cm x 102 cm (Altura x Largura x Comprimento/Profundidade). Material/Composição: Estrutura de Aço Idade Mínima Recomendada: A partir de 3 Anos Participantes: A partir de 1 ou mais pessoas Alimentação: Não se aplica Marca: Castela Referência: CBS1251 Outras informações: As cores podem variar entre as imagens mostradas acima e o produto. Imagens meramente ilustrativas. Aviso: As informações e imagens divulgadas são de total responsabilidade do fabricante/fornecedor. Produto lacrado e disponível a pronta entrega para todo Brasil! APROVADO PELO INMETRO', 1040.99, 699.99, NULL, 'Hobbies & Collections > Toys & Games > Others', 'https://cf.shopee.com.br/file/br-11134207-820lm-mqhpunt6ypkx2c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F446413605%2F23198845288', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22899124233', 'CAIXA PASSIVA SUBWOOFER SLIM SPYDER 8 POLEGADAS 200 W RMS', 'INFORMAÇÕES TÉCNICAS: MODELO – STREET 8 POL 400W; DIÃMETRO – 8 POLEGADAS; BOBINA SIMPLES DE 4 OHMS; POTÊNCIA MUSICAL – 400 WATTS PMPO; POTÊNCIA RMS – 200 WATTS; RESPOSTA DE FREQUENCIA 35HZ A 650HZ; DIMENSÕES: Altura: 10 cm; Largura: 30 cm; Comprimento: 39 cm; COMPOSIÇÃO: 1 - Subwoofer Spyder Slim 8 polegadas 200 Watts RMS 4 OHMs; 1 - Conector duas vias; 1 - Duto de 2 polegadas; INFORMAÇÕES ADICIONAIS: Confeccionada em MDF de 12mm de espessura, com revestimento em carpete preto, podendo variar a tonalidade de acordo com os padrões de tolerância do fabricante do mesmo. No momento da instalação como qualquer outra caixa acústica lembre-se de considerar o deslocamento do cone dos alto falantes, para este produto até 10mm. *Não se responsabilizamos por instalação mal realizada; *Não se responsabilizamos por mau uso do produto (Ex: Queima do Alto falante / Driver / Tweeter); *A garantia do fabricante não cobre bobina queimada; *Para acionar a garantia será necessário encaminhar o produto com a nota fiscal para uma autorizada da marca; *Só aceite receber a mercadoria após verificar se a mesma coincide com a que consta no pedido e se está em perfeito estado;', 269.99, 269.99, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Audio System', 'https://cf.shopee.com.br/file/sg-11134201-825az-mg6qn9r7fh8u71', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F406280808%2F22899124233', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
