INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22891924114', 'Chocolate Diamante Negro Laka 80gr Lacta', 'A perfeita combinação de chocolate ao leite com cristais crocantes. Um sabor único e misterioso. Ingredientes: Açúcar, massa de cacau, manteiga de cacau, soro de leite em pó, leite em pó integral, gordura vegetal, glicose, mel, gordura de manteiga desidratada, açúcar invertido, castanha-de-caju, emulsificantes: lecitina de soja e poliglicerol polirricinoleato e aromatizante. ALÉRGICO: CONTÉM CASTANHA-DE-CAJU E DERIVADOS DE LEITE E SOJA. PODE CONTER AMÊNDOA, CEVADA, AVELÃ, AMENDOIM, TRIGO E LÁTEX NATURAL. CONTÉM LACTOSE. CONTÉM GLÚTEN. Informações Nutricionais: Porção de 25g (4 quadradinhos) Valor Energético 127Kcal (6%) Carboidratos, dos quais: 17g (6%) Açúcares 16g (**) Proteínas 1g (1%) Gorduras totais 6,2g (11%) Gorduras saturadas 3,7g (17%) Sódio 22mg (1%) Informações de responsabilidade do fabricante.', 12.69, 11.99, NULL, 'Food & Beverages > Snacks > Chocolate', 'https://cf.shopee.com.br/file/br-11134207-7qukw-ljr0w3hp1ova93', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1008814366%2F22891924114', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
