INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '52711183900', 'Sulfamicina Oral Ibasa Aves Bovinos Suínos 1L', 'A Sulfamicina Oral Ibasa é uma solução veterinária desenvolvida para auxiliar no manejo sanitário de aves, bovinos e suínos. Sua formulação combina princípios ativos com ação antibacteriana, contribuindo para protocolos de suporte veterinário conforme orientação profissional. Indicada para uso em animais de produção, pode auxiliar nos cuidados relacionados à manutenção da saúde e bem-estar dos animais em diferentes sistemas de criação. Sua apresentação líquida facilita a administração e o preparo conforme necessidade de uso. Produto destinado ao uso veterinário, indicado para utilização conforme recomendação técnica adequada para cada espécie animal. FICHA TÉCNICA • Indicação: Manejo sanitário veterinário • Finalidade: Auxiliar no controle bacteriano • Tipo de produto: Solução oral veterinária • Composição: Sulfametazina e trimetoprim • Forma de apresentação: Solução líquida • Quantidade: 1 litro • Público alvo: Aves, bovinos e suínos CUIDADOS COM O PRODUTO Utilizar conforme orientação veterinária Armazenar em local seco e protegido da luz Manter a embalagem bem fechada Não utilizar sem recomendação profissional Manter fora do alcance de crianças', 169.9, 119.9, NULL, 'Pets > Pet Grooming > Others', 'https://cf.shopee.com.br/file/br-11134207-820m3-mozfkwdvmqrpdb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F293152127%2F52711183900', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
