INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '57450762181', 'Credeli Plus 112,5 mg Cães 2,5 a 5,5 kg 1 Comprimido', 'O Credeli Plus 112,5 mg é um comprimido mastigável indicado para cães com peso entre 2,5 kg e 5,5 kg, oferecendo uma proteção ampla e segura contra pulgas, carrapatos e vermes intestinais. Formulado para facilitar a administração, o comprimido pode ser dado junto com a refeição ou logo após, promovendo aceitação e praticidade no cuidado mensal. Ideal para tutores e clínicas que buscam conforto, eficiência e tranquilidade no manejo da saúde do pet. FICHA TÉCNICA Indicação: cães com peso entre 2,5 kg e 5,5 kg Apresentação: 1 comprimido mastigável Fórmula: associação de princípios ativos antiparasitários de ação mensal Administração: via oral durante ou após a alimentação Frequência de uso: dose mensal conforme recomendação veterinária Ação principal: controle e prevenção de pulgas, carrapatos e vermes Sabor: palatável e aceito pela maioria dos cães CUIDADOS COM O PRODUTO Utilize somente em cães dentro da faixa de peso indicada Mantenha o produto em sua embalagem original até o momento do uso Armazene em local seco, protegido da luz e em temperatura ambiente Não administrar em filhotes com menos de 8 semanas de idade ou fora da faixa de peso indicada sem avaliação veterinária Consulte o médico veterinário em caso de dúvidas ou condições clínicas especiais', 84.9, 67.9, NULL, 'Pets > Pet Healthcare > Medication', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mgmn2xufksg0cc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F293152127%2F57450762181', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
