INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23494387211', 'Creme Bepantol Tattoo 30g', 'A pomada Bepantol Derma Tatto foi formulada especialmente para proporcionar hidratação intensa e restauração à sua pele após o procedimento. Enriquecida com Dexpantenol, lanolina e óleo de amêndoas doces, ela ajuda a proteger e regenerar a pele, preservando as cores vibrantes da sua tatuagem. Ideal para o pós-tatuagem, é a escolha perfeita para quem busca um cuidado eficaz e seguro. Sua fórmula proporciona uma hidratação profunda, garantindo que sua tatuagem se recupere rapidamente e sem ressecamento. Para usar, aplique uma fina camada do Creme Restaurador Bepantol Tattoo sobre a área tatuada. Massageie suavemente até a completa absorção, reaplicando conforme necessário para manter a hidratação da pele tatuada.', 49.24, 49.24, NULL, 'Beauty > Bath & Body Care > Others', 'https://cf.shopee.com.br/file/sg-11134201-824g1-meef965kzzt06f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1050887704%2F23494387211', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
