INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21199561466', 'Kit 2 Máscara Capilar Siàge Hidratação Micelar 250g', 'Máscara Capilar Siàge Hidratação Micelar 250g A Máscara Capilar Siàge Hidratação Micelar traz um exclusivo sistema micelar inteligente que identifica o grau de ressecamento dos seus cabelos e recupera os danos dos fios, agindo diretamente nas agressões. Assim, você tem 3 vezes mais maciez e deixa as suas madeixas soltas e com um brilho bonito e saudável. A máscara oferece hidratação profunda aos cabelos, proporcionando 48 horas de fios soltos, hidratados e suaves, além de 67% mais macios. A linha ainda traz a exclusiva biotecnologia Affinité 4D, que atua até nas camadas mais profundas da fibra capilar, devolvendo a saúde dos fios. Dermatologicamente testado. Para ter os cabelos que sempre sonhou, conheça toda a linha Siàge! Nenhum produto Eudora é testado em animais, ou seja, este item possui selo Cruelty Free. Como Usar: Conselho de Aplicação: Após o uso do Shampoo Siàge Hidratação Micelar, aplique, mecha por mecha, o produto por todo o comprimento e ponta dos fios. Deixe agir por 5 minutos e enxágue bem. Use-a de 1 a 2 vezes por semana, ou sempre que necessário.', 119.98, 119.98, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-823oi-moobzohunwu8b1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F21199561466', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
