INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23697029681', 'SAXOFONE SOPRANO RETO HARMONICS HST410L LAQUEADO EM SIB', 'SAXOFONE SOPRANO RETO HARMONICS HST410L LAQUEADO EM SIB A Harmonics é uma marca de instrumentos musicais e som profissional que segmenta: Cordas, Sopro e Microfones. A marca atua no mercado brasileiro e se destaca pela qualidade e precisão com custo acessível. Os instrumentos Harmonics são companheiros para várias ocasiões, seja no seu primeiro contato como músico, no churrasco com a família, em momentos de descontração com os colegas e amigos ou até soltando a voz no barzinho. Em todos os lugares e propostas a Harmonics é sua companheira de melodias! O saxofone soprano reto da Harmonics tem como marca a qualidade de sua construção e materiais de acompanhamento. Com sua qualidade já reconhecida este saxofone aparece num modelo com acabamento e chaves na cor dourada. O Timbre dos saxofones possui um som encorpado e harmônico com muito grave. A afinação em Bb - Chave de Bb grave articulável - Chave de F# agudo - Molas em aço e parafusos em inox Características Afinação: Bb (Sí Bemol) Extensão: Bb (Si bemol) / G (Sol) Chave Bb Articulada Tudel: Reto e Curvo Apoio de polegar: Regulável Corpo: Latão amarelo Acabamento: Laqueado Sapatilhas: Importada Estojo: Luxo (Soft Case) Garantia: 6 meses Outros Informação adicional: Tudel: Reto e Curvo', 3352.82, 3017.54, NULL, 'Hobbies & Collections > Musical Instruments & Accessories > Wind Instruments', 'https://cf.shopee.com.br/file/sg-11134201-7rbme-lmt3szeggk5hf9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1006271683%2F23697029681', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22898044909', 'Caneleira Penalty Unissex Matis X 610143', 'Jogue sem medo e se proteja de lesões com a Caneleira Penalty Matis X. Seu design foi pensado para futebol dos tipos society, campo e futsal. O modelo conta com revestimento de polipropileno na área externa, para maior resistência e durabilidade. Além disso, ela é texturizada, para que se fixe melhor ao meião. A parte interna é feita com tecnologia Shield Sys, que consiste em EVA nos revestimentos, permitindo maior conforto, proteção e leveza, tudo em um formato anatômico. É perfeita para você jogar como craque, sem fugir dos confrontos na partida!', 49.89, 29.88, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Soccer, Futsal & Sepak Takraw', 'https://cf.shopee.com.br/file/sg-11134201-7ra1c-m4qeyqm89jk187', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F920605202%2F22898044909', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
