INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23693472381', 'Chave Canhão 13mm (44251/013) - Tramontina Pro', 'A Chave Canhão 13mm (44251/013) - Tramontina Pro, é comumente utilizada em manutenções industriais ou automotivas, apertar ou afrouxar parafusos se torna mais fácil com a ajuda da Chave Canhão da Tramontina PRO. Esta chave de fenda proporciona maior conforto e firmeza na utilização, devido as suas as saliências no cabo. Ideal para trabalhos em locais de difícil acesso. Descrição do Produto: • Haste em aço carbono. • Soquete usinado em aço cromo vanádio. • Acabamento cromado. • Ponta fosfatizada. • Cabo injetado. • DIN 3125. • As ferramentas são produzidas e testadas conforme normas específicas. Referência: 44251/013. Marca: Tramontina Pro.', 27.5, 27.5, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rdyo-m1em9gqe7fvcce', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F674110767%2F23693472381', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22433797181', 'Broca Bosch EXPERT HEX-9 MultiConstruction Ø10x90x150mm', 'A broca EXPERT HEX-9 MultiConstruction possui haste hexagonal de 1/4 de polegada e pode ser utilizada com chaves de impacto, parafusadeiras e furadeiras (com ou sem impacto), com ou sem cabo que possuam encaixe ou mandril compatível com 1/4 de polegada. É até 5 vezes mais precisa do que uma broca CYL-3. A broca EXPERT HEX-9 MultiConstruction oferece perfuração estável em quase todos os tipos de materiais, por isso é denominada como uma broca multimaterial. A combinação de carbeto de tungstênio Bosch com arestas de corte afiadas com diamante, tornam a broca resistente ao desgaste. Além disso, sua ponta centradora permite uma perfuração estável do início ao fim. A broca pode ser utilizada na instalação de interiores e em materiais como concreto macio, alvenaria, tijolo, fibrocimento, materiais de construção leves, materiais multicamada, cerâmicas e ladrilhos, madeira, plástico, chapas de metal finas e alumínio. Garantia 6 meses Bosch. - Até 5 vezes mais precisa que uma broca CYL-3 da Bosch - Perfuração precisa e facilitada com a Centering Geometry patenteada Bosch. - Indicada para utilização em diferentes tipos de materiais - Arestas de corte afiadas com diamante tornam a broca resistente ao desgaste - Pode ser utilizada com chaves de impacto, parafusadeiras e furadeiras com e sem impacto Especificações técnicas: - Diâmetro do item (mm): 10 - Comprimento útil (mm): 90 - Comprimento total (mm): 150 - Encaixe: Hexagonal - Diâmetro do encaixe (polegada): 1/4'''' - Tipo de ponta: Carbeto de Tungstênio, 2 arestas de corte - Até 5 vezes mais precisa que uma broca CYL-3 da Bosch - Perfuração precisa e facilitada com a Centering Geometry patenteada Bosch. - Indicada para utilização em diferentes tipos de materiais - Arestas de corte afiadas com diamante tornam a broca resistente ao desgaste - Pode ser utilizada com chaves de impacto, parafusadeiras e furadeiras com e sem impacto', 53.9, 53.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-23030-04esc2zepyov2a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F674110767%2F22433797181', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
