es.', 43.99, 43.99, NULL, 'Home & Living > Dinnerware > Water Bottles & Accessories', 'https://cf.shopee.com.br/file/br-11134201-820m3-mqxdiakn52pw28', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F402450553%2F19797981996', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
