INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '57300761197', 'Carrinho de Passeio Infantil Jip Jip Maral com Guidão Direcional', '***PRODUTO A PRONTA ENTREGA COM ENVIO IMEDIATO*** Carrinho Jip Jip Militar Maral 2 em 1 Com Haste Guia Removível Este carrinho de passeio Jip Jip é um brinquedo 2 em 1 que se adapta ao crescimento da criança, podendo ser guiado pelo adulto ou usado livremente pelo bebê. Com um divertido design militar, possui anel de proteção que levanta, apoio de pés, buzina com som e câmbio que faz creck creck. É seguro, certificado pelo Inmetro e recomendado para crianças a partir de 9 meses. Destaques do produto: Brinquedo 2 em 1 que acompanha o crescimento da criança (com ou sem acessórios) Haste guia com toque seguro, direcionável e fácil de remover Anel de proteção que se levanta para facilitar o acesso à criança Possui buzina divertida, chave que gira e câmbio com som Informações técnicas: Marca: Maral Modelo/Código: Jip Jip Militar 2059 Tipo: Carrinho de passeio / Andador Materiais: Plástico Faixa/Especificações relevantes: Idade recomendada +09 meses Suporta até 30 kg; Gancho da haste suporta até 1,5 kg Acabamento/Proteções: Selo de Segurança do Inmetro 007281/2021 Aplicações: Passeio, diversão e desenvolvimento infantil Conteúdo da embalagem: 1 unidade(s); Jip Jip Militar; Anel de proteção; Haste para empurrar Garantia legal de 90 dias Adquira o Jip Jip Militar, um carrinho temático, seguro e que oferece diversão e autonomia para seu filho!', 359.99, 248.9, NULL, 'Mom & Baby > Toys > Toy Vehicles', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mh7yiziiixhc68', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F445163047%2F57300761197', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22492978903', 'Conjunto Com 2 Cadeiras Estofada Sala de Jantar Trieste Siena Cedro / Areia Dobuê', 'O Conjunto de 2 Cadeiras estofadas Trieste Siena é uma excelente opção para complementar seu ambiente com estilo e qualidade. Seja sua sala de jantar, cozinha, ou área gourmet. Revestidas em tecido Veloplus de fácil limpeza, o conjunto possui estrutura reforçada em MDF excelente para receber os amigos e familiares, tornando o momento ainda mais especial! MEDIDAS: [ A ] = 93 cm [ L ] = 42 cm [ P ] = 61 cm PESO CADEIRA: 7,40Kg PESO SUPORTADO CADEIRA: 110 Kg MODELO: Conjunto Com 2 Cadeiras Estofada Sala de Jantar Trieste Siena Dobuê MARCA: Dobuê COR DA CADEIRA: Estrutura: Cedro / Assento: Areia ESTRUTURA: MDF 25 mm ACABAMENTO: Pintura UV TECIDO DA CADEIRA: Veloplus REVESTIMENTO INTERIOR CADEIRA: Espuma D20 assento e D13 Encosto SAPATAS: Plástica ITENS INCLUSOS: 2 Cadeiras GARANTIA: 3 meses pelo fabricante A Esplanada Móveis se responsabiliza pela entrega dos produtos adquiridos até a porta de entrada ou portaria do endereço indicado, se a portaria do condomínio permitir, as entregas são efetuadas no piso térreo e é de responsabilidade do cliente a locomoção da mercadoria até seu apartamento ou casa. Confira as dimensões do produto e certifique-se de que estão adequadas aos elevadores, portas e corredores do local da entrega. Não fazemos a montagem, desmontagem do produto e/ou portas e janelas, transporte pela escada ou içamento pelo lado de fora do prédio. Não está incluso no serviço de entrega o deslocamento até o interior do apartamento, com ou sem elevador, ou deslocamento em locais de difícil acesso como escadarias. Caso o cliente necessite de entrega dentro das dificuldades mencionadas, deverá entrar em contato para análise e cotação do valor do serviço. Certifique-se de tudo antes de finalizar a compra, evitando assim futuros desagrados ou imprevistos com a entrega.', 329.0, 299.0, NULL, 'Home & Living > Furniture > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rd49-luib5n469tg3cf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1097902002%2F22492978903', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
