INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19261906197', 'Tensor Correia Dentada Chevrolet S10 95 a 2007 Skf', 'NÃO VENDEMOS PARA PESSOA JURÍDICA CONSUMIDOR. PRODUTO NOVO. Aplicação CHEVROLET S10 BLAZER DLX 2.2 MPFI / EFI 1995 até 1999 S10 BLAZER STD. 2.2 MPFI / EFI 2000 S10 BLAZER TORNADO 2.4 MPFI 8V 128CV 2005 até 2007 Conteúdo Da Embalagem 1 Tensor da Correia Dentada Cor do Produto No Tipo de Veículo para Carros Marca A SKF é um fornecedor líder global de tecnologia a quase 100 anos, uma marca experiente e pratica em mais de 40 setores com o conhecimento em plataformas de tecnologia: rolamentos e unidades, vedações, mecatrônica, serviços e sistemas de lubrificação. O Produto Sempre que fizer uma revisão, o tensionador da correia dentada tem que ser olhado, pois mesmo que ele esteja com problemas não é possível ouvir o barulho que faz, porque ele está dentro de uma capa protetora que inibe o barulho da peça, e se ele travar pode arrebentar a correia dentada, e ainda prejudicar outras peças do motor. Importante Recomendamos que os produtos sejam instalados por profissionais especializados e não se responsabiliza pelo mal uso ou instalação indevida, causando a perda da garantia. Verifique com os fabricantes do produto e de seus componentes eventuais limitações à utilização de todos os recursos e funcionalidades. Todas as informações divulgadas são de responsabilidade do fabricante/fornecedor. Tempo de garantia: 6 Meses Prazo de troca e devolução: 7 dias a partir do recebimento do produto - Lei nº 8.078 Imagem meramente ilustrativa Valor Unitário EAN 7316572422687 Código do Fabricante VKM15402', 116.06, 116.06, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-821f6-mgm71h0ca2oddb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F817551928%2F19261906197', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23093931797', 'Jaqueta Ziper Moletom Clássica', 'Jaqueta Ziper Moletom Clássica: Estilo e Conforto para Todos os Momentos! Descubra a Jaqueta Ziper Moletom Clássica, um modelo que nunca sai de moda e é perfeito para qualquer ocasião. Exterior confeccionada em 95% poliéster e 5% elastano, e Capuz forrado em 100% Poliéster. Esa jaqueta oferece um conforto extremo e uma leveza incomparável, ideal para o seu dia a dia. Características Principais: Design Atemporal: Um clássico que se adapta a diferentes estilos e tendências. Conforto Garantido: O tecido macio proporciona uma sensação agradável na pele, perfeita para todas as estações. Versatilidade: Combine com suas roupas favoritas, seja para um passeio casual ou um evento mais despojado. A Jaqueta Ziper Moletom Clássica é a escolha certa para quem busca praticidade e estilo. Não perca a chance de ter essa peça essencial no seu guarda-roupa! Experimente e sinta a diferença!', 239.9, 215.91, NULL, 'Men Clothes > Jackets, Coats & Vests > Jackets', 'https://cf.shopee.com.br/file/sg-11134201-7reqd-m8x1y8zeru09d9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1054730940%2F23093931797', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '52201184151', 'Hello Kitty - Boneca Interativa de12cm Com Luz e Som', 'Hello Kitty ganha vida com esta figura interativa de 5 polegadas, vestindo um adorável macacão rosa. Com mais de 50 reações, ela responde ao toque e à voz, dança ao som de músicas externas e também toca suas próprias canções. A tiara com laço iluminado adiciona um toque mágico à experiência. Ao conversar com Hello Kitty, diferentes emoções e respostas surgem, criando momentos divertidos e afetuosos. Um verdadeiro destaque para quem ama tecnologia, carinho e personagens que expressam sentimentos de forma única. Registro 008664/2025', 399.99, 375.99, NULL, 'Mom & Baby > Toys > Dolls & Stuffed Toys', 'https://cf.shopee.com.br/file/sg-11134201-821gb-mgxwazlcwsgfa8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F341622697%2F52201184151', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
