INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23593843203', 'Bloco de Atividades + Adesivos Tema: Veículos-Melissa & Doug', 'Descrição: "Bloco de atividades com adesivos no tema veículos!Inclui 5 fundos coloridos e 165 adesivos reutilizáveis para reposicionar quantas vezes quiserCenas de fundo removíveis incluem estacionamento, autoestrada, estaleiro de construção, caminho de ferro e aeroportoPromove habilidades motoras finas e brincadeiras criativas. " Características: Marca: Sunny Brinquedos Referência: 4604 Idade recomendada: A partir de 4 anos Pilhas Inclusas? Tipo de Pilha/Bateria Não necessita de pilhas Possui Luzes: Não Possui Sons: Não Dimensões aproximadas da embalagem: 28 x 35,6 x 0,5cm (A x L x C) Garantia: 3 meses a contar da emissão da Nota Fiscal Embalagem: Conteúdo da embalagem: 1 Bloco de Atividades com 165 Adesivos Reutilizáveis Certificado Inmetro: REGISTRO 015501/2024 Produtos de decoração não inclusos. Imagens meramente ilustrativas. As cores dos objetos podem sofrer alterações devido a luminosidade, configurações do monitor e até mesmo a percepção do usuário.', 79.99, 75.19, NULL, 'Books & Magazines > Books > Sticker & Colouring Books', 'https://cf.shopee.com.br/file/sg-11134201-7rd5p-m7jtff7ps9gwbc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F341622697%2F23593843203', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209691775', 'Lacta Intense 70% Cacau Chocolate', 'O novo chocolate Lacta Intense 70% original possui alto teor de cacau sem perder a cremosidade do chocolate Lacta que você já conhece. É uma experiência única no segmento de chocolates amargos. Possui o sabor intenso do cacau combinando com uma maciez irresistível, derretendo lentamente na boca e fazendo cada momento delicioso durar ainda mais. Além de toda a deliciosidade, este chocolate é feito de cacau sustentável, ajudando o meio ambiente. Impossível não se apaixonar! Aproveite e conheça toda a linha de produtos Lacta Intense.', 19.49, 17.53, NULL, 'Food & Beverages > Snacks > Chocolate', 'https://cf.shopee.com.br/file/sg-11134201-8259a-mqnelcm1mwpabc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554990%2F58209691775', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '11385378203', 'ESPUMANTE SALTON SERIES BRUT ROSE', 'Elaborado com as uvas Trebbiano, Moscato e Merlot, tem extração do mosto em prensas pneumáticas. As fermentações ocorrem em temperaturas controladas. Em vista é brilhante, de sutil coloração rosa cerveja, com abundante desprendimento de borbulhas. Com aromas especialmente de frutas vermelhas frescas, como morango e cereja, além de frutos cítricos. Seu paladar é cremoso, de acidez refrescante e prolongada persistência.', 35.88, 28.6, NULL, 'Food & Beverages > Alcoholic Beverages > Wine & Champagne', 'https://cf.shopee.com.br/file/br-11134207-7qukw-ljflcll3fy4q97', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F661273874%2F11385378203', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20398269167', 'Tênis Infantil Novopé super Flex Marinho com Pink', 'A linha Super Flex da Novopé foi desenvolvida para oferecer uma experiência de conforto e mobilidade incomparáveis. Com uma estrutura altamente flexível, esses calçados permitem que os pés das crianças se movam livremente, proporcionando uma sensação de leveza e liberdade em cada passo. Além disso, a biqueira fusionada garante uma resistência superior, protegendo os pés contra impactos e abrasões, enquanto a sola antiderrapante proporciona segurança extra em diversas superfícies. Os calçados da linha Super Flex também se destacam pelo design moderno e atraente, com opções de cores vibrantes e estampas divertidas que encantam os pequenos. Perfeitos para acompanhar a energia e as aventuras das crianças, esses calçados são a escolha ideal para o dia a dia, combinando estilo, segurança e máximo conforto.', 129.9, 129.9, NULL, 'Baby & Kids Fashion > Girl Shoes > Sneakers', 'https://cf.shopee.com.br/file/sg-11134201-82605-mm7szrb1kydc29', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F375042077%2F20398269167', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
