INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209247785', 'Forno Elétrico de Embutir EOS 47L Porta de Vidro e Inox EFE47EI 220V', '🔥 Forno Elétrico de Embutir EOS 47L Grill Vidro Duplo EFE47 ✨ Um forno pensado para quem quer praticidade no dia a dia sem abrir mão de desempenho. Com 47 litros de capacidade e funções essenciais de preparo, ele entrega controle, segurança e eficiência em cada receita, tudo com acabamento moderno e fácil de integrar à sua cozinha. ✨ Destaques do Produto: ✅ Capacidade interna de 47L: ideal para receitas do cotidiano ✅ Função Grill: doura e gratina pratos com praticidade ✅ Função dourar: mais rapidez no acabamento das receitas ✅ Controle de aquecimento: resistência superior, inferior ou ambas ✅ Seletor de temperatura até 230°C: mais precisão no preparo ✅ Timer de até 120 minutos: com aviso de término ✅ Vidro duplo na porta: mais segurança e isolamento térmico ✅ Luz interna: acompanhe o preparo sem abrir a porta ✅ Baixo consumo de energia: mais eficiência no uso diário ✅ Interior antiaderente: facilita a limpeza ✅ Grades internas em inox: mais durabilidade e resistência à ferrugem ✅ Bandeja em cerâmica: mais praticidade na limpeza 📏 Dimensões internas (LxAxP/cm): 45 x 26 x 36 cm 📐 Dimensões para embutir (AxLxP/cm): 57,1 x 48,2 x 57 cm 💎 Mais controle, mais praticidade e mais eficiência para sua cozinha.', 1087.9, 1087.9, NULL, 'Home Appliances > Kitchen Appliances > Ovens', 'https://cf.shopee.com.br/file/sg-11134201-820ma-mnagcpefmiv6d9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1527564302%2F58209247785', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
