INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22694760771', 'Parafuso Inox Fixação Agitador Lavadora Brastemp Consul', 'Parafuso Inox Fixação Agitador Lavadora Brastemp Consul O Parafuso Inox Fixação Agitador Lavadora Brastemp Consul Tem como função fixar o agitador ao mecanismo de sua lavadora. Ele fica rosqueado na parte central de seu agitador. Deve ser parafusado até o final para proporcionar uma melhor fixação da peça.', 7.44, 7.44, NULL, 'Home Appliances > Others', 'https://cf.shopee.com.br/file/sg-11134201-8259r-mqyvjyg9ecjpe4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1323031590%2F22694760771', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23997460716', 'Kit Duplinha de Gelatinas Melancia e Uva #todecacho Kids', 'O Kit duplinha de Gelatinas Melancia e Uva #todecacho Kids: 1 Gelatina Ativadora Melancia #todecacho e 1 Gelatina Modeladora Uva #todecacho Kids. Proporciona definição com movimento, hidratação e ação antifrizz aos cachinhos. <>INDICAÇÕES$& Para quais tipos de cabelo? Cacheados, Crespos e Ondulados. Qual a indicação? Desidratado, com frizz, sem definição, ressecado e sem brilho. Pode usar a partir de quantos anos? A partir de 03 anos. <>ATIVOS$& Quais os principais ativos? #todecacho gelatina ativadora condicionador kids melancia Conta com óleo de Semente de Melancia, Mix de Vitaminas e Glicerina Vegetal que, juntos, proporcionam movimento, hidratação e ação antifrizz. #todecacho gelatina modeladora condicionador kids uva Com com óleo de Semente de Uva e Pantenol que, juntos, proporcionam desembaraço, brilho intenso, fixação flexível e ação antifrizz. <>MODO DE USO$& Qual a melhor forma de usar? Gelatina Ativadora Melancia Gelatina Modeladora Uva Aplique a Gelatina uniformemente nos cabelos limpos e úmidos, no comprimento e pontas. Desembarace os fios com um pente de dentes largos e, em seguida, amasse os cachinhos e ondinhas iniciando o movimento das pontas até a raiz. O procedimento pode ser repetido quantas vezes forem necessárias. <>CARACTERÍSTICAS$& É produto vegano? O kit é vegano. É liberado? O Kit é liberado.', 57.0, 51.56, NULL, 'Mom & Baby > Bath & Body Care > Hair Care & Body Wash', 'https://cf.shopee.com.br/file/br-11134201-7r98o-luz2hmfm1cff4b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F616222685%2F23997460716', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20698458990', 'Kit Desembaraço e Super Controle Salon Line', 'O kit conta com Creme para Pentear Salon Line Super Desembaraço promove ultradesembaraço, brilho maciez e muita definição. Creme para Pentear Super Controle Salon Line 1L promove controle de frizz, redução de volume, brilho, maciez e muita definição. <>INDICAÇÕES$& Para quais tipos de cabelo? Cabelos cacheados, crespos e cabelos em transição. Qual a indicação? Cabelos finos e com dificuldade de desembaraço. Pode usar a partir de quantos anos? A partir de 12 anos. <>ATIVOS$& Quais os principais ativos? Creme Super Desembaraço Óleo de argan, babosa e D-Pantenol: ajudam a proporcionar cabelos nutridos, hidratados e de fácil desembaraço. Creme Super Controle Óleo de abacate, óleo de macadâmia e colágeno vegetal: ajudam a proporcionar brilho intenso e maciez aos cabelos. <>MODO DE USO$& Qual a melhor forma de usar? Creme Super Desembaraço Com os cabelos limpos e úmidos, aplique o Creme Desembaraçante mecha a mecha no comprimento e pontas. Desembarace os fios com um pente de dentes largos e, em seguida, amasse-os iniciando o movimento das pontas até a raiz. Repita o movimento quantas vezes forem necessárias. A aplicação de creme para desembaraçar cabelo dependerá da quantidade e do comprimento dos fios. Não enxágue. Creme Super Controle Com os cabelos limpos e úmidos, aplique o Creme de pentear Salon Line Super Controle mecha a mecha no comprimento e pontas. Desembarace os fios com um pente de dentes largos e, em seguida, amasse-os iniciando o movimento das pontas até a raiz. Repita o movimento quantas vezes forem necessárias. A aplicação dependerá da quantidade e do comprimento dos fios. Não enxágue. <>CARACTERÍSTICAS$& É produto vegano? Todos os produtos do kit são veganos. É liberado? Todos os produtos do kit não são liberados.', 79.0, 67.15, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-8258a-mfuq7vxbh98s16', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F616222685%2F20698458990', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '54810371996', 'Pato Bloqueador de Odores Algodão 60ML', 'Bloqueador de Odores Sanitários Pato Block Algodão – 60ml Chega de passar sufoco ou constrangimento no banheiro! O Pato Block N°2 de Boa é o seu aliado perfeito para garantir total discrição e frescor em qualquer momento do dia. Com uma fórmula inovadora e uma fragrância suave de Algodão, ele cria uma barreira protetora na água do vaso sanitário que bloqueia o mau odor antes mesmo que ele se espalhe pelo ambiente. Seja em casa, no trabalho ou na casa de amigos, com o Pato Block você faz o seu "número 2" com total tranquilidade e deixa o banheiro com um aroma limpo e agradável. Por que escolher o Pato Block? Bloqueio Eficaz: Cria uma película na água que aprisiona os odores desagradáveis dentro do vaso. Fragrância de Algodão: Deixa um perfume suave, leve e fresco, sem aquele cheiro forte e artificial de sprays comuns. Tamanho Prático (60ml): Compacto e discreto, cabe perfeitamente na bolsa, na mochila ou no nécessaire. Ideal para levar para o trabalho, viagens ou eventos. Fácil de Usar: Borrifou, usou, sumiu! Sem complicações. Como Usar (Passo a Passo): Antes de utilizar o vaso, agite o frasco. Borrife de 3 a 5 vezes diretamente na água do vaso sanitário. Use o banheiro sem preocupações. Os óleos naturais criarão a barreira protetora. Pronto! O único cheiro que vai ficar no ar é o perfume suave de algodão.', 29.59, 29.59, NULL, 'Pets > Litter & Toilet > Diapers', 'https://cf.shopee.com.br/file/sg-11134201-823qd-moies5fdqlfx12', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F683952730%2F54810371996', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20799560466', 'Pijama Infantil Menina Urso-Polar Em Fleece Malwee Kids', 'O Pijama Infantil menina Urso-Polar Em Fleece Malwee Kids é perfeito para as noites quentinhas e cheias de fofura. Confeccionado em fleece, um tecido macio e quentinho, ele proporciona conforto e proteção durante toda a noite. Com uma estampa encantadora de urso-polar, esse pijama traz diversão e encanto para as horas de sono. A blusa de mangas longas e a calça com cós elástico garantem um ajuste perfeito ao corpo. • Pijama Infantil em Fleece • Camiseta: • Gola Redonda • Mangas Longas • Bordado Frontal • Calça: • Cós e Barra em Elástico', 189.9, 75.9, NULL, 'Baby & Kids Fashion > Girl Clothes > Sleepwear', 'https://cf.shopee.com.br/file/sg-11134201-7rfhx-m313ywc7lnzbd7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1264817414%2F20799560466', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23394398860', 'XAROPE MONIN MIRTILLO 700ML', 'Xarope Monin Mirtilo 700ml. O mirtilo é nativo da América do Norte. Durante séculos, os nativos americanos reuniram os frutos para consumo ou preservação. Apresentando uma cor aveludada de um azul profundo, mirtilos têm um sabor agradavelmente doce com uma acidez suave quando maduro. MONIN Blueberry Syrup preserva perfeitamente o delicioso sabor de amoras maduras. Feito com ingredientes selecionados e cana de açúcar puro, MONIN Blueberry Syrup é um altamente concentrado, aromatizante, autêntica e com uma versatilidade excepcional para a criação de bebidas especiais.', 76.99, 76.99, NULL, 'Food & Beverages > Beverages > Cordial & Syrups', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mek6bn7r4q2qca', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1605305232%2F23394398860', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23998877926', 'VODKA SKYY GARRAFA DE 750ML', 'Criada em São Francisco (EUA) no início dos anos 90 com o objetivo de ser a Vodka mais pura do mundo, chegou ao Brasil em 2000 como uma Vodka importada. Hoje, SKYY VODKA celebra a mistura de pessoas, interesses, talentos, cenários que estimulam a criatividade e o progresso na nossa sociedade. Destilada 4x e filtrada 3, a SKYY é uma vodka premium, extremamente suave e versátil, resultado da produção inovadora que contempla todos os processos. Combina com a sua imaginação e com o que você quiser. Graduação Alcoólica: 40%', 41.99, 41.99, NULL, 'Food & Beverages > Alcoholic Beverages > Liquor & Spirits', 'https://cf.shopee.com.br/file/br-11134207-81z1k-meha11f2i13702', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1605305232%2F23998877926', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
