INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22999195803', 'Tênis Infantil Bibi Space do Homem-Aranha', 'O tênis Space da Bibi, em colaboração oficial com a Marvel, traz o herói mais querido da criançada para os passinhos do dia a dia. Com artes exclusivas do Homem-Aranha, cores vibrantes e luzes que piscam, o modelo transforma cada movimento em uma missão cheia de aventura, sem abrir mão do conforto e da segurança. Por que escolher o Space do Homem-Aranha? Luzes LED que acendem a cada passo, dando um show de brilho e diversão; Palmilha Fisioflex, que oferece a sensação de andar descalço e auxilia no desenvolvimento natural dos pezinhos; Calce fácil com tira ajustável, garantindo ajuste firme e autonomia para as crianças; Cabedal macio com estampa do Homem-Aranha e teias, resistente para o uso diário e super estiloso; Materiais seguros e livres de substâncias tóxicas, além de solado leve e antiderrapante para passos mais estáveis; Com o Space Bibi x Marvel, cada passo vira uma aventura de super-herói. Garanta já esse modelo iluminado e acompanhe as descobertas da criançada com muito estilo, conforto e imaginação!', 299.9, 299.9, NULL, 'Baby & Kids Fashion > Boy Shoes > Sneakers', 'https://cf.shopee.com.br/file/sg-11134201-8227i-mhgad33goqh16b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1325759944%2F22999195803', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18399559124', 'Caderno brochura capa dura quadriculado 1x1cm 96 folhas D Mais Tilibra', 'O Caderno Quadriculado 1x1cm Brochura Capa Dura D+ Azul 96 Folhas possui capa dura e folhas quadriculadas de 1x1cm. Ideal para o dia a dia na escola, auxiliando o aluno no desenvolvimento da coordenação motora e no aprendizado da escrita. Detalhes: - Capa: dura - Folhas: quadriculadas 1x1cm - Miolo - Formato: 200mm x 275mm - Gramatura: 56 g/m² - Número de folhas: 96 folhas', 27.84, 27.84, NULL, 'Stationery > Notebooks & Papers > Notebooks & Notepads', 'https://cf.shopee.com.br/file/sg-11134201-824iu-mdyz0ujqornp03', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400736454%2F18399559124', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18197155255', 'Colar feminino de prata 925 coração zircônias coloridas', 'Apresentamos o deslumbrante Colar Feminino de Prata 925 com Coração e Zircônias Coloridas da Aqua Joias, uma joia que combina encanto, estilo e cores vibrantes em um colar feminino perfeito para adicionar um toque de elegância ao seu visual. Confeccionado em prata 925 de alta qualidade, esse colar oferece brilho excepcional e durabilidade. O pingente em formato de coração é delicadamente adornado com zircônias coloridas, que capturam a luz e adicionam um brilho deslumbrante à peça. Cada zircônia é selecionada cuidadosamente para garantir um visual encantador e sofisticado. O colar possui uma corrente veneziana de 45cm, que proporciona um encaixe confortável e elegante ao redor do pescoço. Com um peso leve de 1,80 gramas, esse colar é perfeito para uso diário, oferecendo conforto e estilo sem esforço. O fecho bóia garante segurança e praticidade ao colar feminino, permitindo que você o ajuste de acordo com seu conforto e preferência. Na Aqua Joias, somos especialistas em criar joias femininas de qualidade excepcional. Nosso colar de prata 925 com coração e zircônias coloridas é cuidadosamente confeccionado, com atenção aos detalhes, resultando em uma peça de joalheria elegante e encantadora. Adicione um toque de estilo e sofisticação ao seu look com o Colar Feminino de Prata 925 Coração Zircônias Coloridas da Aqua Joias. Clique agora em "Comprar" e desfrute da qualidade excepcional e do encanto único que só uma joia Aqua Joias pode oferecer!', 175.95, 142.9, NULL, 'Fashion Accessories > Necklaces', 'https://cf.shopee.com.br/file/sg-11134201-7rfic-m9k8yy9hmd348b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F328147687%2F18197155255', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '55354207664', 'Rack com Painel para Sala TV até 43" 1 Porta 3 Prateleiras 136cm Nogueira/Off White - J Carvalho', 'O Rack com Painel Denver J Carvalho é a solução ideal para quem deseja organizar a sala ou o quarto com praticidade e estilo, mesmo em ambientes compactos. Compatível com TVs de até 43 polegadas, ele combina design moderno, acabamento elegante em Nogueira/Off White e prateleiras funcionais para eletrônicos e itens decorativos. BENEFÍCIOS DO PAINEL: Compatível com TVs até 43”, ideal para espaços menores Organização eficiente, com 3 prateleiras funcionais Visual moderno e discreto, que valoriza a decoração Montagem simples, com manual e kit de ferragens inclusos Fácil manutenção, limpeza prática no dia a dia CARACTERÍSTICAS DO PAINEL: Marca: J Carvalho Material: MDP Cor: Nogueira / Off White Acabamento: Finish Foil Escala de Brilho: Fosco Indicado para TVs de até 43 Polegadas 3 Prateleiras Dimensões: 110 cm (L) x 90 cm (A) x 15 cm (P) Peso: 12,07 kg MONTAGEM: Sistema de Montagem: Parafusos e Cavilhas Produto entregue desmontado Acompanha manual de montagem e kit de ferragens O Rack Detroit J Carvalho é a escolha perfeita para quem busca sofisticação, funcionalidade e resistência em um único móvel. Com design moderno e acabamento em Nogueira/Off White, ele acomoda TVs de até 55 polegadas e oferece excelente espaço para eletrônicos, objetos decorativos e organização do dia a dia. BENEFÍCIOS DO RACK: Ideal para TVs de até 55”, perfeito para salas de estar Organização inteligente, com prateleira, nichos e porta basculante Armazenamento discreto, com porta basculante e dobradiças metálicas Mais estabilidade, com pés reguláveis em polipropileno Montagem prática, com manual e kit completo inclusos CARACTERÍSTICAS DO RACK: Marca: J Carvalho Material: MDP Acabamento: Finish Foil Fosco Cor: Nogueira / Off White Indicado para TVs de até 55 Polegadas Suporta até 15 kg 1 Prateleira 3 Nichos 1 Porta Basculante com Dobradiça Metálica 4 Pés Reguláveis em Polipropileno (17 cm) Sistema de Montagem: Parafusos e Cavilhas DIMENSÕES E PESO: Altura: 53,5 cm Largura: 136 cm Profundidade: 36 cm Peso: 20,95 kg CUIDADOS: Limpar com pano seco ou levemente umedecido.', 747.89, 409.9, NULL, 'Home & Living > Furniture > Shelves & Racks', 'https://cf.shopee.com.br/file/sg-11134201-8262f-mj5w3qgoefwi8f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F390327339%2F55354207664', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
