INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '11106796218', 'Fita crepe 48mmx50m 101LA 3M', 'Fita crepe 48mmx50m - 101LA - 3M A Fita Crepe 3M 101 LA prende, veda e protege superfícies de respingos de tinta. Resistente e fácil de usar, o produto não rasga durante o uso e pode ser cortado com a mão, sem necessidade de usar tesoura. O adesivo da Fita Crepe 3M 101 LA adere instantaneamente a papéis, metais, madeiras, plásticos, vidros, áreas pintadas e outras superfícies sem descolar - inclusive em locais irregulares e cantos arredondados. No momento da remoção, o produto descola suavemente e por inteiro, sem quebrar ou danificar a superfície. A Fita 101 LA é um utensílio indispensável em todas as caixas de ferramentas, escritórios e até mesmo em casa. Versátil, ela pode ser usada para fechamento de embalagens e caixas de papelão, pendurar placas de sinalização temporárias, fazer marcações para pinturas e muitas outras utilidades. Detalhes: - Medidas: 48mm x 50m - Fácil de aplicar - Remoção limpa - Linha de pintura com excelente acabamento - Resistente a água e solventes - Alta adesão', 28.92, 28.92, NULL, 'Stationery > School & Office Equipment > Strings & Tapes', 'https://cf.shopee.com.br/file/sg-11134201-7rd4e-m6zgpil37guk0b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400736454%2F11106796218', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18699458554', 'Etiqueta adesiva TP18 coração multicolor neon Pimaco', 'A Pimaco Multiuso Coração Multicor Neon Ø18,79mm é a escolha perfeita para quem deseja adicionar um toque de cor e personalidade a seus projetos, seja para organização, personalização ou decoração. Com seu formato em coração e cores neon vibrantes, essas etiquetas são ideais para destacar, identificar e até mesmo criar elementos criativos em diversas situações. Perfeitas para quem busca um produto versátil e visualmente atrativo, as Pimaco Multiuso Coração são ideais para uso pessoal, profissional e escolar. Detalhes: - Tamanho: Ø18,79 mm - Quantidade de folhas 5 - Quantidade de etiquetas por folha 20 - Quantidade de etiquetas por envelope 100.', 16.48, 13.85, NULL, 'Stationery > Notebooks & Papers > Labels & Stickers', 'https://cf.shopee.com.br/file/sg-11134201-81ztf-mn1v4wpgtdz41c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400736454%2F18699458554', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
