INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '14903108621', 'Bomba pulverizadora agrícola de pistão 30 - 45 l/min Sem motor - BPF45 - Tekna', 'Produto: Bomba pulverizadora agrícola de pistão 30 - 45 l/min Sem motor - BPF45 Marca: Tekna Descrição: A Bomba pulverizadora agrícola de pistão sem motor BPF45 da Tekna, proporciona vazão de 30 - 45 litros por minutos e pressão de 21-45KG/CM2. A BPF45 é indicada para pulverização agrícola em culturas em geral, pode ser acionada por motores elétricos de 2 a 3 KW ou a combustão de 2,7 a 4 HP. Possui Regulador de pressão com trava, Manômetro com glicerina, Registros de esfera em latão, Câmara de compensação, Visor de nível do óleo, Base para acoplamento com furação universal Fabricada em ferro fundido. Além disso a Bomba pulverizadora é acompanhada de mangueira de descarga, mangueira de sucção, polia dupla, kit de reparo, filtro de suçção e suporte. Especificações: Vazão: 30-45 l/min Rotação: 300-1000 rpm Pressão máxima: 21-45 kgf/cm"² Potência necessária: 2,7 a 4 hp Material do cabeçote: Ferro fundido Polia: Sim Mangueira de sucção: Sim Mangueira de retorno: Sim Filtro sucção: Sim. Itens Inclusos: Polia dupla" " em "V", Ø 210mm Mangueira de descarga:" 1/2" x 2.10 m Mangueira de sucção:" 1" x 2.30 m Kit de reparo Kit de remoção Filtro de sução Suporte do equipamento." Dimensões (C x L x A): 36.50 x 30.00 x 34.70 centímetros Peso: 12.00 Kg', 765.89, 709.9, NULL, 'Home & Living > Tools & Home Improvement > Water Pumps, Parts & Accessories', 'https://cf.shopee.com.br/file/sg-11134201-825b3-mr2d25xs4ves91', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F489001115%2F14903108621', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21597987160', 'Jogo 2 Pneus Barum by Continental Aro 14 Bravuris 5HM 185/65R14 86H', '*Nossas vendas são realizadas apenas para consumidor final, sendo vetada a comercialização para CNPJ de revendedores.Resistente ao choque com o piso, o Bravuris 5HM, da Barum,foi desenvolvido a partir da tecnologia de polímeros que propiciam total resistência e excelente desempenho, principalmente em pistas molhadas. Seu design de nervura central com ranhuras laterais otimizadas oferecem rolamento suave e seguro. Sobre a marca Barum A marca Barum nascida na Europa a partir da união das marcas Checoslováquia Bata, Rubena e Mitas, a Barum iniciou sua produção em 1966, em Otrokovice, na República Checa. Em 1993, a marca passa a fazer parte do Grupo Continental e, em 2014, se torna conhecida mundialmente. Qualidade aliada à custo-benefício é a principal característica dos produtos da Barum.', 883.4, 812.73, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Automobile Tires', 'https://cf.shopee.com.br/file/sg-11134201-7rfga-m329piffga2u0d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F549724933%2F21597987160', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
