INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22398185379', 'White Lub 300ML Desengripante Lubrificante Desengraxante SuperOrbi Quimica', 'White Lub Desengripante Spray 300ml Lubrificante Desengraxante Orbi Química Saiba por que comprar o desengripante Whitelub da Orbi Química: - Anti-ferrugem e anti-umidade: Previne o acúmulo de ferrugem e repele a umidade, ideal para ambientes úmidos e externos. - Desbloqueio instantâneo: Solta peças emperradas com facilidade, poupando tempo e esforço. - Proteção prolongada: Forma uma camada protetora contra ferrugem e corrosão, aumentando a durabilidade das superfícies. - Lubrificação eficiente: Reduz o atrito e melhora o funcionamento de mecanismos travados. - Penetração profunda: A fórmula avançada alcança áreas difíceis, garantindo um desempenho superior. - Fácil de usar: Spray prático que vai direto ao ponto, sem complicações. - Melhora a vida útil: A manutenção preventiva com desengripante economiza em consertos e substituições. Ficha Técnica: Fabricante: Orbi Química Modelo: WHITELUB Possui 300ml de Spray', 18.56, 18.56, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > External Parts', 'https://cf.shopee.com.br/file/br-11134201-7r98o-m8dfznp73ea91f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F729127860%2F22398185379', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
