INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19197749512', 'Triciclo Infantil You Boy 3 Menino Nathor', 'Triciclo Infantil You Boy 3 Menino Nathor O Triciclo Nathor possui um mecanismo que impede que o guidão gire além do necessário. O Limitador evita acidentes, permitindo um pedalar com muito mais tranquilidade e segurança para criança. Quadro, garfo e guidão feitos em alumínio, o triciclo Nathor é muito mais leve, pesando apenas 2kg. Possui também maior durabilidade por não enferrujar. Além de serem mais silenciosos, os Pneus em E.V.A. garantem um pedalar mais macio, menos escorregadios, mais leves e duráveis. Descrição do produto Material: Quadro, garfo e guidão em alumínio Pneus: E.V.A. Manoplas em elastômero TPE atóxico Limitador de giro do guidão Cestinha ou plaquinha Buzina “fon-fon” Altura máxima recomendada: 85cm a 100 cm Peso máximo recomendado: 21 kg Peso do produto: 2,180 Kg Peso com a embalagem: 2,780 Kg Dimensões do produto (CxAxL): 64cm x 52cm x 46cm Dimensões da embalagem (CxAxL): 43cm x 37cm x 23cm Imagens meramente ilustrativas, todos os itens que ambientam o produto não estão inclusos.', 327.51, 193.99, NULL, 'Sports & Outdoors > Sports & Outdoor Accessories > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rd5i-lwug5c65gvtm6f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F638399297%2F19197749512', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
