INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '54757502645', 'Minha vida, Minha obra | Henry Ford', 'Uma história de vida inspiradora de um grande homem, cujos princípios o guiaram a se tornar uma das figuras mais marcantes da história industrial norte-americana. Este livro, embora publicado há quase cem anos, dá uma receita ainda atual e oportuna do que é preciso para qualquer empresário ter sucesso e deve ser lido por qualquer pessoa interessada no que é necessário para fazer parte do verdadeiro sonho americano, uma noção que hoje se mantém apenas por um fio nos Estados Unidos. Uma obra que vai além das técnicas para o sucesso trata-se de como fazer uma diferença verdadeiramente positiva para o indivíduo, os funcionários e o país como um todo. 16x23cm 272 Páginas', 20.9, 15.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-8260l-mm3isicoxvyn4d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F54757502645', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
