INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12574670703', 'Chumbinho Technogun Mamuth Pro Expansão 4.5mm (.177) - 250un', 'Projetado para atiradores que buscam máxima potência e precisão, o Chumbinho Technogun Mamuth Pro Expansão combina tecnologia avançada e design Hollow Point para oferecer impacto devastador e penetração eficiente. Fabricado com um sistema exclusivo de injeção em alta pressão, o Mamuth oferece balanceamento centrífugo aprimorado, garantindo maior precisão e uniformidade nos disparos. Sua composição inclui 98% de chumbo, além de zinco e outros metais, proporcionando a dureza ideal para suportar até mesmo armas mais potentes. Por que escolher o Mamuth PRO? Máximo impacto e alto poder de expansão Produção em alta pressão para maior precisão Liga especial com 98% de chumbo para maior resistência Ideal para carabinas de média e alta potência. Características Marca: Technogun Modelo: Mamuth Pro Expansão Calibre: 4.5mm (.177) Material: Chumbo Peso: 0,53 g (8 gr) Quantidade: 250 unidades Comprimento: 7,8 mm Indicação: Carabinas de média e alta pressão Atenção Nunca atire em superfícies duras (pedras, paredes de alvenaria ou chapas de aço), pois há risco de ricochete. Utilize sempre em um ambiente seguro e com óculos de proteção. Posicione os alvos com um fundo seguro, como barrancos de terra ou chapas de EVA, para evitar transfixação. Mantenha fora do alcance de crianças e animais e utilize com responsabilidade. Garantia 3 meses contra defeitos de fabricação. Itens Inclusos 1x Lata de Chumbinho Technogun Mamuth Pro Expansão 4.5mm (250 unidades) 1x Nota Fiscal Imagens meramente ilustrativas. As cores e detalhes podem variar conforme sua tela e o produto final.', 43.0, 43.0, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Shooting & Survival Games', 'https://cf.shopee.com.br/file/sg-11134201-7rass-malubu5nf1mbbe', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F654132276%2F12574670703', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22599129561', 'Atacado C\ 6 Shampoo Lava Auto Com Cera (500 Ml) Radnaq', 'ATACADO - FRETE GRÁTIS*** CAIXA COM 6 UNIDADES DE Shampoo Lava Auto Com Cera (500 Ml) Radnaq APROVEITE A PROMOÇÃO PARA LAVAGEM AUTOMOTIVA ATACADO Shampoo Lava Auto Cremoso (500 Ml) Radnaq O Lava Autos Radnaq é um detergente concentrado que tem uma formulação desenvolvida para proporcionar uma lavagem com mais rendimento. É um produto neutro que não agride a pintura, pois não contém sais corrosivos em sua formulação. Proporciona um realce na pintura do veículo. Embalagem: 500ml ENVIO IMEDIATO TEMOS O PRODUTO A PRONTA ENTREGA CAIXA COM 6 UNIDADES FECHADA NÃO PERCA TEMPO ADQUIRA JÁ A SUA', 62.39, 62.39, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Shampoo', 'https://cf.shopee.com.br/file/sg-11134201-825as-mg6x6sfkoposc2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F391224294%2F22599129561', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8144497593', 'Kit Borracha Vedação Uno Mille 1994 1995 1996 1997 4-portas', 'O Lojão 2 Primos tem o prazer de trazer mais um produto de excelente qualidade, sucesso de vendas com preço justo! TODOS OS NOSSOS PRODUTOS SÃO ORIGINAIS , NOVOS, LACRADOS E COM GARANTIA!. Kit Borrachas Vedação de 4 Portas Os veículos possuem componentes de borracha nas portas, vidros e no teto que tem por função evitar a infiltração de água e poeiras. A avaliação periódica desses componentes é recomendada, para que eventuais infiltrações não comprometam a lataria, provocando sua corrosão e molhando o interior do veiculo. Essas borrachas protetoras são conhecidas como guarnição, e, além de serem instaladas no teto e nas portas, também podem ser encontradas nas áreas de contato entre capô, no porta-malas e nos vidros, evitando o contato direto da tampa com a carroceria. Essa é a borracha que faz o contorno da porta, vai fixada na carroceria, evitando que entre água, poeira para dentro do veiculo, diminuindo até barulhos internos e amortecendo o fechamento da porta. Compatível com FIAT Uno Mille Ano 1988 1994 1995 1996 1997 1998 1999 2000 2001 2002 2003 2004 2005 2006 2007 2008 2009 2010 2011 2012 2013, em todas as versões fabricadas: CS, S, SX, TOP, Export, Brio, Eletronic, CSL, ELX, MPI, Smart, Fire, Economy, Way, Grazie, Para outros carros e modelos, entre em contato conosco. Temos todos os modelos Entre outros veículos. Informar modelo desejado no ato da compra! Borrachas na cor preta. Produto de excelente qualidade 100% garantido. Fixado por encaixe Garantia de 3 meses Entrega para todo o Brasil. Cód: A540', 230.24, 230.24, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Others', 'https://cf.shopee.com.br/file/711dc3f5ab70cb5bb78a46d803944484', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F391224294%2F8144497593', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
