INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58252745169', 'Kit Módulo Amplificador Stetsom IR160.2 + Par Alto Falantes 5 pol JBL Triaxial 5TRFX55 110W potente', 'Módulo Stetsom IR160.2 + Par Alto Falantes 5 JBL Triaxial 5TRFX55 110W Kit completo para quem busca som forte e equilibrado: o Módulo Stetsom IR160.2 entrega potência e eficiência, enquanto o par de alto-falantes JBL 5” triaxiais 5TRFX55 de 110W garante áudio limpo, graves consistentes e agudos bem definidos, elevando a qualidade do som do seu carro. Especificações Técnicas: Módulo Amplificador Digital Stetsom IR 160.2 RCA 2 Canais - 160 Watts RMS • Número de Canais: 2 • Potência RMS em 2 Ohms 13,8V: 2 x 80W RMS • Potência RMS em 4 Ohms 13,8V: 2 x 45W RMS • Tensão de Alimentação: 9,5 ~ 15V • Resposta em Frequência: 35Hz ~ 20KHz • Relação Sinal Ruído: > 90 dB • Distorção Harmônica: > 0,03 % THD • Sensibilidade de Entrada: 2V • Impedância de Entrada: 2,4K Ohms • Impedância Mínima de Saída: 2 Ohms • Consumo com Sinal Musical: 6,4 A • Consumo com Sinal Bass: 12,8 A • Dimensões (A x L x C) mm: 29 x 58 x 77 • Peso Kg: 0,115 Kg Par de Alto Falantes 5 pol JBL FLEX4 5TRFX55 Triaxial - 110 Watts RMS • Potência Nominal: 55 Watts RMS • Resposta de Frequência @ -10 dB: 70 a 20000 Hz • Sensibilidade: 87 dB • Diâmetro Nominal: 133 (5) mm(in) • Impedância Nomina: 4 Ohms Conteúdo da Embalagem: • 01 Par de alto falantes 5 pol 5TRFX55 - 110 Watts RMS • 01 Amplificador de audio IR160.2 RCA - 160 Watts RMS • 01 Cabo de audio tipo fio • 01 Cabo de audio tipo RCA • Manual e Certificado de Garantia Importante: • Garantia de 273 Dias. • Valor do Kit.', 344.21, 323.56, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Audio System', 'https://cf.shopee.com.br/file/sg-11134201-8260o-mj5ku1u58j5u1b', 'https://shope.ee/an_redir?origin_link=https%3