INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21355716238', 'João Treme a Cauda - David Powlison', '📖 Descrição Em João Treme a Cauda, o autor David Powlison apresenta uma história infantil cristã que ensina valores bíblicos de forma simples e envolvente. A narrativa acompanha João, um menino que enfrenta medos e inseguranças, mas aprende que pode confiar em Deus em todas as situações. Com ilustrações coloridas e linguagem acessível, o livro transmite uma mensagem de fé, coragem e esperança, tornando-se uma ferramenta preciosa para pais e educadores cristãos que desejam ensinar princípios espirituais às crianças. 📊 Ficha técnica Título: João Treme a Cauda Autor: David Powlison Editora: Fiel Ano de publicação: 2025 EAN/ISBN: 9786557231838 Idioma: Português Dimensões: 22 cm x 22 cm x 1 cm Peso: 300 g Número de páginas: 32 Categoria: Literatura infantil cristã Indicação etária: Crianças a partir de 4 anos Recursos adicionais: Ilustrações coloridas, linguagem simples, mensagem bíblica de fé e coragem 🔑 Palavras-chave joão treme a cauda, David Powlison, Editora Fiel, literatura infantil cristã, fé e coragem, livro ilustrado, ensino bíblico para crianças', 36.95, 36.95, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mj8rd1m2tzpdc0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F380531074%2F21355716238', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43650102616', 'Desempenadeira Elétrica 390mm 720w 60hz Dec-700 Cortag', 'Desempenadeira Elétrica DEC 700 – Potência e Agilidade no Acabamento de Superfícies A Desempenadeira Elétrica DEC 700 é a escolha ideal para quem busca produtividade, acabamento profissional e menos esforço físico em obras e reformas. Com 720W de potência, essa ferramenta foi desenvolvida para agilizar o processo de reboco, lixamento e acabamento em paredes, gesso, massa corrida e cimento, entregando resultados uniformes e com excelente padrão. Com empunhadura adicional e cabo de 3 metros, oferece liberdade de movimento e mais ergonomia durante o uso prolongado. A trava de segurança no interruptor permite uso contínuo sem manter o dedo no gatilho, ideal para grandes áreas. A base de ABS com quatro pontos de fixação em velcro garante praticidade na troca dos acessórios. Diferenciais: - Alta performance com motor de 720W - Empunhadura emborrachada e adicional para maior conforto e controle - Interruptor com trava para uso contínuo - Suporte em ABS resistente com 4 pontos de fixação em velcro - Cabo de força com 3 metros de comprimento - Acompanha acessórios para diferentes tipos de acabamento Aplicações: - Reboco e acabamento em cimento - Lixamento e nivelamento de gesso e massa corrida - Texturização de paredes - Ideal para profissionais da construção civil e reformas residenciais Especificações Técnicas: - Potência: 720W - Alimentação: 127V ou 220V (conforme modelo) - Diâmetro do disco: 390 mm - Comprimento do cabo: 3 metros - Sistema de fixação: Velcro (4 pontos) - Peso: Aproximadamente 3,5 kg Acessórios inclusos: - 1 Desempenadeira estriada 390 mm - 1 Disco de lixa G-80 (390 mm) - 1 Esponja/filtro para desempenamento (390 mm) - 1 Suporte para discos (390 mm) - Kit com chave, parafuso e escova de carvão Otimize seu tempo e aumente a qualidade dos seus serviços com a Desempenadeira Elétrica DEC 700. Uma aliada indispensável para quem busca produtividade e acabamento de alto nível. Marca: Cortag Modelo: Dec 700', 941.05, 643.0, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rfgg-m9hskf80gtrdb6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F406223656%2F43650102616', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
