INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23001123038', 'O Caminho Para A Presença de Deus - John & Lisa Bevere', 'Neste livro O Caminho Para a Presença de Deus dos autores John Bevere e Lisa Bevere exploram oito barreiras que podem nos afastar e separar da presença de Deus. Descubra como romper essas barreiras que surgem em seu caminho para te afastar da presença do Senhor Jesus Cristo. John e Lisa Bevere lhe apresentarão como desfrutar de novos momentos de intimidade com Deus. Cada capítulo dissertara sobre uma barreira especifica e o abençoará com cinco devocionais- repletos de estratégias espirituais e orações específicas – afim de ajudá-lo ao longo do caminho que por fim o levará diante do Deus Todo-Poderoso! Inicie a jornada e veja Deus mover na sua vida. Autor: John Bevere | Lisa Bevere Editora: LAN Acabamento: Brochura Formato: 16 x 23 Cm Peso (g): 270 Idioma: Português ISBN: 9788559290110 Título: O Caminho Para a Presença de Deus | John Bevere e Lisa Bevere Subtítulo: Uma Jornada de 40 dias rumo à intimidade com Deus Páginas: 192', 43.42, 43.42, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mdzyxmu5qq682d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F380531074%2F23001123038', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
