INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40468566473', 'Livro Coragem é Agir com o Coração Fred Elboni', 'DESCRIÇÃO Coragem é Agir com o Coração convida o leitor a viver uma jornada de autenticidade, abraçando a vulnerabilidade como caminho para relações mais verdadeiras — inclusive consigo mesmo. Fred Elboni aborda temas como insegurança, expectativas externas e comparações, oferecendo reflexões que motivam o leitor a agir com o que sente, revelando seu mundo interior com honestidade e coragem. Este livro é ideal para quem busca crescimento emocional, autoconfiança e conexão genuína. Com linguagem acolhedora, instigante e prática, ele inspira a transformar o medo em força, a incerteza em expressão, e a timidez em presença. FICHA TECNICA Título: Coragem é Agir com o Coração – Como Abraçar a Vulnerabilidade e Ter Relações Mais Honestas e Verdadeiras Autor: Fred Elboni Editora: Gente Formato: Brochura Páginas: 144 Peso: 180 g Dimensões: 14 × 21 × 2 cm Edição: 1ª Ano de publicação: 2025 ISBN: 9786585044141 PALAVRAS-CHAVE coragem é agir com o coração, fred elboni, vulnerabilidade, relações autênticas, amor próprio, autoconfiança, livros de autoajuda, crescimento emocional, agir com autenticidade, coragem interior', 44.08, 44.08, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/br-11134207-81z1k-meilckmo50xube', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F380531074%2F40468566473', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
