INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '46304634326', 'Bicicleta Infantil Verden Jack Aro 12 Com Rodinhas Laterais Azul Vermelho', 'A bicicleta é um dos veículos mais escolhidos como meio de transporte, e essa tendência aumentou ainda mais com a pandemia de coronavírus. Além de seu uso para fins recreativos e esportivos, tem um impacto muito positivo no meio ambiente e bem-estar de pessoas de todas as idades. Seus benefícios são múltiplos: é acessível, ocupa pouco espaço, não gera poluição e faz bem a saúde. Junte-se a esta onda sustentável que avança em todo o mundo! Segurança e qualidade Seu freio a tambor tem muitos benefícios: sendo um sistema totalmente fechado, não é afetado pelas condições climáticas e é menos suscetível ao desgaste, por isso geralmente requer menos manutenção.', 304.56, 301.52, NULL, 'Mom & Baby > Toys > Sports & Outdoor Play', 'https://cf.shopee.com.br/file/sg-11134201-82588-mg89qqcojspac1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F401389575%2F46304634326', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18997675173', 'Porta de Aço Postigo 215x85cm com Grade Quadrada Minas Sul MGM', 'As esquadrias MGM vêm recebendo ao longo dos anos vários prêmios concedidos através de pesquisas realizadas pelo IBOPE/ ANAMACO, tornando-se assim a número um no segmento da Construção civil. As esquadrias de aço MGM são projetadas para atender a uma grande variedade de públicos, são fornecidas com pintura de acabamento eletrostática a pó na cor branca garantindo uma cobertura uniforme e durabilidade superior, tendo como opção com ou sem grade e com ou sem vidro. Produtos produzidos em aço não são recomendados para as regiões litorâneas, podendo inclusive perder a garantia do produto. Garantia: 5 Anos Tipo de Vidro: Não possui Escala de Brilho: Brilhante Lado de Abertura: Direita Textura da Porta: Lisa Acompanha Puxador: 1 Origem do Produto: Nacional Tipo de Dobradiça: Simples Ambiente Principal: Sala de Jantar Acompanha Dobradiça: 3 Material do Batente: Aço Material do Puxador: Aço Quantidade de Folhas: 1 Acabamento do Puxador: Polido Material da Dobradiça: Aço Tipo de Grade da Porta: Quadrada Tipo de Puxador da Porta: Externo Acabamento (Construção e Acabamento): Esmaltada Material Principal Construção e Acabamento: Aço Cor Predominante: Branco Tamanho do Produto: 215cm x 85cm Elétrica: Não Possui Grade: Sim Possui Vidro: Não Acompanha Trinco: Sim Acompanha Batedor: Não Acompanha Batente: Sim Acompanha Fechadura: Sim Acompanha Guarnição: Não Necessita Instalação: Não Acompanha Olho Mágico: Não Possui Isolamento Acústico: Não Acompanha Manual de Instalação: Sim Marca: MGM Cor do Produto: Branco Linha ou Coleção: Minas Sul Medida do Vão (A x L): 217cm x 87cm Tipo de Certificado: Produto qualificado mediante a norma técnica ABNT NBR 10821. Peso (kg): 17.1654 Altura (cm): 215 Largura (cm): 85 Espessura (cm): 6 Largura do Batente: 6 Dimensão da Maquina da Fechadura: 40', 802.48, 802.48, NULL, 'Home & Living > Decoration > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rd3u-lul7dh4hivj377', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F855489892%2F18997675173', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18899870725', 'PALETA ILUMINADORES FRAN BY FRANCINY EHLKE GRITANI', 'Com perfeita combinação entre no natural e o GLOW, a paleta GRITANI oferece iluminadores que vão de tons neutros a intensos em uma única paleta. Os tons ajustáveis foram cuidadosamente pensados para atender a todos os gostos e ocasiões.Porque amamos? O acabamento de segunda pele e a riqueza em brilho e pérolas, oferecem o glow perfeito e fixação prolongada.', 149.9, 149.9, NULL, 'Beauty > Makeup > Face', 'https://cf.shopee.com.br/file/sg-11134201-824hd-me5v3kkvggsmf3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1213673814%2F18899870725', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
