INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209697923', 'Pita Bread Pão Sírio Extrafino', 'O Pão Sírio Extrafino da Pita Bread é leve e versátil, perfeito para wraps, sanduíches ou acompanhando pastas e patês. Sua textura macia e sabor neutro combinam com diversos recheios. Cada pacote contém 6 unidades, ideal para refeições rápidas e saborosas.', 17.49, 14.86, NULL, 'Food & Beverages > Bakery > Breads', 'https://cf.shopee.com.br/file/sg-11134201-82623-mj72p18tlix123', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554820%2F58209697923', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
