INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23693255155', 'Kit Meia Lupo Sport Walk Cano Curto 3 Pares', 'O kit produzido pela Lupo, com meias modelo Sport Walk, é uma ótima opção para garantir o máximo de conforto e manter seus pés aquecidos no dias mais frios. Confeccionadas em algodão, poliamida e outras fibras, a peça possui cano curto e conta com acabamento canelado, que se encarrega do ajuste ideal. Além disso, vem com sola do pé semi-acolchoada, oferecendo melhor aconchego nas pisadas. Seu design é predominantemente branco e a logo da marca fornecedora é vista em preto e azul próximo a barra. Adquira já a sua!Composição: 79% Algodão, 19% Poliamida e 02% Outras fibrasContém: 03 pares brancosOrigem: NacionalCano: Curto', 46.9, 46.9, NULL, 'Men Clothes > Socks', 'https://cf.shopee.com.br/file/sg-11134201-7rdvr-lzwfc6an5a94df', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1337527569%2F23693255155', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20598186607', 'Camisa Kappa Vasco II 2025 Feminina', 'A Camisa Vasco II 2025 da Kappa é a escolha perfeita para os torcedores apaixonados vestirem seu orgulho. Com design elegante e tradicional, traz o branco como cor predominante e a icônica faixa transversal preta. Confeccionada em poliéster e elastano com tecnologia no tecido, oferece conforto, leveza e respirabilidade. O escudo do clube bordado se destaca no peito. Detalhes como a frase “Sou Vascaíno” na nuca e “Jamais terá a cruz. Este é meu batismo” no interior da gola reforçam a identidade cruzmaltina. A gola em V, punhos e nuca em preto completam o visual moderno e fiel à história do Vasco.TecnologiasKOMBAT PRO SYSTEM®: Técnica autêntica que atribui uma elegância italiana ao design do produto, sustentando-se nas especificidades dos atletas profissionais.Hidroway Protection: Tecido de alta performance com absorção de umidade e secagem rápida, proporcionando melhor conforto e excelente caimento.Composição: 97% Poliéster e 03% ElastanoCor predominante: BrancoClube: Vasco da GamaModelo: TorcedorGênero: FemininoOrigem: NacionalEscudo: BordadoManga: CurtaGola: VDimensões aproximadas (A x L):P: 60 x 48 cmM: 62 x 50 cmG: 64 x 52 cmGG: 67 x 54 cm', 215.9, 215.9, NULL, 'Men Clothes > Tops > Shirts', 'https://cf.shopee.com.br/file/sg-11134201-7ratx-macngha7a15u94', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1337527569%2F20598186607', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
