INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58207707631', 'Pente Basic Dentes Finos Ricca', 'Para um cabelo impecável e alinhado, o Pente Basic Dentes Finos Ricca é a escolha certeira. Com dentes finos e resistentes, ele é ideal para penteados mais detalhados e para aquele retoque rápido que salva o dia! Por que escolher o Pente Basic Dentes Finos? Compacto e leve, ele é perfeito para carregar na bolsa e usar sempre que precisar. Funciona bem em todos os tipos de cabelo e é o acessório essencial para o dia a dia ou para arrasar em ocasiões especiais. Como usar: Utilize para alinhar os fios, separar mechas ou criar penteados com precisão. Características: Dentes finos para maior precisão Design leve e portátil Compatível com todos os tipos de cabelo Com o Pente Basic Dentes Finos Ricca , seus fios ficam no lugar e você pronta para brilhar. Porque #RiccaLover sabe que um pente básico é indispensável!', 16.9, 16.9, NULL, 'Beauty > Beauty Tools > Hair Tools', 'https://cf.shopee.com.br/file/br-11134275-820lg-mmamcartp2x39a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1328633078%2F58207707631', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
