INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '56400329183', 'LAIKOU Japão Sakura Blooming Radiance : Kit Multifuncional De Cuidados Com A Pele , Beatuy Para Presente Feminino Menina', 'Kit de Beatuy de Presente de Pele para Sakura do Japão Radiância de Florescimento: Kit All-in-One Sakura Skincare, Kit de Presente de Cuidados com a Pele para Meninas Informações básicas do produto do produto Vida útil da prateleira de 5 anos O pacote inclui: conjunto de 3 peças Sakura (sérum 17ml, creme 30g, creme para os olhos 15g) + limpador Sakura 50g + máscara de descascamento Sakura 50g + máscara de dormir Sakura 5pcs + máscara de olhos Sakura 2pcs + máscara labial Sakura 2pcs + caixa de presente + cartão de presente Características do Produto 🌸 Rotina Sakura: Um regime de cuidados com A pele de limpeza A tratar e máscara. Pele úmida e radiante em uma linda caixa. 💖 Radiância e hidratação florescendo: Alimentado por Sakura Japonesa (flor de cerejeira), conhecido por iluminar a pele sem brilho e fornecer frescor duradouro - perfeito para combater os efeitos de um clima úmido. 🎁 Experiência de presente de luxo final: Apresentado em uma caixa de presente exclusiva com tema de Sakura com um cartão de saudação rosa, tornando-o o presente perfeito para qualquer ocasião especial. ✨ Tratamentos etiquetados para cada necessidade: Apresenta máscaras exclusivas (dormindo, descasca, olho, lábio) para cuidados intensivos, além de essenciais do núcleo (essência, creme, creme para os olhos) para nutrição diária. ✨ Benefícios e efeitos da chave: Tom de brilho e uniformização: O extrato de Sakura ajuda a reduzir o visual do embotamento, promovendo um brilho translúcido e radiante. Hidrata profundamente: Bloqueia na umidade para manter a pele carnuda, úmida e refrescada o dia todo. Purifies & Refines: A máscara peel-off ajuda a desenhar impurezas e minimizar a aparência dos poros. Cuidados com o Targeted: O creme para os olhos e patches visam olheiras, enquanto a máscara labial nutre os lábios secos. Nutrição multiuso: A máscara de dormir funciona durante a noite para reparar e acordar para uma pele brilhante.', 260.0, 129.0, NULL, 'Beauty > Beauty Sets & Packages', 'https://cf.shopee.com.br/file/cn-11134207-820l4-mgeik75zpte551', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F250961519%2F56400329183', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
