INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23106013640', 'Kit 3 Shampoos Seda Cachos Definidos 325ml cada', 'O Kit contém 3 Shampoos Seda Cachos Definidos com 325ml cada Shampoo com exclusiva tecnologia Fitagem Complex. Shampoo que mantém os fios sob controle e com volume. Shampoo Seda que contém filtro UV. Cachos definidos e saudáveis. Shampoo para cabelo cacheado. Shampoo Seda Cachos Definidos pode ser usado diariamente. Não tem nada que faça a gente se sentir melhor do estar com o cabelo cacheado bem definido, não é mesmo Porque se estamos com cachos lindos, nós também nos sentimos lindas! Pensando nisso, Seda criou o Shampoo Seda Cachos Definidos 325ml, formulado com a exclusiva tecnologia Fitagem Complex, que sela e alinha as fibras capilares, deixando os fios lindos e com cachos de arrasar, além de deixá-los cheios de vida e muito bem definidos. A tecnologia Fitagem Complex é uma mistura que combina queratina, conhecida pelas propriedades de reconstrução e força, e biotina, responsável por deixar unhas e cabelos mais saudáveis. O Shampoo Seda Cachos Definidos 325ml é ótimo para cabelos cacheados que buscam mais nutrição e definição dos fios, porque além de uni-los suavemente, oferece finalização com controle de frizz e hidratação. Dúvidas em como usar É simples e mega fácil Coloque o Shampoo Seda Cachos Definidos 325ml nas mãos e aplique-o diretamente nos cabelos molhados. Massageie bem e enxágue.', 48.16, 48.16, NULL, 'Beauty > Hair Care > Shampoo', 'https://cf.shopee.com.br/file/sg-11134201-22110-f3repfxlj1jv9e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F528273775%2F23106013640', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
