INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58253930451', 'Creme Acetinado Desodorante Hidratante Corporal Eudora Rosé 250g', 'O Creme Acetinado Desodorante Hidratante Corporal, de Eudora, foi elaborado pensando na mulher sofisticada que valoriza o luxo. É Ideal para deixar sua pele macia, sedosa, com aspecto aveludado e perfumada pela intensa fragrância de Eudora Rosé. Com textura cremosa, propicia hidratação intensa por até 48 horas e um toque acetinado maravilhoso, além de deixar a pele perfumada e desodorizada. Já a fragrância marcante traz o toque borbulhante do espumante para a assinatura da linha, combinando Frutas Vermelhas, a elegância da Rosa e a densidade das madeiras em um Chypre Frutal radiante e sofisticado. Nenhum produto Eudora é testado em animais, ou seja, este item possui selo Cruelty Free. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 119.99, 119.99, NULL, 'Beauty > Bath & Body Care > Body Cream, Lotion & Butter', 'https://cf.shopee.com.br/file/sg-11134201-8261m-mju18hv61tzabb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1679511787%2F58253930451', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
