INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58255840539', 'Copo de Treinamento Buba em Silicone Verde 120ml', 'Copo de Treinamento em Silicone Buba Copinho de Silicone Azul O copo de silicone da Buba é ideal para auxiliar no desenvolvimento do hábito de beber líquidos de maneira regular e independente. É seguro para as crianças em casos de queda, pois o silicone não quebra e possui toque frio, impedindo transferência da temperatura do líquido garantindo o toque suave para as mãos sensíveis da criança. Já as alças promovem maior sensação de confiança e independência para as crianças. - Capacidade: 120ml. - Feito em silicone de grau alimentício, atóxico e livre de BPA. - Livre de BPA.', 46.09, 37.4, NULL, 'Mom & Baby > Feeding Essentials > Utensils', 'https://cf.shopee.com.br/file/sg-11134201-825zs-ml6d9h1tw1e79e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1045085918%2F58255840539', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
