INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22399374266', 'Colcha 300 Fios Montrelle Kacyumara Rose Parisi', 'A Colcha Montrelle foi desenvolvida para quem valoriza elegância, qualidade e acabamento impecável. Seu caimento refinado proporciona um visual sofisticado à cama, enquanto o acabamento em viés adiciona um toque de requinte que faz toda a diferença na composição do ambiente. Os porta-travesseiros acompanham o mesmo padrão da colcha, garantindo harmonia e um resultado visual impecável. Confeccionada em cetim de algodão egípcio 300 fios, a Colcha Montrelle oferece toque extremamente suave e acetinado, além de alta durabilidade. O tratamento anti-pilling evita a formação de bolinhas, mantendo a peça bonita e confortável por muito mais tempo. Características Tamanhos Solteiro: 1,80 x 2,40 m Casal: 2,20 x 2,40 m Queen: 2,40 x 2,60 m King: 2,80 x 2,60 m Super King: 3,20 x 2,70 m Porta-Travesseiro Solteiro: 1 unidade Casal, Queen, King e Super King: 2 unidades Composição 300 Fios 100% Algodão Egípcio Diferenciais Acabamento Caimento impecável que valoriza o ambiente. Antipilling Tecido com maior durabilidade e sem formação de bolinhas. Garantia Garantia de devolução de até 7 dias corridos após o recebimento do produto. Solicite pelo nosso SAC. Lavagem Siga as instruções de lavagem dispostas na etiqueta do produto. Atenção As cores do produto podem apresentar variações sutis de acordo com o lote de fabricação e/ou configurações de tela.', 799.9, 679.92, NULL, 'Home & Living > Bedding > Blankets, Comforters & Quilts', 'https://cf.shopee.com.br/file/sg-11134201-8260b-ml5063sn44r113', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1516596857%2F22399374266', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
