INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43703218884', 'Kit Vinagre Capilar Forever Liss Com Máscara Anabolizante 200g', 'Descrição: O Vinagre Capilar de Maçã 200ml age nos fios como uma selagem capilar. Recupera cabelos danificados, restaura o pH, deixa os fios hidratados e macios. Por ser um produto com pH baixo, sela as cutículas, tratando a porosidade e mantendo hidratados por muito mais tempo, sem pontas duplas e sem frizz. A Máscara Anabolizante Forever Liss 240g é um potente recurso para quem precisa regenerar cabelos secos, frágeis e danificados por processos químicos. Sua fórmula enriquecida com ativos como proteína de soja, Óleo de Coco, Aminoplex, Creatina, Arginina e Pró-Vitamina B5 nutre profundamente os cabelos, enquanto sua ação umectante hidrata os fios restaurando a vitalidade e o movimento. Modo de uso Vinagre Capilar 01. Logo após lavar e condicionar os cabelos, borrife o Vinagre Capilar de Maçã em todo o comprimento do cabelo. 02. Penteie os cabelos. 03. Finalize como desejar. Máscara Anabolizante 01. Logo após lavar os cabelos com o Shampoo Anabolizante, aplique a Máscara Anabolizante nos fios ainda úmidos, espalhando em todo o comprimento. 02. Enluve mecha a mecha. 03. Deixe agir de 15 a 20 minutos. 04. Enxágue até retirar o produto por completo. 05. Finalize como desejar. Contém 01 - Vinagre Capilar de Maçã Forever Liss 200ml. 01 - Máscara Anabolizante 200g.', 112.8, 93.9, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-7raum-mamomo1uokqb57', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F427106553%2F43703218884', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
