INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22195905611', 'KIt 6 Aditivos Radiador Delphi Diluído RL10012 - Cód.8483', 'Aditivo de Radiador Diluído Delphi RL10012 100% Orgânico (ecológico), recomendado para todos os sistemas de arrefecimento de veículos e motores estacionários, atendendo e superando todas as normas vigentes. Modo de Uso: - Siga as recomendações do fabricante do veículo ao adicionar aditivo para radiadores. - Drenar completamente e lavar com água limpa o sistema de arrefecimento do veículo. - Adicionar o aditivo no sistema de arrefecimento (não adicionar água - produto pronto para uso). - Checar o nível periodicamente e completar com aditivo diluido Delphi, se necessário. - Armazenar em local fechado, seco e sob temperatura ambiente. O aditivo de radiador deverá ser substituído a cada 5 anos ou 241.000 km ou completado o quanto antes se necessário. O trabalho de substituição do líquido de arrefecimento deverá ser executado por um profissional qualificado, pois é necessário eliminar todo ar do sistema durante o reabastecimento. Caracterísitcas: - Anticorrosivo - Anticongelante - Antibolhas - Antifervura Não nos responsabilizamos pelo mau uso do produto. Atende / Supera normas NBR15.297, NBR13.075, ASTM D-3306, ASTM D-4340', 146.32, 146.32, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Additive and Lubricant', 'https://cf.shopee.com.br/file/sg-11134201-7rdxy-mcm5plsb0vng17', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F634548170%2F22195905611', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
