INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23798888220', 'Kit 3 Sabonete em Barra Hidratante Nivea Pure Milk Sensitive 90g', 'Sabonete em Barra Hidratante Nivea Pure Milk Sensitive 90g O que é? Sabonete hidratante que oferece cuidado, proteção e de renovação da pele todos os dias. Cuide bem de você! Para que serve o Sabonete em Barra Nivea Leite Puro Sensível? A fórmula enriquecida com a essência preciosa do leite e deliciosa continha, proporciona uma pele macia e hidratada mesmo após o banho. Benefícios e diferenças: - Fórmula especial hidrata a pele - Fragrância suave e delicada - Sabonete Glicerinado - Dermatologicamente testado Como usar o Sabonete em Barra Nivea Pure Milk Sensitive? Massageie o sabonete sobre a pele molhada até formar uma espuma e enxágue em seguida. Indicações: 1. Massageie o sabonete sobre a pele molhada até formar espuma. 2. Enxágue em seguida. Instruções: Massageie o sabonete sobre a pele molhada até formar espuma. Enxague em seguida. Informação De Segurança: Descubra uma incrível sensação de cuidado, de proteção e de renovação da pele. O sabonete em barra NIVEA PURE MILK BEAUTY ELIXIR na versão SENSITIVE possui uma fórmula especial enriquecida com a preciosa essência do leite e deliciosamente adotada que proporciona uma sensação de pele macia e hidratada durante e após o banho. O cuidado com você começa no banho! Dermatologicamente testado e compatível com a pele. Ingredientes: Descubra uma incrível sensação de cuidado, de proteção e de renovação da pele. O sabonete em barra NIVEA PURE MILK BEAUTY ELIXIR na versão SENSITIVE possui uma fórmula especial enriquecida com a preciosa essência do leite e deliciosamente adotada que proporciona uma sensação de pele macia e hidratada durante e após o banho. O cuidado com você começa no banho.', 11.67, 11.67, NULL, 'Beauty > Bath & Body Care > Body Wash & Soap', 'https://cf.shopee.com.br/file/sg-11134201-825av-mqm0b1en5bf074', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F23798888220', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
