INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19998035305', 'Banheira Bebê Portátil Banheira Inflável Infantil 55 Litros Banheira Para Banho Do Bebê Love - Mor', 'Banheira Bebê Inflável Cores: • Rosa • Bege - Azul Em três delicadas cores e estampas, a Banheira Bebê oferece todo o conforto para o seu bebê. Com capacidade para até 55 litros de água e medindo 92cm de diâmetro, ela é perfeita para ajudar as mamães a tornar a hora do banho ainda mais gostosa! É excelente para usar aonde você estiver. Produzida em vinil resistente, acompanha quatro câmaras de ar independentes, uma válvula de deságue e kit reparo. É recomendada para crianças maiores de 1 ano. A Banheira permite ver a temperatura ideal da água através de um indicativo interno: quando a água atingir de 32° até 38°, a cor que você verá será Azul, 38° será Bordô e acima de 38° será Vermelho. Tudo isso para o bem-estar do seu pequeno. Há ainda, um gancho para pendurar e facilitar a secagem. Para segurança e comodidade, há um apoio inflável opcional, que evita deslizamentos. Mais uma praticidade Mor para o seu dia a dia! Atenção! Nunca deixe crianças sozinhas perto da água sem supervisão de um adulto. Especificações: Material: PVC Formato: Oval Tamanho: Entre 90cm e 1m Idade: Até 3 anos Capacidade: 55 litros Medidas: Altura: 33,00 Centímetros Largura: 61,00 Centímetros Comprimento: 92,00 Centímetros Mor Peso 865,00 Gramas', 171.42, 120.0, NULL, 'Mom & Baby > Bath & Body Care > Bathing Tubs & Seats', 'https://cf.shopee.com.br/file/sg-11134201-7rdve-mcqdlczoomd82e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F800925303%2F19998035305', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
