INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18764883762', 'Kit 2 Absorvente para Incontinência Urinária Tena Lady Discreet Maxi Night 6 Unidades', 'Absorvente para Incontinência Urinária Tena Lady Discreet Maxi Night 6 Unidades Absorvente para Incontinência Urinária TENA Lady Discreet Maxi Night Noturno faz parte da linha TENA Lady Discreet, produtos exclusivos para mulheres com incontinência urinária. Proteção diária para mulheres ativas com perda moderada de urina. TENA Lady Maxi Night foi especialmente projetado para proporcionar uma boa noite de sono. São macias e confortáveis, favorecendo proteção adicional devido ao seu formato específico: são mais largas na parte de trás com maior área de cobertura e extra absorção quando deitado. Produto que você fixa na roupa íntima, evitando que ele se desloque com o movimento; Possui sistema Odour Control™ - Sistema de controle que reduz o risco de odores indesejáveis; Dry Fast Core™ - Núcleo de secagem rápida que absorve e retém o líquido mais rapidamente; Superfície com toque de tecido - Maior conforto e sensação de maciez; Absorve 9x mais que o absorvente menstrual garante segurança e excelente proteção contra vazamentos. Os componentes são atóxicos e pré-testados.', 53.98, 53.98, NULL, 'Health > Personal Care > Feminine Care', 'https://cf.shopee.com.br/file/sg-11134201-823oe-mowbql92cvf397', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F18764883762', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
