INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22335657056', 'Hot Wheels Mario Kart Nemesis - Mattel', 'Hot Wheels Mario Kart Nemesis - Mattel Hot Wheels traz a ação em ritmo acelerado do mundo de Mario Kart à vida real com dois sets inspirados nas icônicas pistas do aclamado videogame. Cada set inclui uma réplica do veículo de Mario Kart em metal, que as crianças podem lançar para superar obstáculos e desafios, igualzinho ao filme, mas, desta vez, em uma pista Hot Wheels®! Ficar na pista é a chave para ser o corredor mais rápido do trajeto! “Suba de nível” e adicione mais desafios conectando cada um desses sets de pistas ao set completo pistas Mario Circuit (vendido separadamente). Acrobacias incríveis e corridas emocionantes para crianças que adoram Mario Kart! Vendidos separadamente. Sujeito a disponibilidade. Cores e decorações podem variar. Selo Inmetro: 00128-18A', 275.99, 275.99, NULL, 'Hobbies & Collections > Collectible Items > Vehicle Models & Diecast', 'https://cf.shopee.com.br/file/sg-11134201-82629-ml5j410mxwch41', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F952529254%2F22335657056', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
