INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18097494228', 'Kit Maçaneta Interna Gol G4 2005 a 2014 Fox 2003 a 2009 Grafite', '🚀 ENVIO IMEDIATO — PRODUTO EM ESTOQUE NO BRASIL! ⚡ Enviamos assim que o pagamento é confirmado. Produto em estoque para envio rápido. ⚙️ Maçanetas internas para Volkswagen Gol G4 e Fox, indicadas para reposição das peças quebradas, moles ou travando. Ajudam a recuperar a abertura correta das portas e manter o acabamento interno do veículo. 🚗 Compatível com: Volkswagen - Gol G4 2005 a 2014 Volkswagen - Fox 2003 a 2009 ℹ️ Mais Informações: Cor: Grafite Material: Plástico Aplicação: Portas dianteiras e traseiras Kit com 4 maçanetas internas Encaixe direto, sem adaptações Ideal para reposição Produto novo, embalado e protegido 🏷️ Tags: #macanetainterna #macanetaporta #kitmacanetainterna #macanetagolg4 #macanetafox #macanetainternagolg4 #macanetainternafox #macanetavolkswagen #macanetaportagol #macanetaportafox #portadianteira #portatraseira #acabamentointerno #volkswagengol #volkswagenfox #golg4 #gol2005 #gol2010 #gol2014 #fox2003 #fox2006 #fox2009', 67.11, 61.75, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Others', 'https://cf.shopee.com.br/file/br-11134207-820m3-mqcczywjvvgi02', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373280378%2F18097494228', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
