INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23407015512', 'Rack Estante TV 65" com Leds Berlim Multimóveis Madeirado/Preto', 'O Rack Estante TV 65" com Leds Berlim Multimóveis vai deixar sua sala de estar mais bonita e aconchegante para você curtir os melhores filmes e séries com a família ou amigos. Produzido em MDP, que garante maior durabilidade e facilidade na limpeza, além de um acabamento superior, possui 2 portas articuladas com um excelente espaço interno para organizar seus pertences. Além de prateleiras para que você possa personalizar a decoração, conta com nichos para acomodar todos os equipamentos eletrônicos. O painel para TV de até 65” (suporta até 30kg) possui espaçamento para passagem dos fios, que permite deixar os cabos mais organizados. Com design minimalista e de fácil instalação, as luminárias em LED proporcionam um visual mais moderno e você pode escolher em qual lugar do móvel deseja fixar. Com luz brilhante, as luminárias funcionam com 3 pilhas AAA. Conteúdo da Embalagem: 1 (uma) estante 1 (um) kit com 2 luminárias LED Dimensões do produto montado: Altura: 171cm | Largura: 213cm | Profundidade: 38cm Painel - Altura: 98cm | Largura: 150cm *Devido as variações de tamanho dos televisores no mercado, sugerimos que verifique as medidas da sua TV e compare com o painel antes de efetuar a compra. *Não recomendamos utilizar suporte de TV articulado. *Você pode consultar as medidas internas na imagem técnica do produto. *As cores do produto podem sofrer variações de tonalidade de acordo com as configurações do seu dispositivo. Imagem meramente ilustrativa. Decoração e eletros não acompanham o produto. O produto será entregue desmontado e não disponibilizamos o serviço de montagem.', 1059.99, 859.99, NULL, 'Home & Living > Furniture > Shelves & Racks', 'https://cf.shopee.com.br/file/sg-11134201-22100-9i7htzpw24iv19', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F308628919%2F23407015512', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21897684306', 'ATRACAO MAGNETICA VOL 01', 'ATRACAO MAGNETICA VOL 01 Uma bela jovem com um segredo, determinada a fazer de tudo para vencer na carreira. Um bilionário decidido, com habilidades que vão muito além de seus dons em informática. Uma paixão avassaladora que vai pôr de ponta cabeça os planos de todos os envolvidos. Sobre o autor Erica Hathaway aprendeu desce cedo a não depender de ninguém. Recém formada em Harvard e dando início à própria empresa, tudo o que ela não quer é perder seu foco profissional por conta de paixonites juvenis. Planos, porém, são feitos para falhar. Em uma reunião decisiva, Erica conhece o misterioso e genial empresário Blake Landon e se vê imediatamente atraída por ele. Apesar de o sentimento ser mútuo, ela resiste aos avanços implacáveis de Landon. O que ele não imaginava era que Erica escondesse um segredo inimaginável, que pode pôr a perder não só a relação entre os dois, como também a vida que ela lutou muito para construir. Sobre o autor Meredith Wild é autora best seller internacional e dos jornais New York Times e USA Today. Com uma casa em New Hampshire onde mora com o marido e os três filhos, Meredith se define como uma apreciadora de tecnologia e whisky, além de uma romântica inveterada.. Informações Adicionais Autor: WILD, MEREDITH Data Publicação: 01/01/1900 Tipo de capa: BROCHURA Condição do Item: Novo Subtitulo: ATRACAO MAGNETICA VOL 01 Idioma: PORTUGUES Páginas: 288 Edição: 1 ISBN-13: 9788522031269 ISBN-10: 8522031266', 20.98, 15.94, NULL, 'Books & Magazines > Books > Fantasy', 'https://cf.shopee.com.br/file/sg-11134201-7rd4j-lvn5cu1ixyfv5b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F826663787%2F21897684306', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
