INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '13348039657', 'Macacão de Bebê Pezinho Amore Bolinha 100% Algodão', 'DESCRIÇÃO Seu bebê merece esse conforto! O Macacão Pezinho com Ziper e protetor de Ziper é uma exclusividade da Amore pensada especialmente para os pequenos. São macias e confortáveis, feitas com tecido Suedine 100% algodão, para tornar o dia do seu amor mais alegre e cheio de estilo. DETALHES • Confeccionados com tecido macio em Suedine 100% Algodão • Pezinho • Ziper • Protetor de Ziper TAMANHO • RN = Recém Nascido • P = 3 Meses de Idade • M = 6 Meses de Idade • G = 9 Meses de Idade • GG = 12 Meses de Idade Ou em Centímetros. O tamanho em centímetros é entre a gola do macacão e o pezinho. Rn - 48cm P - 51cm M - 56cm G - 61cm GG - 66cm ESPECIFICAÇÕES 1 Macacão com Ziper A mercadoria é composto somente pelos produtos da descrição acima.', 34.9, 32.9, NULL, 'Baby & Kids Fashion > Baby Clothes > Bodysuits & Jumpsuits', 'https://cf.shopee.com.br/file/br-11134207-820mg-mnfpqrd8lq8170', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F435692544%2F13348039657', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
