INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19897678522', 'Shampoo Pantene Pro-V Miracles Queratina 300ml', 'Você já reparou o quanto você expõe o seu cabelo ao calor? (Sol, Chapinha, Secador, Babyliss...). Apresentamos o shampoo e condicionador Pantene Queratina Preenche & Blinda, nossa fórmula Pro-V Miracles com Queratina.O shampoo penetra no cabelo, fazendo uma limpeza e blindagem que protege, enquanto o condicionador identifica e preenche fios danificados, para alinhar e selar, facilitando o desembaraço. Use o shampoo e condicionador e a linha completa Preenche & Blinda para uma reparação contra danos causados até pelo calor. Cabelos mais resistentes e brilhantes.Fórmula que não pesa com Queratina e Pro-Vitamina B5, para cabelos danificados. pH balanceado.Short DescriptionVocê já reparou o quanto você expõe o seu cabelo ao calor? (Sol, Chapinha, Babyliss...). Apresentamos Pantene Queratina Preenche & Blinda, nossa fórmula Pro-V Miracles com Queratina e Pro-Vitaminas B5. Fórmula que não pesa.O shampoo penetra no cabelo, fazendo uma limpeza e blindagem que protege, enquanto o condicionador identifica e preenche fios danificados, para alinhar e selar, facilitando o desembaraço. Use a linha completa de shampoo e condicionador Preenche & Blinda para uma reparação contra danos causados até pelo calor.Cabelos mais resistentes e brilhantes. O shampoo penetra no cabelo, fazendo uma limpeza e blindagem que protege O condicionador identifica e preenche fios danificados, para alinhar e selar, facilitando o desembaraço A linha completa Preenche & Blinda repara o contra danos, causados até pelo calor Cabelos mais resistentes e brilhantes Contém Queratina e Pro-Vitaminas B5, para cabelos danificados pH balanceado Fórmula que não pesa', 35.99, 33.08, NULL, 'Beauty > Hair Care > Shampoo', 'https://cf.shopee.com.br/file/sg-11134201-