INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58204634427', 'Macacão Feminino Decote em V Dianna Preto', 'Macacão Feminino Decote em V Dianna, confeccionado em viscose creponada, que garante leveza, fluidez e elegância ao vestir. Possui base lisa e decote em V profundo, formando alças com aplicação de argolas metálicas, além de fita interna de sustentação para maior segurança. Conta com recorte com elástico para melhor ajuste ao corpo, bainha com acabamento limpo e bolso sobreposto aplicado na reta, com pesponto aparente e abertura com bainha. Uma peça versátil, ideal para compor looks sofisticados.', 119.99, 119.99, NULL, 'Women Clothes > Jumpsuits, Playsuits & Overalls > Overalls', 'https://cf.shopee.com.br/file/sg-11134201-8258b-mr060tgm8kjk09', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F778895824%2F58204634427', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18997728967', 'Kit Relação Yamaha Fazer 250 2005 Com Retentor Original Kmc', 'KIT RELAÇÃO COMPLETO FAZER 250 (COROA/PINHAO E CORRENTE COM RETENTOR) NOVO NA CAIXA - ORIGINAL KMC PRINCIPAIS APLICAÇÕES: MOTOS: YAMAHA YS FAZER 250 ANO: 2005 Á 2016, *Aço 1045 *Corrente 428HX132L (COM RETENTOR) *45 dentes da coroa *15 dentes do pinhão Função da Coroa e do Pinhão: A Coroa e o Pinhão juntamente com a corrente são conhecidos como kit relação, e são fundamentais para uma pilotagem segura, sendo responsáveis por transmitir o movimento da saída da transmissão até a roda traseira. Como detectar problemas? Verifique se há desgastes nos dentes da coroa e do pinhão. Ao trocar verifique também: o ideal é realizar a troca do kit inteiro (coroa, pinhão e corrente) para garantir a durabilidade do conjunto, ruídos e folga na transmissão de força. Diferenciais: Produzida em aço 1045 Endurecimento térmico para aumentar a resistência e durabilidade Número de dentes conforme padrão original Dentes tratados termicamente. ****Recomendamos que os produtos sejam instalados por profissionais especializados***', 225.0, 196.0, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Transmission', 'https://cf.shopee.com.br/file/sg-11134201-7rd61-lx1f8wrzyoukac', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F445101258%2F18997728967', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
