INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23298170577', 'Pista Hot Wheels T-Rex Batalha Blaze - Mattel JBM73', 'Você pode enfrentar um T-Rex faminto que atacou o quartel de bombeiros da Hot Wheels City com um caminhão de brinquedo em escala 1:64! O conjunto apresenta um dinossauro nêmesis em grande escala que tem olhos que giram toda vez que os carros passam até que ele seja nocauteado! Lançar os carros com força suficiente gira os olhos e arranca os dentes do dinossauro, para que ele seja comido e depois expulso! Você pode recarregar e reiniciar, mas dessa vez você é desviado pelo posto de combustível. É melhor abastecer para a próxima corrida! Fabricante: Mattel Ref.:JBM73 Código Barras:194735264186 Idade recomendada: Acima de 3 Anos Dimensões da Embalagem (AxLxC): 25X45X10cm Garantia do Vendedor: 7 dias Garantia do Fabricante: 3 meses Produto original, novo, lacrado e acompanhado de Nota Fiscal.', 402.99, 299.99, NULL, 'Mom & Baby > Toys > Toy Vehicles', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m5mu21y50r4g67', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1162387686%2F23298170577', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
