INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22694558103', 'Regata Vôlei De Praia Brasil Oficial Masculina Verde Volt', 'Regata Vôlei de Praia Brasil Oficial Masculina Volt é a peça ideal para quem vive a intensidade das areias. Utilizada pelos atletas da Seleção Brasileira de Vôlei de Praia, ela combina performance, conforto e identidade nacional. Com tecido leve e de secagem rápida, oferece excelente respirabilidade e liberdade de movimentos. O visual traz os escudos da CBVP e da Confederação Brasileira, além do patrocínio do Banco do Brasil, em um design vibrante e autêntico.', 199.99, 199.99, NULL, 'Men Clothes > Tops > Tanks', 'https://cf.shopee.com.br/file/sg-11134201-825a4-mqw2p6x0o93976', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1645847036%2F22694558103', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23193555036', 'Porta Chumbinho 28 Unidades 4,5mm Preto Prático Cordilheira Sport', 'LOJA CORDILHEIRA SPORT! PORTA CHUMBINHOS CORDILHEIRA 28UN 4,5MM Este porta chumbinhos é ideal para aqueles que utilizam chumbinho 4.5mm, podendo ser facilmente fixado no equipamento ou no braço da pessoa. Ele utiliza elásticos e velcro para garantir uma fixação segura e prática. Além de ser muito confortável no braço, o design permite fácil acesso aos chumbinhos, oferecendo capacidade para armazenar até 28 unidades. CARACTERÍSTICAS Marca: Cordilheira Sport Modelo: Porta Chumbinhos Cor: Preto Calibre: 4,5mm Capacidade: 28 unidades Material: Fibra de Nylon e Borracha Medidas: 7 x 5 cm Peso: 7g Acompanha Chumbinhos: Não ITENS INCLUSOS 01 Porta Chumbinhos Cordilheira 28 unidades 4,5mm *Não acompanha Chumbinhos* GARANTIA: 7 DIAS PELO VENDEDOR NÃO NECESSITA CR PARA COMPRA! ATENÇÃO!!!!! O USO DO PRODUTO EXIGE TREINAMENTO E EQUILÍBRIO EMOCIONAL. DEVERÁ SER GUARDADO EM LUGAR SEGURO E FORA DO ALCANCE DE TERCEIROS. Todos os produtos anunciados estão em estoque a pronta entrega. Só comercializamos produtos NOVOS e com NOTA FISCAL em nome do comprador e com garantia. Nossos envios são muito rápidos e feitos no mesmo dia desde que a compra seja confirmada até as 12 horas. Prezamos muito o nosso comprometimento com o cliente, todas as perguntas são respondidas o mais rápido possível. COMPRANDO MAIS ITENS DA LOJA VOCÊ TEM DESCONTO NO FRETE!!! VER TODOS OS PRODUTOS DA LOJA EM: “VER MAIS ANÚNCIOS DO VENDEDOR” OU “PERFIL DA LOJA”', 23.0, 22.05, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Shooting & Survival Games', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m353ojphe7tfdd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F443107548%2F23193555036', NULL,