INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21999032848', 'Sonda Lambda C4 Pallas 2.0 16V 2007 08 09 10 11 12 2013 PRE - 1681 - 882640057', 'Sonda Lambda C4 Pallas 2.0 16V 2007 08 09 10 11 12 2013 PRE Citroen - C4 Pallas 2.0 16V 2007/2013 (4 Fios) (57cm) (Planar) (PRE CATALISADOR) A sonda lambda, sensor de oxigênio, sensor de O2, por vezes também chamado sensor EGO (do inglês exhaust gas oxygen), é um dispositivo que envia um sinal elétrico à injeção eletrônica do automóvel indicando a presença de oxigénio nos gases de escape, possibilitando o controle da quantidade de combustível a enviar para o motor.', 271.23, 271.23, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Injection', 'https://cf.shopee.com.br/file/sg-11134201-7rbn3-lmz3i2i70ml5c7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F21999032848', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22492902577', 'Bóia Tanque Sensor Nível Fiat Palio 2000 a 2012 - 1333525 - 2301', 'Bóia Tanque Sensor Nível Fiat Palio 2000 a 2012 1333525 2301 Motor 1.4/1.8 4Cil 8v MPI Flex O sensor de nível de combustível tem a função de medir a quantidade de combustível presente no tanque e informar a UCE (Unidade de Comando Eletrônico) que, por sua vez, controla a posição do marcador de nível no painel de instrumentos do veículo.', 101.93, 101.93, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Body', 'https://cf.shopee.com.br/file/sg-11134201-7rbn4-ln03t9c42t1n33', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22492902577', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58261160857', 'Palheta Limpador Bosch Multiclip Universal Borracha natural Silenciosa + Aditivo Naska', 'PALHETA BOSCH MULTICLIP – COMPATIBILIDADE, DURABILIDADE E LIMPEZA PERFEITA! 🚗💨 A Palheta Bosch Multiclip foi desenvolvida para oferecer máxima compatibilidade e alta performance, unindo a eficiência da linha Aerofit com a tecnologia dos conectores exclusivos Aerotwin Bosch. Com sistema Multiclip e conexão Quick-Clip, ela se adapta a diversos modelos de veículos, proporcionando instalação rápida, prática e segura. Sua estrutura Flat Blade totalmente em plástico, sem partes metálicas expostas, oferece maior durabilidade, resistência e excelente desempenho em qualquer condição climática. A borracha natural com tratamento em grafite garante um deslizamento suave e silencioso no vidro, reduzindo atrito, vibrações e trepidações durante o uso. ✅ BENEFÍCIOS E VANTAGENS • Compatível com diversos modelos de veículos • Sistema Multiclip com instalação rápida e prática • Tecnologia Flat Blade para melhor desempenho • Estrutura resistente sem partes metálicas expostas • Borracha natural com tratamento em grafite • Limpeza eficiente, silenciosa e sem trepidações • Excelente visibilidade em chuva forte • Alta durabilidade e resistência • Produto original Bosch 🎁 ITENS INCLUSOS ✔ 2 Palhetas Bosch Multiclip conforme medidas do fabricante ✔ 1 Aditivo Limpa Para-brisa Naska 100ml ⚠ IMPORTANTE • Verifique corretamente o modelo e ano do veículo antes da compra • O verso da embalagem apresenta apenas um resumo das aplicações • Caso tenha dúvidas sobre compatibilidade, entre em contato antes da compra • Produto com garantia de 3 meses • Imagens ilustrativas • Não nos responsabilizamos pelo uso incorreto do produto COM A NASKA A TECNOLOGIA ESTÁ AO SEU ALCANCE. YOU MAKE IT HAPPEN. 🚀', 165.0, 148.5, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > External Parts', 'https://cf.shopee.com.br/file/br-11134207-820ln-moinmgvzhretd3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F347237979%2F58261160857', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
