INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21899240337', 'Rotor Distribuidor Vw Santana 1984 a 1992 - 106578 - 21215', 'Rotor Distribuidor Vw Santana 1984 a 1992 106578 21215 TODOS (IGNIÇÃO ELETRÔNICA) O rotor é um dispositivo do sistema de ignição que tem por finalidade, distribuir as centelhas de alta tensão para cada um dos pólos da tampa do distribuidor. Alguns rotores possuem uma resistência entre seu contato central e sua extremidade. Essa resistência serve para atenuar as interferências eletromagnéticas provocadas pela alta tensão do sistema.', 37.91, 37.91, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Ignition', 'https://cf.shopee.com.br/file/sg-11134201-822wn-mo9x3ffnh8ge8c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F21899240337', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
