INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23097976286', 'PASTA D'' ÁGUA SIMPLES COM 120G', '• Alívio Clássico para Irritações da Pele: A Pasta D''Água é um medicamento tradicional e eficaz para o alívio de irritações cutâneas. Sua principal função é secativa, antisséptica suave e calmante. • Indicada para Brotoejas e Queimaduras Solares: Perfeita para aliviar a coceira e o desconforto causados por brotoejas, queimaduras solares de primeiro grau, assaduras e picadas de inseto. • Ação Calmante e Protetora: O Óxido de Zinco presente na fórmula cria uma camada protetora sobre a pele, ajudando a acalmar a área irritada e a acelerar a cicatrização. • Fórmula Simples e Segura: Um produto essencial para se ter em casa, para o cuidado de toda a família. ESTE É UM MEDICAMENTO. SEU USO PODE TRAZER RISCOS. PROCURE O MÉDICO E O FARMACÊUTICO. LEIA A BULA. • Palavras-chave: Pasta D''Água, Óxido de Zinco, Brotoeja, Queimadura Solar, Coceira, Pele Irritada, Secativo.', 36.2, 36.2, NULL, 'Beauty > Bath & Body Care > Body Cream, Lotion & Butter', 'https://cf.shopee.com.br/file/sg-11134201-7rdy5-m1hb9v2ay2m7f4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1251200960%2F23097976286', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
