INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23192645656', 'Eico Pro Spray Fluído Leave-in Finalizador Protetor Térmico Filtro Solar Hidratante 0% Frizz 200ml', 'Eico Pro Spray Fluído Leave-in Finalizador – 200ml O Eico Pro Spray Fluído Leave-in é o aliado perfeito para proteger e cuidar dos fios no dia a dia. Sua fórmula leve e eficaz conta com protetor térmico, filtro solar e ativos hidratantes que preservam a saúde do cabelo, proporcionando maciez, brilho e controle absoluto do frizz. Com ação multifuncional, ele protege contra os danos causados pelo calor de secadores, chapinhas e modeladores, além de blindar os fios contra a ação nociva dos raios UV. Ideal para todos os tipos de cabelo, mantém a hidratação por mais tempo sem pesar e garante um acabamento sedoso e natural. Benefícios: Proteção térmica e solar Hidratação intensa e duradoura Controle de até 0% frizz Fórmula leve, não oleosa Indicado para todos os tipos de cabelo Modo de usar: Borrife sobre os fios úmidos ou secos, do comprimento às pontas, e finalize como desejar. Não enxágue.', 69.9, 32.37, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/br-11134207-7r98o-md586o2g9df685', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F385344228%2F23192645656', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19297798362', 'Parachoque Traseiro Celta 2007 2008 2009 2010 2011 Preto', 'Código do produto: DTS1744 Parachoque Traseiro Celta 2007 2008 2009 2010 2011 2012 2013 2014 2015 2016 Preto É um item indispensável para manter o design, originalidade e segurança de seu veículo. Possui material resistente, composto em plástico da mais alta qualidade com textura lisa e acabamento impecável sem falar no padrão de fabricação igual aos originais que mantem um alinhamento perfeito em seu veículo. Compatível com: Chevrolet - Celta 2007 - Celta 2008 - Celta 2009 - Celta 2010 - Celta 2011 - Celta 2012 - Celta 2013 - Celta 2014 - Celta 2015 - Celta 2016 Especificações Técnicas - Parachoque Traseiro - Textura Lisa - Material em Plástico ATENÇÃO Garantia - 3 Meses O valor anunciado referente a Unidade. A empresa não se responsabiliza pela má instalação do produto. Procure por um profissional especializado!', 435.44, 435.44, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Body', 'https://cf.shopee.com.br/file/sg-11134201-7rdvq-lzgivn3ihnwn61', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F469347212%2F19297798362', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20498089107', 'Kit 5 Óleo Motor W-Flex Sae 10w40 Api Sn Semi-sintético', 'Este anúncio contem: 01 - Litro de Óleo SAE 10w40 API SL Semi-Sintético. Óleo lubrificante de base semissintetica para motores à gasolina, àlcool, gnv e Flex. Óleos minerais básicos, base sintética, pacote de aditivos detergente e dispersante, aditivo melhorador de viscosidade e abaixador de ponto de fluidez. Autorização: ANP SDL 557. A nossa empresa comercializa apenas produtor originais de fabricantes certificado pelo ISO 9001. Dúvidas frequentes: Nós trabalhamos apenas com produtos novos e com garantia. Nossos produtos são de qualidade original, respeitando todas as regras do fabricante. Produto a pronta entrega. Seus produtos serão enviados em até 24 horas úteis. Sobre nossa empresa: Estamos há mais de 30 anos no mercado de autopeças, buscando sempre a satisfação dos nossos clientes. Trabalhamos com as melhores marcas do ramo automotivo e aqui você encontrará as melhores peças para seu veículo, e contará com qualidade e o melhor atendimento. Nossos produtos são todos rigorosamente conferidos e embalados para que chegue até você da melhor maneira.', 199.82, 183.83, NULL, 'Spare Parts and Accessories for Vehicles > External Accessories for Automobiles > Others', 'https://cf.shopee.com.br/file/br-11134207-820lm-mopqwnffzv9hc1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F615444977%2F20498089107', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
