INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22302003783', 'Tonalizante Color Touch Castanho Claro Intenso Marrom Cinza 5/71', 'O Tonalizante Color Touch possui uma exclusiva fórmula tri spectra que garante até 70% de cobertura dos fios brancos, e um cabelo 50% mais brilhante que um cabelo natural. Possui formulação sem amônia, que proporciona uma cor vibrante e duradoura sem danificar os fios capilares. Color Touch proporciona maior intensidade e cobertura da cor enquanto oferece aos cabelos um cuidado com uma suavidade extrema. O Sistema Care Control, aliado a ingredientes naturais e vitamina C, trata e protege os fios enquanto colore. O Intensificador de Brilho gds garante tonalidades intensas e reflexos luminosos. As 97 nuances de Color Perfect podem ser multiplicadas várias e várias vezes graças ao super mix: Tons intensos que reforçam, matizam e variam as nuances de cor. O Color Touch foi desenvolvido a partir de amplas pesquisas e avanços tecnológicos, é um tonalizante de base cremosa, o que facilita na mistura e na aplicação da coloração.', 51.29, 51.29, NULL, 'Beauty > Hair Care > Hair Colour', 'https://cf.shopee.com.br/file/sg-11134201-825ad-mq7qudrlse8c32', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F683941545%2F22302003783', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
