INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22195008166', 'Tênis Ous Fluente Preto Branco Gold Essencial', 'Confortável e robusto, o Fluente é uma ótima escolha para quem busca desempenho no skate ou visual para o dia a dia. Seu cabedal é confeccionado em camurça curtida, livre de metais pesados, com detalhes em material sintético e mesh, garantindo resistência. Além disso, o forro esportivo traz ventilação, mantendo os pés frescos durante o uso. O solado possui um novo design, composto por borracha Granular A+, oferecendo aderência ao solo, enquanto a entressola em EVA proporciona conforto e absorção de impactos. Além disso, o cadarço em poliéster é resistente, com passadores com proteções extra para maior durabilidade. O modelo ainda conta com etiquetas e um puxador localizado na parte traseira, que facilitam o calce, além de elástico na lingueta, mantendo-a sempre no lugar. Para completar, o Fluente vem com a palmilha Ative, que pode ser lavada na máquina, trazendo praticidade para o dia a dia.', 429.9, 365.42, NULL, 'Men Shoes > Sneakers', 'https://cf.shopee.com.br/file/sg-11134201-823qk-moyghbyckp35fe', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1490976150%2F22195008166', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '47060530911', 'Kit Coberdrom Edredom Dots Percal 300 Fios Manta Sherpa Dupla Face Matelado', 'Com visual elegante e acabamento acolhedor, o Coberdrom Dots combina beleza e conforto para deixar suas noites ainda mais agradáveis. A união do toque macio com o aquecimento suave do Sherpa cria uma peça dupla face pensada para proporcionar bem-estar em todas as estações mais frias. Além de confortável, seu design delicado valoriza a decoração do quarto, tornando a cama ainda mais convidativa. Atenção: As cores do produto podem sofrer pequenas variações devido à configuração da tela do seu dispositivo. Especificações do Produto Solteiro: 01 Coberdrom: 2,20m x 1,60m 01 Porta Travesseiro: 70cm x 50cm Queen: 01 Coberdrom: 2,40m x 2,20m 02 Porta Travesseiros: 70cm x 50cm King: 01 Coberdrom: 2,60m x 2,40m 02 Porta Travesseiros: 70cm x 50cm Super King: 01 Coberdrom: 2,80m x 2,60m 02 Porta Travesseiros: 70cm x 50cm Composição Tecido Sherpa: 100% Poliéster Enchimento: 100% Poliéster 300 Fios 100% Poliéster Destaques do Produto Conforto Térmico Agradável: Combinação que aquece com leveza e suavidade Toque Macio e Aveludado: Sensação aconchegante que envolve durante o descanso Dupla Face Versátil: Permite variar o visual da cama com praticidade Design Elegante: Acabamento que valoriza a decoração do quarto Ideal para Quem busca noites mais quentinhas com conforto e suavidade Ambientes que pedem charme e aconchego na composição da cama Presentear com um item funcional, bonito e perfeito para dias mais frios', 199.9, 144.9, NULL, 'Home & Living > Bedding > Blankets, Comforters & Quilts', 'https://cf.shopee.com.br/file/sg-11134201-822xb-mo8axgap3q4i83', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316749752%2F47060530911', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
