INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23993261696', 'Jogo Calota Calotinha Tampa Central Aro 17 18 Volcano Space Prata SEM Emblema', 'Produto: Calota Volcano Space Prata Trabalhamos com produtos de Alta qualidade, se vc procura qualidade e peças bonitas, compre nossos produto pode ter certeza que irá se surpreender com a qualidade de nossos produtos que é um grande diferencial comparado a outros produtos existentes no ML Aplicação: Rodas de Liga leve Volcano Modelo Space Aro 17 e 18 Valor referente a: 04 UNIDADES SEM EMBLEMA (ao efetuar a compra coloque 01 na quantidade que se refere ao kit com 04 unidades) Disponível nas cores: Prata Forma de fixação da peça: Encaixe Disponível em estoque: Sim Produto novo: Sim Material da calota: Plástico Abs Forma de envio: Mercado Envios - Os produtos são enviados pelo correio ou transportadora isso é definido pelo mercado envios de acordo com o CEP da sua região Temos loja física localizada em São Caetano do Sul - SP Bairro: Cerâmica Antes de efetuar a compra, verifique todo o anúncio afim de adquirir corretamente o produto que precisa, e se o modelo anunciado é o mesmo da sua roda, caso não seja não garantimos compatibilidade, verifique também as medidas informadas nas fotos, cor e quantidade desejada e se seu ENDEREÇO DE ENVIO ESTÁ CORRETO, evitando assim aborrecimentos com sua compra Não aceitaremos devolução de produtos comprados para teste e não nos responsabilizamos por adaptações! Desde já agradecemos e ficamos a disposição para dúvidas através do campo de perguntas ou após a compra também há opção de envio de fotos através da opção mensagem ao vendedor para confirmação do produto adquirido', 119.9, 119.9, NULL, 'Spare Parts and Accessories for Vehicles > External Accessories for Automobiles > Wheel Cover', 'https://cf.shopee.com.br/file/sg-11134201-7rcei-m6k22mn7mgip