INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23793622973', 'Pneu Aro 17 Bridgestone 215/55R17 Turanza ER370 94V', 'Nascida Em 1931 no Japão, a Bridgestone Tem Se Dedicado a Criar Pneus Que Oferecem Uma Experiência Única Ao Volante. Marcada por Inovação, Desempenho e Compromisso Com a Segurança, os Pneus Bridgestone Proporcionam Confiança Em Cada Curva. Líder Global no Mercado de Pneumáticos, a Bridgestone Também Estabeleceu Sua Marca Com Pneus de Alta Durabilidade e Resistentes Ao Desgaste. Conteúdo da Embalagem: • - 01 - Pneu Trnz Er370 215/55r17 Bl94v - Bridgestone Aplicações de Veículos: • - Compass • - Fusca • - Altima • - 407, 407 Sw • - Es350, Gs350 • - E-j7 • - Airtrek • - Forester, Outback • - Camry, Previa • - S-cross, S-cross Ii, Vitara, Vitara Ii • - Montana Iii, Tracker Iii • - Hr-v Especifiações Técnicas: • - Marca: Bridgestone • - Modelo: Turanza Er370 • - Medida: 215/55r17 • - Largura: 215mm • - Perfil: 55% • - Aro: 17 • - Diâmetro Total Em Mm: 668.3 • - Índice de Peso: 94 - 670 Kg , 94 • - Índice de Velocidade: v - 240 Km/h , t • - Rft = Runflat: Não • - Tipo de Construção: Radial • - Peso Unitario: 11.0 • - Extra Load: Não • - Protetor de Bordas: Não • - Sidewall: Bsw Letras Pretas • - Tipo de Terreno: Ht • - Desenho: Assimétrico • - Registro Inmetro: 002598/2012 • - Garantia: 5 Anos Contra Defeito de Fabricação • - Observações: Produto Novo. Imagem Meramente Ilustrativa - Vianx - • Este Produto Possui 60 Meses de Garantia. • Imagens Meramente Ilustrativas. • a Garantia é Responsabilidade do Fabricante e Esta Limita Se Apenas á Troca de Qualquer Produto Encontrado Com Defeitos de Fabricação Desde Que Tenha Sido Utilizado Corretamente ou Devidamente Instalado por Um Profissional Qualificado.', 892.9, 892.9, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Automobile Tires', 'https://cf.shopee.com.br/file/sg-11134201-7ra2t-m4uo7rw3sdze50', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F428720624%2F23793622973', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
