INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58200067317', 'Sabonete Esfoliante Panvel Glow 120g', 'Conteúdo: 120g O Sabonete Esfoliante Corporal Glow renova a pele, removendo as células mortas. Sua fórmula enriquecida com ingredientes de origem natural promove a hidratação da pele enquanto esfolia e limpa, deixando-a preparada para o uso dos autobronzeadores da linha Panvel Glow. Para que serve o Sabonete Esfoliante Panvel? Esfoliar gentilmente a pele, removendo células mortas. Quais são os benefícios do Sabonete Esfoliante Panvel? Vegano Livre de Parabenos Livre de Triclosan Maciez Esfoliação gentil Hidratação Modo de uso Aplique sobre o corpo úmido, massageando com movimentos circulares e, em seguida, enxágue retirando todo o produto da pele. Recomendações Gerais / Precauções Uso externo. Mantenha fora do alcance de crianças e ao abrigo da luz solar e do calor. Em caso de contato com os olhos, enxágue abundantemente. Não aplique sobre a pele ferida ou irritada. Em caso de sensibilidade, suspenda o uso e procure orientação médica. Produto inflamável, mantenha longe de fonte de calor ou chama.', 19.99, 19.99, NULL, 'Beauty > Skincare > Others', 'https://cf.shopee.com.br/file/sg-11134201-821ga-mgx1db9kvyfd1b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1609010660%2F58200067317', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
