INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58260139798', 'Sabonete em Barra Original Johnson''s', 'O Baby Sabonete em Barra Johnson Original limpa suavemente sem agredir a pele delicada do bebê, mantendo sua barreira natural de proteção. Sua fórmula é dermatologicamente testada e é livre de parabenos e ftalatos, deixando o tradicional cheirinho de bebê Johnson''s após o banho. Esfregue primeiro o produto nas mãos até obter uma espuma cremosa. Em seguida, espalhe a espuma na pele do bebê. Enxágue na sequência. O sabonete não deve ser usado na região dos olhos e deve ser aplicado por um adulto ou sob sua supervisão. Não agride e nem resseca a pele pois não contém álcool, nem triclosan. Ideal para peles delicadas. Fórmula chega de lágrimas que não agride os olhos.', 7.99, 7.99, NULL, 'Mom & Baby > Bath & Body Care > Hair Care & Body Wash', 'https://cf.shopee.com.br/file/sg-11134201-82581-mqnekewh2rd97e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554792%2F58260139798', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
