INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22093078923', 'Interruptor De Embreagem F250 F350 F450 F550 F650 Ranger 6 Pinos - 3RHO456', 'Interruptor de Embreagem: Segurança e precisão para cada troca de marcha! O Interruptor de Embreagem é o componente crucial que garante a perfeita comunicação entre o pedal da embreagem e o sistema de partida do seu veículo, proporcionando partidas seguras e precisas, além de proteger componentes vitais. Com design robusto e tecnologia de ponta, o interruptor oferece: Precisão impecável: Aciona o sistema de partida no momento ideal, garantindo partidas rápidas e sem trancos. Segurança reforçada: Evita partidas acidentais com o veículo engatado, protegendo você e outros. Não deixe para depois, faça seu pedido agora e garanta partidas seguras e precisas para seu veículo! Veículos FORD: Aerostar (1988-1994) Bronco (1988-1996) Bronco II (1988-1990) Explorer (1991-2001) Explorer Sport (2001-2003) F-150 (1988-1997) F-250 (1988-1997) F-250 Super Duty (1999-2010) F-350 (1988-1997) F-350 Super Duty (1999-2010) F-450 Super Duty (1999-2010) F-550 Super Duty (1999-2010) F-550 (2000-2010) F-650 (2000-2010) F-750 (2000-2010) Ranger (1990-2012) Thunderbird (1989-1995)', 196.12, 196.12, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Transmission', 'https://cf.shopee.com.br/file/sg-11134201-7rd6v-lvt9f8hlufdu35', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1005342012%2F22093078923', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
