INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58255130663', 'Kit Automotivo Aplicador de Espuma Vonixx Pano Microfibra E Pincel Detalhamento', 'KIT CONTÉM: 1- PANO DE MICROFIBRA SORTIDO 1- PINCEL DETALHAMENTO YAMASE 1- ESPONJA YAMASE brinde 1- APLICADOR DE ESPUMA VONIXX Tenha tudo o que você precisa para cuidar do seu carro com qualidade profissional! Nosso kit reúne os melhores acessórios para um acabamento impecável: Pano de Microfibra: Macio e super absorvente, ideal para limpar, polir e retirar resíduos sem riscar ou danificar a pintura. Pincel para Detalhamento: Perfeito para alcançar cantinhos difíceis, removendo sujeiras e poeira de áreas como grades, emblemas, painéis e detalhes internos. Espuma Aplicadora de Cera: Proporciona uma aplicação uniforme e eficiente da cera, facilitando o acabamento brilhante e proteção da pintura. Tudo para manter seu veículo limpo, protegido e com aparência de showroom, de maneira prática e eficiente!', 38.92, 38.92, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Towels', 'https://cf.shopee.com.br/file/br-11134207-81ztt-mkmke4qenls36a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316945044%2F58255130663', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
