INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22892851947', 'Cuba Pia para Banheiro Retangular Dalla Preta', 'Modelo: Dalla Preta; Altura: 11 cm; Largura: 31 cm; Comprimento: 44 cm; Tipo: de sobrepor; Material: Mármore Sintético; Forma: Retangular; Quantidade de furos para torneira: Não se aplica; Válvula indicada: 7/8 ou 1 ; Inclui torneira: Não; Embalagem do envio: Isopor, papelão e plástico. Informações adicionais: - Os objetos que ambientam as fotos não acompanham o produto; - O produto será entregue desmontado; - É de inteira responsabilidade do cliente a montagem do produto e/ou instalação, custos de transporte por escadas e/ou elevadores, guincho ou içamento, assim como possíveis irregularidades provenientes de manuseio inadequado; - Embora o produto acompanhe o manual de montagem, verifique a complexidade antes de decidir montá-lo sozinho, recomendamos que contrate um profissional de sua confiança; - Fique atento, nossas cores podem sofrer alterações dependendo do seu monitor; - ANTES DE MONTAR O SEU PRODUTO, certifique-se que todas as instruções dispostas no manual, bem como todas as ferragens descritas, estejam presentes dentro da embalagem. Verifique se há alguma peça danificadas, caso esteja, prestaremos a devida assistência dentro do prazo da garantia.', 219.99, 219.99, NULL, 'Home & Living > Tools & Home Improvement > Sinks & Water Taps', 'https://cf.shopee.com.br/file/sg-11134201-7rccn-lrxgdagtexx0a6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F401986069%2F22892851947', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22294923399', 'Boné Unissex Olympikus Running Preto/Cinza', 'O Boné Unissex Olympikus Running Preto/Cinza foi desenvolvido para acompanhar o ritmo da corrida com leveza, ventilação e ajuste confortável. Confeccionado em tecido leve de poliéster com elastano, oferece toque macio e encaixe flexível, proporcionando maior conforto durante treinos e atividades esportivas. A estrutura com cinco painéis conta com dois painéis laterais com furos a laser que favorecem a ventilação, ajudando a manter a cabeça fresca mesmo em treinos mais intensos. A aba curva e maleável permite dobrar e guardar com facilidade durante a corrida. O fechamento em tira aderente garante ajuste prático, enquanto o logo com tecnologia refletiva aumenta a visibilidade em ambientes com pouca luz. As Lojas Radan contam com 10 lojas físicas no Rio Grande do Sul, oferecendo esta e uma grande variedade de produtos e marcas de calçados e vestuário feminino, masculino, infantil e esportivo. Compre online com entrega rápida para todo o Brasil ou em uma de nossas lojas físicas, aproveitando nossa experiência e adquirindo produtos de qualidade. Aproveite! Produto de autenticidade garantida vendido pela Lojas Radan. A cor do produto nas fotos pode sofrer alteração em decorrência do uso do flash ou da configuração do seu monitor. Características: Nome do produto: Boné Unissex Olympikus Running Preto/Cinza Modelo: OIWB251713 Indicado: Dia a dia, esportivo Categoria: Boné esportivo Composição: 97% poliéster, 3% elastano Estrutura: Cinco painéis com ventilação a laser Fechamento: Tira aderente ajustável Aba: Curva e maleável Diferencial: Logo refletivo para maior visibilidade Peso do produto: 80g Produto Original: Autenticidade garantida pelas Lojas Radan.', 109.89, 109.89, NULL, 'Fashion Accessories > Hats & Caps', 'https://cf.shopee.com.br/file/sg-11134201-8262d-mm63sibmtj452f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1577790116%2F22294923399', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '25945560336', 'Tênis Infantil Menina Kidy K360 Retrô TEC-GEL Solado Antiderrapante Conforto Estilo Segurança', 'Tênis Infantil Kidy K360 Retrô Cinza e Rosa – Conforto, Estilo e Proteção no Dia a Dia O Tênis K360 Retrô Cinza e Rosa une estilo, conforto e tecnologia para acompanhar os passos das crianças com segurança e leveza. Seu solado em PVC é super leve, antiderrapante e resistente, ideal para proteger durante as brincadeiras do dia a dia. O fechamento em cadarço garante um ajuste firme e personalizado, proporcionando mais autonomia e praticidade. A palmilha com tecnologia TEC-GEL oferece excelente absorção de impacto, proporcionando conforto prolongado. Com formato anatômico, o modelo se adapta ao pé infantil, auxiliando no crescimento saudável. Uma escolha ideal para pais que buscam qualidade, proteção e bem-estar para seus filhos! 📏 Tabela de Medidas: 28 —------------------------------ 18,7 cm 29 —------------------------------ 19,3 cm 30 —------------------------------ 20,0 cm 31 —------------------------------ 20,7 cm 32 —------------------------------ 21,3 cm 33 —------------------------------ 22,0 cm 34 —------------------------------ 22,7 cm 35 —------------------------------ 23,3 cm 36 —------------------------------ 24,0 cm 🌟 Diferenciais do Produto: • Palmilha TEC-GEL: máximo conforto e absorção de impacto • Solado em PVC leve e antiderrapante • Formato anatômico que respeita o crescimento infantil 📌 Informações Técnicas: • Tamanhos: do 28 ao 36 • Fechamento: Cadarço • Cabedal: Têxtil • Forro: Têxtil • Palmilha: TEC-GEL • Sola: PVC Antiderrapante 🧼 Cuidados com o Produto: • Limpar com pano úmido e sabão neutro • Não deixar de molho • Secar à sombra, longe de fontes de calor 🧠 Formato Anatômico Sempre pensando na saúde e conforto das crianças, todos os calçados Kidy possuem formato anatômico, que auxilia no crescimento e desenvolvimento saudável dos pés. 🏪 Sobre a Kidy A Kidy é uma marca especialista em calçados infantis que une tecnologia, inovação e cuidado em cada detalhe. Criamos produtos que acompanham o crescimento das crianças com conforto, proteção e estilo. Nossa missão é oferecer soluções inteligentes para o dia a dia das famílias, sempre com muito carinho e atenção à saúde dos pezinhos em desenvolvimento.', 209.99, 179.99, NULL, 'Baby & Kids Fashion > Girl Shoes > Sneakers', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mb2k0ept5gqh0d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1045812437%2F25945560336', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
