INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23893612959', 'Bomba de Porão Seaflo 1100 1.100 GPH - 12v 3A Barco Lancha Jet', 'Bomba de Porão 1100 GPH SEAFLO 12V 3A A Bomba de Porão 1100 GPH 12V não automática de padrão CE, RoHS, ISO 8846 e ISO 8849 de aplicação marítima e operação silenciosa, é ideal para evacuação de água, possui sistema de proteção anti-airlock, vedações herméticas exclusivas, além da fiação possuir bloqueio em grau marítimo, eixo em aço inoxidável e base removível para fácil instalação, limpeza e manutenção. A Bomba de Porão 1100 GPH 12V pode ser ativada por painel ou interruptor de boia, sendo que esses produtos independentes. Aplicações: A Bomba de Porão 1100 GPH 12V deve ser utilizada para a drenagem de água, podendo ser utilizada em transferência e esgotamento de líquidos de água doce ou salgada, aquário grande, pequena piscina, reservatórios de água, fontes etc.. Áreas apropriadas para o uso: Construção naval, piscicultura, indústria, agricultura, medicina, economia doméstica e outras áreas. Instalação: Recomenda-se que para instalação da Bomba de Porão 1100 GPH 12V seja utilizado parafusos de aço inoxidável nº8 de comprimento adequado para a fixação da bomba, (Atenção para não perfurar o casco da embarcação). Para a instalação elétrica atentar-se a utilização de um Fusível para a segurança do seu Circuito Elétrico e lembre-se que o cabo de alimentação do motor nunca deve ser instalado tensionado (Esticado), o cabo deve sempre possui uma folga para evitar infiltrações por araste de água e desgastes no motor do produto. Configurações de funcionamento: A Bomba de Porão 1100 GPH 12V opera com a vazão de 1100 GPH ou 4164 L/h, sua capacidade de elevação pode atingir a 4,5 m porem a vazão altera conforme a altura de elevação aumenta. Características: Vazão: 1100 GPH - 4164 L/H Head: 4,5 M Tensão eletrica: 12 V Corrente Eletrica: 3,0 A Tamanho do Fusível: 5,0 A Eixo: Aço Inoxidavel Porta de saída: 1 1/8° (29mm) Comprimento do Cabo: 1,0 m Bitola do Cabo Elétrico: 18 AWG Dimensões: 70,4x108x100,7mm Peso: 0,35 Kg *imagens Ilustrativas* *Garantia 02 Anos*', 160.17, 144.16, NULL, 'Home & Living > Tools & Home Improvement > Water Pumps, Parts & Accessories', 'https://cf.shopee.com.br/file/sg-11134201-7rdw8-mbs7tzcph2qi2c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1006271683%2F23893612959', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
