INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '28933856458', 'Roupão de Banho Microfibra Soft Tamanho único Camesa', 'Roupão de Banho Microfibra Soft Tamanho Único Camesa Descubra o conforto e a elegância do Roupão de Microfibra Soft Camesa, perfeito para quem busca aconchego nos dias frios. Com toque extremamente macio, modelagem estilo quimono, mangas longas e bolsos frontais, ele é ideal para relaxar após o banho ou curtir momentos de descanso em casa. Principais Características: - Material: 100% Poliéster (Microfibra Soft) - Modelagem: Quimono com mangas compridas - Detalhes: Bolsos frontais e pendurador para maior praticidade - Produto Antialérgico: Suave para a pele, ideal para pessoas com sensibilidade cutânea - Tamanho Único: Veste diversos biotipos confortavelmente Medidas Aproximadas: - Comprimento: 1 metro - Largura: 52 cm (fechado) - Comprimento da Manga: 55 cm - Largura dos Ombros: 50 cm (de costura a costura) Conteúdo da Embalagem: - 1 Roupão Felpudo Microfibra Adulto Camesa (Tamanho Único) Por que escolher o Roupão de Microfibra Camesa? O Roupão de Microfibra Soft Camesa é a definição de conforto e sofisticação. Seu tecido felpudo e leve proporciona uma sensação acolhedora, enquanto sua modelagem versátil se ajusta perfeitamente ao corpo. Seja para relaxar após um banho quente ou para usar como loungewear, este roupão se torna um item indispensável no seu dia a dia. Presenteie-se ou presenteie quem você ama com esse toque de bem-estar. Adquira agora o seu Roupão de Microfibra Soft Camesa e experimente o melhor em conforto e estilo!', 89.9, 64.9, NULL, 'Home & Living > Bathrooms > Towels & Bathrobes', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m8p069z4co3m17', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F572649927%2F28933856458', NULL, NULL, '2026-07-28T02:11:31.708458