INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '50804663163', 'Refil Mop Ponta Cortada Algodão Branco 340g Kunber', 'Refil Mop Ponta Cortada Algodão Branco 340g Kunber - Mop ponta cortada 340g pode ser utilizado na limpeza geral e pesada, em conjunto com o balde espremedor - Composição do fio: 85% algodão e 15% poliéster (mais fibra, maior resistência mecânica e durabilidade ao fio) - Fios com maior percentual de fibras de poliéster e filamento interno promovem durabilidade superior, maior resistência a tração e menor perda de massa em uso comparado aos similares no mercado - Banda de costura (superior) em PVC resinado confere mais estabilidade e melhor fixação do mop no suporte - Devido as características da fibra de algodão, é indicado para áreas com maior ênfase na secagem de pisos e retenção de líquidos Gramatura: 340g Cor: Branco Compatível com: Cód.: 101297 - Suporte Plástico para Refil Mop Amarelo Kunber Cód. de Fábrica: 15305 Cód.: 101299 - Suporte Plástico para Refil Mop Úmido Vermelho Kunber Cód. de Fábrica: 15307 Cód.: 101298 - Suporte Plástico para Refil Mop Úmido Verde Kunber Cód. de Fábrica: 15306 Cód.: 101296 - Suporte Plástico para Refil Mop Úmido Azul Kunber Cód. de Fábrica: 15301 Cód.: 102404 - Conjunto Mop Úmido Azul com Cabo de Alumínio de 150cm Kunber Cód. de Fábrica: 15503 Embalagem: 01 unidade', 39.06, 39.06, NULL, 'Home & Living > Home Care Supplies > Mops', 'https://cf.shopee.com.br/file/sg-11134201-82612-mjh4nph27toga7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F946161700%2F50804663163', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '28992476459', 'Conector DC Jack para Notebook Dell Inspiron 14-5458-B08P', 'Conector DC Jack compatível com Dell Inspiron 14-5458-B08P Este é um DC Jack bringIT compatível com o notebook Dell Inspiron 14-5458-B08P. Ele é ideal para acabar com os problemas de alimentação de energia em um notebook. O DC Jack — ou DC Power Jack — é um conector interno responsável por intermediar a alimentação de energia entre a fonte (carregador) e o laptop. Este produto é um de alta qualidade e cumpre todas as especificações de segurança dos notebooks. Para evitar problemas de compatibilidade, compare as fotos deste anúncio com seu equipamento original. Assim você consegue verificar as principais informações de compatibilidade e demais especificações do seu notebook. Atenção: Esse é um dc jack bringIT, portanto não é um produto original da fabricante Dell. Caso seja necessário, todo o suporte e garantia do produto serão oferecidos pela nossa equipe. Informações Técnicas Tamanho do Conector: 4.5mm x 3.0mm Cabo: Com Cabo Garantia: 3 meses de garantia contra defeitos de fabricação Referência: DC112-DE-0120', 46.2, 43.89, NULL, 'Computers & Accessories > Desktop & Laptop Components > Others', 'https://cf.shopee.com.br/file/sg-11134201-8258e-mqs1cxpqkidd1f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F392651618%2F28992476459', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
