INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22793101443', 'Kit 2 Cx Tinta Guache Infantil Pote de 15ml Tempera 6 Cores Pintura Desenhos Lembrancinhas Infantil', 'TINTA GUACHE MULTICOR 6 CORES EM CADA CAIXA PARA PINTURA INFANTIL A Tinta Guache é ideal para dar um toque especial em suas lembrancinhas e brindes de festa. Com 6 cores vibrantes em cada embalagem, você terá muita variedade para soltar a criatividade. Cada unidade contém 15 ml de tinta, garantindo durabilidade e qualidade em cada aplicação. A tinta guache é um importante instrumento para o desenvolvimento da criatividade, coordenação motora e percepção visual das cores. Características: 6 cores com 15ml cada Lavável Cores miscíveis entre si Produto não tóxico e solúvel em água CORES: Amarelo, Verde, Preto, Branco, Azul e Vermelho (NAO É POSSIVEL ESCOLHER COR, CADA CAIXINHA VAI COM AS CORES DESCRITAS ACIMA) >> ATENÇÃO<< Quando utilizado para menores de 03 anos, deve haver supervisão de um adulto. Não personalizamos e nem fabricamos, todos os produtos vão sortidos, sem possibilidade de escolha de cor. Bolinha Magica, pequeno presente, GRANDE ALEGRIA!!', 18.58, 16.73, NULL, 'Stationery > Art Supplies > Water & Poster Colours', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lwrdybj4v45b8a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1045133925%2F22793101443', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23894190413', 'Máscara Lavanda Loiro Perfeito Cronograma Capilar 250g', 'A Máscara Loiro Lavanda Ybera Fashion Gold é o tratamento ideal para quem deseja manter o loiro frio e sofisticado. Sua fórmula tonalizante corrige o amarelado indesejado, neutralizando os reflexos quentes e preservando a luminosidade natural dos fios. Enriquecida com algas marinhas, óleo de jojoba e manteiga de manga, ela trata profundamente a fibra capilar, reduz a porosidade e combate as pontas duplas. A tintura de lavanda atua como antioxidante, protegendo a cor e mantendo o loiro vibrante por mais tempo. Benefícios principais: Neutraliza tons amarelados e oxidações Mantém o loiro frio, luminoso e sofisticado Repara danos e melhora a textura dos fios Reduz a porosidade e as pontas duplas Ação rápida em apenas 3 segundos Modo de uso: Após lavar com o Shampoo Luminoso, aplique mecha por mecha e enluve os fios. Deixe agir por 3 segundos para condicionamento ou 30 minutos para um tratamento intensivo. Enxágue bem.', 139.9, 139.9, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-822xc-mo7ag79hjtab7e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1350034564%2F23894190413', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
