INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19877394258', 'Kit De Acessórios de Micro Retífica para Vidro e Pedra 9pçs 735 - Dremel', 'Tire o máximo de suas ferramentas rotativas Dremel utilizando a nossa inovadora e extensa linha de acessórios rotativos e acessórios. Seja qual for o seu projeto, temos a solução perfeita para você. Os acessórios Dremel cabem dentro da sua ferramenta rotativa para aumentar a sua versatilidade. Este micro kit de acessórios de 8 peças é especialmente pensado para realizar todas as aplicações de vidro e pedra. Pretende: esculpir, gravar, cortar, lixar ou esmerilhar, existe um acessório Dremel para realizar o trabalho com grande precisão. Compatível com todas as ferramentas rotativas Dremel com e sem fio. Não há necessidade de procurar a pinça certa, todos os acessórios rotativos Dremel apresentam uma haste padrão de 1/8''''. Itens inclusos: - 02 Disco Impregnado De 25,4mm Para Ferro, Aço, Vidro, Cerâmica E Pedra (Modelo 425) - 01 Broca Diamantada De Ponta Dupla De 2,4mm E 1,6mm Para Vidro, Pedra E Cerâmica (Modelo 664DR) - 01 Haste Para Discos (Modelo 402) - 01 Ponta Diamantada Para Gravar De Ponta Redonda De 2mm Vidro, Cerâmica E Pedra (Modelo 7103) - 01 Ponta Diamantada Para Gravar De Ponta Fina De 2mm Para Vidro, Cerâmica E Pedra (Modelo 7134) - 01 Pedra Formato Chama De Fogo Para Esmerilhar De 7,1mm Para Vidro, Pedra, Cerâmica, Alumínio E Cobre (Modelo 83142) - 01 Pedra Formato Pera Para Esmerilhar De 4,8mm Para Vidro, Pedra, Cerâmica, Alumínio E Cobre E Gravar Em Vidro (Modelo 84922) - 01 Chave Especificações: - Dimensões: CxLxA: 10,16 x 5 x 15,24cm - Peso: 0,250 Kg - Kit especial de vidro e pedra para todas as aplicações - Vem com estojo de armazenamento reutilizável e 9 acessórios - A tampa transparente, o compartimento de armazenamento e a bandeja removível facilitam a localização dos acessórios - Pode empilhar facilmente, ficar em pé ou pendurar na parede com um gancho', 123.9, 123.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7qvfh-lf5tkh06xy4ob4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F674110767%2F19877394258', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
