INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22691408080', 'Espaguete Termo Retrátil Transparente 12mm c/ Cola - Cód.7840', 'Ideal pra proteção e isolação elétrica de fios e cabos com flexibilide no mercado elétrico, eletrônico, comunicação, automotivo e muitos outros. - Os espaguetes ou tubos termoencolhíveis servem para isolar com alta flexibilidade de conformação toda a extensão de barramentos retangulares ou redondos, inclusive em curvas. - Os Termocontráteis Transparentes ou Incolor são largamente utilizados em identificação de fiações e chicotes elétricos, além de servirem como capa protetora para etiquetas. - Com Cola (Resina) - Contração: 2:1 - Retardante de Chamas e Livre de Halogenos - Baixa Emissão de Fumaça - Resistente a Luz UV, Abrasão e a maioria dos solventes - Teperatura: -45 a 125° C (trabalho); 70º C (contração) - Certificações: RoHS / CSA / UL 224 **Valor referente ao metro**', 35.0, 35.0, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Electrical System', 'https://cf.shopee.com.br/file/sg-11134201-7rdxk-mcqerdlh39xcd1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F634548170%2F22691408080', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
