INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21497975108', 'Teclado Musical Arranjador Casio Ctk3500 61 Teclas Preto Estudante Iniciante', 'O Casio CTK-3500 é um teclado versátil, ideal para quem quer explorar a música de maneira intuitiva e prática. Com 61 teclas sensíveis ao toque, ele proporciona uma experiência próxima a de um piano, enquanto seus 400 timbres e 100 ritmos oferecem uma variedade de sons para inspirar criatividade em qualquer estilo musical. Suas 60 canções demo e o sistema de lições Step-Up tornam o aprendizado simples, permitindo desenvolver habilidades nas mãos esquerda e direita separadamente. Além disso, o CTK-3500 conta com modos como o Dance Music Mode e efeitos de reverb e transposição, que trazem mais profundidade à execução musical. É compatível com o aplicativo Chordana Play, que facilita o aprendizado, e vem equipado com conectividade USB Midi e entradas para microfone e pedal sustain, proporcionando ainda mais opções para prática e performance. Especificações: Teclado: 61 teclas sensíveis ao toque, estilo piano Polifonia: 48 vozes Timbres: 400 timbres integrados Ritmos: 100 ritmos integrados Canções Demo: 60 canções Funções Educacionais: Sistema de lições Step-Up, divididas por lições de mão esquerda e direita Efeitos Sonoros: Efeitos de reverb e transposição Modos: Função Dance Music Mode Funções: Sustain / Vibrato / Split / Metro / Gravação / Playback / Modo de Música de Dança / Aprendizado Step-Up Conectividade: Saída para fones de ouvido, USB Midi, entrada de áudio, entrada para microfone e pedal sustain Compatibilidade: Compatível com o aplicativo Chordana Play para expandir o aprendizado musical Alimentação: Fonte externa (inclusa) ou 6 pilhas AA Dimensões: 94,6 x 30,7 x 9,2 cm O que acompanha no Ctk3500 ? Itens: 1 Teclado Musical Ctk3500 1 Fonte Casio Original', 2319.9, 1494.9, NULL, 'Hobbies & Collections > Musical Instruments & Accessories > Keyboards & Pianos', 'https://cf.shopee.com.br/file/br-11134207-820lo-mny84ftzokci07', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F780674849%2F21497975108', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
