INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23694287463', 'Bóia Torpedo Pino Patinga 35g - Jr Pesca', 'A Bóia Torpedo Pino Patinga 35g da marca Jr Pesca é um produto de alta qualidade, perfeito para pescadores que utilizam carretilhas e molinetes e ideal para lançamento em grandes distâncias, o que facilita a captura de peixes de grande porte em pesqueiros. Este modelo conta com um girador em aço inox para amarrar a linha, proporcionando maior praticidade durante a pesca. Já na parte inferior, conta com um chumbo que facilita o arremesso a longas distâncias. O material de fabricação é uma combinação de metal, isopor e chumbo, garantindo resistência e flutuabilidade adequada. Essa boia é perfeita para pescadores que buscam qualidade e eficiência em suas pescarias. Atenção: Essa boia possui variação de cores, sendo necessário escolher o modelo desejado no ato da compra. Não perca tempo e garanta já sua Bóia Torpedo Pino Patinga 35g - Jr Pesca aqui na Dispropil!! Especificações Técnicas: - Marca: Jr Pesca - Modelo: Bóia Torpedo Pino Patinga 35g - Jr Pesca - Material: Metal, isopor e chumbo - Peso: 35g - Forma torpedo - Chumbo e Girador na ponta - Altura: 17cm Itens Inclusos: 01 - Bóia Torpedo Pino Patinga 35g - Jr Pesca', 25.9, 25.9, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Fishing', 'https://cf.shopee.com.br/file/sg-11134201-7rdyd-md0l8m59p00kda', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1063297286%2F23694287463', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
