INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22693345619', 'Pasta Catálogo com 50 Envelopes Finos Preto ACP – Porta Documentos A4 1un', 'Organize seus documentos com praticidade e elegância com a Pasta Catálogo ACP 122, modelo ideal para uso em escritórios, escolas, empresas e apresentações profissionais. Produzida com materiais de alta qualidade, esta pasta possui 50 envelopes plásticos finos e transparentes, perfeitos para guardar folhas no formato A4, mantendo-as protegidas contra sujeira, umidade e amassados. A capa rígida em polipropileno (PP) de cor preta oferece resistência e um visual moderno, ideal para quem busca durabilidade e aparência profissional. Os envelopes são fixos e proporcionam folhas de fácil visualização, ideais para catálogos, relatórios, apresentações, certificados ou portfólios. A Jandaia é uma das marcas mais tradicionais e reconhecidas do Brasil no segmento de papelaria. Com décadas de experiência no mercado, a empresa é referência em qualidade, inovação e design em produtos escolares, corporativos e de escritório.', 60.38, 60.38, NULL, 'Stationery > School & Office Equipment > Folders, Paper Organizers & Accessories', 'https://cf.shopee.com.br/file/sg-11134201-7rdvg-m0iy4chgd2iq64', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1306190243%2F22693345619', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23798066024', 'Violão Giannini N6 Bk Captador Passivo + Capa Acessórios', 'ACOMPANHA O KIT: 1) VIOLÃO GIANNINI N6-BK 2) CAPA ACOLCHOADA 3) 2 ROLDANAS 4) CABO P10 5M 5) CORREIA IBOX 6) CAPOTRASTE 7) 3 PALHETAS Com este violão infantil da Giannini, aprender a compor sons é fácil e divertido. Seu desenho e estilo são especialmente adaptados para melhorar a capacidade musical criativa. Feito á sua medida A tampa de tília tem um peso e densidade que lhe dão um som com mais corpo. Esta madeira tem um bom equilíbrio de graves, por isso soa com mais peso rítmico e um tom suave. Com suas 6 cordas você pode tocar diferentes peças sem se cansar, pois requer pouca pressão dos dedos. Qualidade se destaca As cordas de nylon são caracterizadas por serem flexíveis e resistentes. Garantem durabilidade e também têm um grande poder de absorção da carga de choque. Perfeito para você Com o formato classic aproveite ao máximo este instrumento, conseguindo um som muito limpo, pois é muito bem equilibrado entre agudos, médios e graves.', 595.65, 595.65, NULL, 'Hobbies & Collections > Musical Instruments & Accessories > String Instruments', 'https://cf.shopee.com.br/file/sg-11134201-7rfgk-m3dvn83slfh98e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F302241610%2F23798066024', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '48007004797', 'Escrivaninha de Estudos em L com 3 Gavetas Porto Multimóveis MP6045', 'A Escrivaninha de Estudos em L com 3 Gavetas Porto Multimóveis MP6045 é a escolha ideal para quem busca praticidade, organização e um visual moderno para o cantinho de estudos. Versátil e funcional, ela se adapta perfeitamente ao seu espaço, oferecendo excelente aproveitamento de área e soluções inteligentes para manter tudo sempre ao alcance das mãos. Diferenciais: - 3 anos de garantia contra defeitos de fabricação e material. - Produzida em madeira de reflorestamento (MDP 15mm): garante resistência e durabilidade. - Acabamento acetinado (cerca de 20% de brilho): proporciona facilidade na limpeza e visual elegante. - 4 opções de montagem: formato reto ou em L (canto), com a mesa à esquerda ou à direita do balcão. - 3 gavetas com corrediças metálicas: oferecem abertura suave e praticidade na organização dos seus itens. - 4 nichos externos ideais para livros, pastas, objetos decorativos ou materiais de estudo. - Tampo resistente (suporta até 10kg) para acomodar seu computador. - Pés retrô em polipropileno: agregam estabilidade, charme e personalidade ao móvel. - Puxadores em ABS: resistentes e modernos. Conteúdo da Embalagem: 1 (uma) Escrivaninha Manual de Montagem Kit Ferragem Dimensões do Produto Montado: Altura: 72cm | Largura: 136cm | Profundidade: 150cm *Você pode consultar as medidas detalhadas na imagem técnica do produto. *As cores do produto podem sofrer variações de tonalidade de acordo com as configurações do seu dispositivo. *Aqui na Loja Multimóveis, você pode concluir sua compra facilmente com toda segurança. A entrega é garantida e você está em 1° lugar. Imagem meramente ilustrativa. Decoração e eletrônicos não acompanham o produto. O produto será entregue desmontado e não disponibilizamos o serviço de montagem.', 669.99, 599.99, NULL, 'Home & Living > Furniture > Desks & Tables', 'https://cf.shopee.com.br/file/sg-11134201-8261r-mlmmokeemfwoec', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F308628919%2F48007004797', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
